window.ExtraBibleBooks=window.ExtraBibleBooks||{};window.ExtraBibleBooks["MRK"]={"book":"MRK","editions":{"dan-1819":[[1,1,"Jesu Christi, Guds Søns, Evangeliums Begyndelse var,","Jesu Christi, Guds Søns, Evangeliums Begyndelse var,"],[1,2,"ligesom skrevet er i Propheterne: see, jeg sender min Engel for dit Ansigt, som skal berede din Vei for dig.","ligesom skrevet er i Propheterne: see, jeg sender min Engel for dit Ansigt, som skal berede din Vei for dig."],[1,3,"Det er hans Røst, som raaber i Ørken: bereder Herrens Vei, gjører hans Stier jævne.","Det er hans Røst, som raaber i Ørken: bereder Herrens Vei, gjører hans Stier jævne."],[1,4,"Johannes døbte i Ørken og prædikede Omvendelsens Daab til Syndernes Forladelse.","Johannes døbte i Ørken og prædikede Omvendelsens Daab til Syndernes Forladelse."],[1,5,"Og det ganske Land Judæa gik ud til ham og de af Jerusalem, og de døbtes af ham i Jordans Flod, alle, som bekjendte deres Synder.","Og det ganske Land Judæa gik ud til ham og de af Jerusalem, og de døbtes af ham i Jordans Flod, alle, som bekjendte deres Synder."],[1,6,"Men Johannes havde Klæder af Kameelhaar og et Læderbælte om sin Lænd, og aad Græshopper og vild Honning.","Men Johannes havde Klæder af Kameelhaar og et Læderbælte om sin Lænd, og aad Græshopper og vild Honning."],[1,7,"og prædikede og sagde: der kommer den efter mig, som er stærkere end jeg, for hvem jeg ikke er værdig til at bukke mig ned, at løse hans Skotvinge.","og prædikede og sagde: der kommer den efter mig, som er stærkere end jeg, for hvem jeg ikke er værdig til at bukke mig ned, at løse hans Skotvinge."],[1,8,"Vel har jeg døbt Eder med Vand, men han skal døbe Eder med den Hellig Aand.","Vel har jeg døbt Eder med Vand, men han skal døbe Eder med den Hellig Aand."],[1,9,"Og det skete i de samme Dage, at Jesus kom fra Nazareth i Galilæa, og døbtes af Johannes i Jordan.","Og det skete i de samme Dage, at Jesus kom fra Nazareth i Galilæa, og døbtes af Johannes i Jordan."],[1,10,"Og strax, der han steg op af Vandet, saae han Himlene adskilte, og Aanden ligesom en Due komme ned over ham.","Og strax, der han steg op af Vandet, saae han Himlene adskilte, og Aanden ligesom en Due komme ned over ham."],[1,11,"Og der skete en Røst fra Himlene: du er min Søn, den Elskelige, i hvilken jeg haver Behagelighed.","Og der skete en Røst fra Himlene: du er min Søn, den Elskelige, i hvilken jeg haver Behagelighed."],[1,12,"Og strax drev Aanden ham ud i Ørken.","Og strax drev Aanden ham ud i Ørken."],[1,13,"Og han var der i Ørken fyrretyve Dage, og blev fristet af Satan, og var blandt Dyrene; og Englene tjente ham.","Og han var der i Ørken fyrretyve Dage, og blev fristet af Satan, og var blandt Dyrene; og Englene tjente ham."],[1,14,"Men efterat Johannes var kastet i Fængsel, kom Jesus til Galilæa, og prædikede Guds Riges Evangelium,","Men efterat Johannes var kastet i Fængsel, kom Jesus til Galilæa, og prædikede Guds Riges Evangelium,"],[1,15,"og sagde: Tiden er fuldkommet, og Guds Rige er nær; omvender Eder og troer paa Evangelium.","og sagde: Tiden er fuldkommet, og Guds Rige er nær; omvender Eder og troer paa Evangelium."],[1,16,"Men der han vandrede ved den galilæiske Sø, saae han Simon og hans Broder Andreas, at de kastede Garn i Søen, (thi de vare Fiskere).","Men der han vandrede ved den galilæiske Sø, saae han Simon og hans Broder Andreas, at de kastede Garn i Søen, (thi de vare Fiskere)."],[1,17,"Og Jesus sagde til dem: følger efter mig, saa vil jeg gjøre Eder til Menneske-Fiskere.","Og Jesus sagde til dem: følger efter mig, saa vil jeg gjøre Eder til Menneske-Fiskere."],[1,18,"Og de forlode strax deres Garn og fulgte ham.","Og de forlode strax deres Garn og fulgte ham."],[1,19,"Og da han gik lidet frem derfra, saae han Jakobus, Zebedæus’ Søn, og hans Broder Johannes, at ogsaa de bødte deres Garn i Skibet;","Og da han gik lidet frem derfra, saae han Jakobus, Zebedæus’ Søn, og hans Broder Johannes, at ogsaa de bødte deres Garn i Skibet;"],[1,20,"og han kaldte strax ad dem, og de forlode deres Fader Zebedæus i Skibet med Leiesvendene, og gik efter ham.","og han kaldte strax ad dem, og de forlode deres Fader Zebedæus i Skibet med Leiesvendene, og gik efter ham."],[1,21,"Og de gik ind i Capernaum, og strax paa Sabbaten gik han ind i Synagogen og lærte,","Og de gik ind i Capernaum, og strax paa Sabbaten gik han ind i Synagogen og lærte,"],[1,22,"og de forundrede sig saare paa hans Lærdom; thi han lærte dem, som den, der havde Myndighed, og ikke som de Skriftkloge.","og de forundrede sig saare paa hans Lærdom; thi han lærte dem, som den, der havde Myndighed, og ikke som de Skriftkloge."],[1,23,"Og der var et Menneske i deres Synagoge med en ureen Aand, og han raabte høit,","Og der var et Menneske i deres Synagoge med en ureen Aand, og han raabte høit,"],[1,24,"og sagde: ak! hvad have vi med dig at skaffe, Jesus af Nazareth? er du kommen at fordærve os? jeg kjender dig, hvo du er, den Guds Hellige.","og sagde: ak! hvad have vi med dig at skaffe, Jesus af Nazareth? er du kommen at fordærve os? jeg kjender dig, hvo du er, den Guds Hellige."],[1,25,"Og Jesus truede ham og sagde: ti, og far ud af ham!","Og Jesus truede ham og sagde: ti, og far ud af ham!"],[1,26,"Og den urene Aand sled ham, og raabte med stor Røst, og foer ud af ham.","Og den urene Aand sled ham, og raabte med stor Røst, og foer ud af ham."],[1,27,"Og de bleve alle forfærdede, saa at de bespurgte sig med hverandre og sagde: hvad er dette? hvad er denne for en ny Lærdom? thi han byder og de urene Aander med Magt, og de lyde ham.","Og de bleve alle forfærdede, saa at de bespurgte sig med hverandre og sagde: hvad er dette? hvad er denne for en ny Lærdom? thi han byder og de urene Aander med Magt, og de lyde ham."],[1,28,"Men hans Rygte kom strax ud i alt det omkringliggende Land i Galilæa.","Men hans Rygte kom strax ud i alt det omkringliggende Land i Galilæa."],[1,29,"Og de gik strax ud af Synagogen, og kom i Simons og Andreas’ Huus, med Jakobus og Johannes.","Og de gik strax ud af Synagogen, og kom i Simons og Andreas’ Huus, med Jakobus og Johannes."],[1,30,"Men Simons Hustrus Moder laae og havde Feber, og strax sagde de ham om hende:","Men Simons Hustrus Moder laae og havde Feber, og strax sagde de ham om hende:"],[1,31,"og han gik til hende, tog fat paa hendes Haand og reiste hende op, og Feberen forlod hende strax, og hun gik dem tilhaande.","og han gik til hende, tog fat paa hendes Haand og reiste hende op, og Feberen forlod hende strax, og hun gik dem tilhaande."],[1,32,"Men der det var blevet Aften, der Solen var nedgangen, førte de alle, som vare syge, og de Besatte til ham,","Men der det var blevet Aften, der Solen var nedgangen, førte de alle, som vare syge, og de Besatte til ham,"],[1,33,"og den ganske Stad var forsamlet for Døren.","og den ganske Stad var forsamlet for Døren."],[1,34,"Og han helbredte Mange, som lede af mangehaande Sygdomme, og uddrev mange Djævle, og lod Djævelene ikke tale; thi de kjendte ham.","Og han helbredte Mange, som lede af mangehaande Sygdomme, og uddrev mange Djævle, og lod Djævelene ikke tale; thi de kjendte ham."],[1,35,"Og om Morgenen, længe før Dag, stod han op og gik ud og gik hen til et øde Sted, og bad der.","Og om Morgenen, længe før Dag, stod han op og gik ud og gik hen til et øde Sted, og bad der."],[1,36,"Og Simon og de, som vare med ham, skyndte sig efter ham.","Og Simon og de, som vare med ham, skyndte sig efter ham."],[1,37,"Og der de fandt ham, sagde de til ham: Alle lede efter dig.","Og der de fandt ham, sagde de til ham: Alle lede efter dig."],[1,38,"Og han sagde til dem: lader os gaae til de nærmeste Smaastæder, at jeg og der kan prædike, thi dertil er jeg kommen.","Og han sagde til dem: lader os gaae til de nærmeste Smaastæder, at jeg og der kan prædike, thi dertil er jeg kommen."],[1,39,"Og han prædikede i deres Synagoger udi al Galilæa, og uddrev Djævle.","Og han prædikede i deres Synagoger udi al Galilæa, og uddrev Djævle."],[1,40,"Og der kom en Spedalsk til ham, bad ham, og faldt paa Knæ for ham, og sagde til ham: dersom du vil, kan du rense mig.","Og der kom en Spedalsk til ham, bad ham, og faldt paa Knæ for ham, og sagde til ham: dersom du vil, kan du rense mig."],[1,41,"Men Jesus ynkedes inderligen, og udrakte Haanden og rørte ved ham, og sagde til ham: jeg vil; vorde reen!","Men Jesus ynkedes inderligen, og udrakte Haanden og rørte ved ham, og sagde til ham: jeg vil; vorde reen!"],[1,42,"Og da han det sagde, gik Spedalskheden strax af ham, og han blev renset.","Og da han det sagde, gik Spedalskheden strax af ham, og han blev renset."],[1,43,"Og han drev ham strax fra sig, idet han bød ham strengeligen,","Og han drev ham strax fra sig, idet han bød ham strengeligen,"],[1,44,"og sagde til ham: see til, at du siger Ingen Noget herom; men gak hen, besee dig for Præsten, og offre for din Renselse det, som Moses haver befalet, dem til et Vidnesbyrd.","og sagde til ham: see til, at du siger Ingen Noget herom; men gak hen, besee dig for Præsten, og offre for din Renselse det, som Moses haver befalet, dem til et Vidnesbyrd."],[1,45,"Men der han kom ud, begyndte han at fortælle Meget derom og udspredte Rygtet om denne Sag, saa at han ikke mere kunde gaae aabenbare ind i en Stad; men han var udenfor paa øde Steder, og allevegnefra kom de til ham.","Men der han kom ud, begyndte han at fortælle Meget derom og udspredte Rygtet om denne Sag, saa at han ikke mere kunde gaae aabenbare ind i en Stad; men han var udenfor paa øde Steder, og allevegnefra kom de til ham."],[2,1,"Og nogle Dage derefter gik han atter ind i Capernaum, og der spurgtes, at han var hjemme.","Og nogle Dage derefter gik han atter ind i Capernaum, og der spurgtes, at han var hjemme."],[2,2,"Og strax forsamledes Mange, saa at de ikke havde Rum, end ikke for Døren; og han talede Ordet til dem.","Og strax forsamledes Mange, saa at de ikke havde Rum, end ikke for Døren; og han talede Ordet til dem."],[2,3,"Og Nogle kom til ham, som bragte en Værkbruden, der blev baaren af Fire.","Og Nogle kom til ham, som bragte en Værkbruden, der blev baaren af Fire."],[2,4,"Og der de ikke kunde komme nær til ham for Folket, toge de Taget af, hvor han var; og da de havde brudt Hul, lode de Sengen ned, paa hvilken den Værkbrudne laae.","Og der de ikke kunde komme nær til ham for Folket, toge de Taget af, hvor han var; og da de havde brudt Hul, lode de Sengen ned, paa hvilken den Værkbrudne laae."],[2,5,"Men der Jesus saae deres Tro, sagde han til den Værkbrudne: Søn! dine Synder ere dig forladne.","Men der Jesus saae deres Tro, sagde han til den Værkbrudne: Søn! dine Synder ere dig forladne."],[2,6,"Men nogle af de Skriftkloge sadde der, og de tænkte i deres Hjerter:","Men nogle af de Skriftkloge sadde der, og de tænkte i deres Hjerter:"],[2,7,"hvi taler denne saadanne Bespottelser? Hvo kan forlade Synder uden Een, det er Gud?","hvi taler denne saadanne Bespottelser? Hvo kan forlade Synder uden Een, det er Gud?"],[2,8,"Og Jesus kjendte strax i sin Aand, at de tænkte saa ved sig selv, og sagde til dem: hvi tænke I Saadant i Eders Hjerter?","Og Jesus kjendte strax i sin Aand, at de tænkte saa ved sig selv, og sagde til dem: hvi tænke I Saadant i Eders Hjerter?"],[2,9,"Hvilket er lettere, at sige til den Værkbrudne: Synderne ere dig forladne? eller at sige: staa op, og tag din Seng, og vandre?","Hvilket er lettere, at sige til den Værkbrudne: Synderne ere dig forladne? eller at sige: staa op, og tag din Seng, og vandre?"],[2,10,"Men at I skulle vide, at Menneskens Søn haver Magt at forlade Synder paa Jorden, (sagde han til den Værkbrudne):","Men at I skulle vide, at Menneskens Søn haver Magt at forlade Synder paa Jorden, (sagde han til den Værkbrudne):"],[2,11,"jeg siger dig: staa op, og tag din Seng, og gak til dit Huus.","jeg siger dig: staa op, og tag din Seng, og gak til dit Huus."],[2,12,"Og han stod strax op, og tog Sengen, og gik ud for Alles Øine, saa de bleve alle forfærdede og prisede Gud og sagde: vi have aldrig seet Saadant.","Og han stod strax op, og tog Sengen, og gik ud for Alles Øine, saa de bleve alle forfærdede og prisede Gud og sagde: vi have aldrig seet Saadant."],[2,13,"Og han gik ud igjen til Søen, og alt Folket kom til ham, og han lærte dem.","Og han gik ud igjen til Søen, og alt Folket kom til ham, og han lærte dem."],[2,14,"Og der han gik frem, saae han Levi, Alphæus’ Søn, siddende i Toldboden, og sagde til ham: følg mig. Og han stod op og fulgte ham.","Og der han gik frem, saae han Levi, Alphæus’ Søn, siddende i Toldboden, og sagde til ham: følg mig. Og han stod op og fulgte ham."],[2,15,"Og det begav sig, der han sad tilbords i hans Huus, satte og mange Toldere og Syndere sig tilbords med Jesus og hans Disciple; thi de vare mange og havde fulgt ham.","Og det begav sig, der han sad tilbords i hans Huus, satte og mange Toldere og Syndere sig tilbords med Jesus og hans Disciple; thi de vare mange og havde fulgt ham."],[2,16,"Og der de Skriftkloge og Pharisæerne saae, at han aad med Toldere og Syndere, sagde de til hans Disciple; hvad er det, at han æder og drikker med Toldere og Syndere?","Og der de Skriftkloge og Pharisæerne saae, at han aad med Toldere og Syndere, sagde de til hans Disciple; hvad er det, at han æder og drikker med Toldere og Syndere?"],[2,17,"Og der Jesus det hørte, sagde han til dem: de Karske have ikke Læge behov, men de, som have ondt. Jeg er ikke kommen at kalde Retfærdige, men Syndere til Omvendelse.","Og der Jesus det hørte, sagde han til dem: de Karske have ikke Læge behov, men de, som have ondt. Jeg er ikke kommen at kalde Retfærdige, men Syndere til Omvendelse."],[2,18,"Og Johannes’ Disciple og Pharisæerne fastede, og de kom og sagde til ham: hvorfor faste Johannes’ Disciple og Pharisæernes, men dine Disciple faste ikke?","Og Johannes’ Disciple og Pharisæerne fastede, og de kom og sagde til ham: hvorfor faste Johannes’ Disciple og Pharisæernes, men dine Disciple faste ikke?"],[2,19,"Og Jesus sagde til ham: mon Bryllupsfolkene kunne faste, den Stund Brudgommen er hos dem? Saalænge de have Brudgommen hos sig, kunne de ikke faste.","Og Jesus sagde til ham: mon Bryllupsfolkene kunne faste, den Stund Brudgommen er hos dem? Saalænge de have Brudgommen hos sig, kunne de ikke faste."],[2,20,"Men de Dage skulle komme, da Brudgommen skal tages fra dem, og da skulle de faste i de Dage.","Men de Dage skulle komme, da Brudgommen skal tages fra dem, og da skulle de faste i de Dage."],[2,21,"Og Ingen bøder et gammelt Klædebon med en Klud af nyt Klæde, ellers river den nye Klud noget af det gamle, og Hullet bliver værre.","Og Ingen bøder et gammelt Klædebon med en Klud af nyt Klæde, ellers river den nye Klud noget af det gamle, og Hullet bliver værre."],[2,22,"Og Ingen lader ny Viin i gamle Læderflasker, ellers sprænger den nye Viin Læderflaskerne, og Vinen spildes, og Læderflaskerne fordærves; men man skal lade ny Viin i nye Læderflasker.","Og Ingen lader ny Viin i gamle Læderflasker, ellers sprænger den nye Viin Læderflaskerne, og Vinen spildes, og Læderflaskerne fordærves; men man skal lade ny Viin i nye Læderflasker."],[2,23,"Og det begav sig, at han vandrede paa Sabbaten gennem Sæden, og hans Disciple begyndte, idet de gik, at plukke Ax.","Og det begav sig, at han vandrede paa Sabbaten gennem Sæden, og hans Disciple begyndte, idet de gik, at plukke Ax."],[2,24,"Og Pharisæerne sagde til ham: see, hvorfor gjøre de paa Sabbaten, hvad ikke er tilladt?","Og Pharisæerne sagde til ham: see, hvorfor gjøre de paa Sabbaten, hvad ikke er tilladt?"],[2,25,"Og han sagde til dem: have I aldrig læst hvad David gjorde, der han havde det behov, og selv hungrede og de, som vare med ham?","Og han sagde til dem: have I aldrig læst hvad David gjorde, der han havde det behov, og selv hungrede og de, som vare med ham?"],[2,26,"Hvorledes han gik ind i Guds Huus, da Abiathar var Ypperstepræst, og aad Skuebrødene, hvilke det ikke er Nogen tilladt at æde uden Præsterne, og gav ogsaa dem, som vare med ham?","Hvorledes han gik ind i Guds Huus, da Abiathar var Ypperstepræst, og aad Skuebrødene, hvilke det ikke er Nogen tilladt at æde uden Præsterne, og gav ogsaa dem, som vare med ham?"],[2,27,"Og han sagde til dem: Sabbaten blev til for Menneskets Skyld, ikke Mennesket for Sabbatens Skyld.","Og han sagde til dem: Sabbaten blev til for Menneskets Skyld, ikke Mennesket for Sabbatens Skyld."],[2,28,"Saaledes er Menneskens Søn en Herre ogsaa over Sabbaten.","Saaledes er Menneskens Søn en Herre ogsaa over Sabbaten."],[3,1,"Og han gik atter ind i Synagogen, og der var et Menneske, som havde en vissen Haand.","Og han gik atter ind i Synagogen, og der var et Menneske, som havde en vissen Haand."],[3,2,"Og de toge vare paa ham, om han vilde helbrede ham paa Sabbaten, paa det de kunde anklage ham.","Og de toge vare paa ham, om han vilde helbrede ham paa Sabbaten, paa det de kunde anklage ham."],[3,3,"Og han sagde til det Menneske, som havde den visne Haand: træd frem her i Midten.","Og han sagde til det Menneske, som havde den visne Haand: træd frem her i Midten."],[3,4,"Og han sagde til ham: er det tilladt at gjøre godt paa Sabbaten, eller gjøre ondt? frelse et Liv, eller slaae ihjel? Men de taug.","Og han sagde til ham: er det tilladt at gjøre godt paa Sabbaten, eller gjøre ondt? frelse et Liv, eller slaae ihjel? Men de taug."],[3,5,"Og han saae omkring paa dem med Vrede, bedrøvet over deres Hjerters Forhærdelse, og sagde til Mennesket: ræk din Haand ud! og han rakte den ud; og hans Haand blev karsk igjen som den anden.","Og han saae omkring paa dem med Vrede, bedrøvet over deres Hjerters Forhærdelse, og sagde til Mennesket: ræk din Haand ud! og han rakte den ud; og hans Haand blev karsk igjen som den anden."],[3,6,"Og Pharisæerne gik ud og holdt strax Raad med de Herodianer mod ham, hvorledes de kunde omkomme ham.","Og Pharisæerne gik ud og holdt strax Raad med de Herodianer mod ham, hvorledes de kunde omkomme ham."],[3,7,"Og Jesus veg hen med sine Disciple til Søen, og en stor Mængde fulgte ham fra Galilæa og fra Judæa,","Og Jesus veg hen med sine Disciple til Søen, og en stor Mængde fulgte ham fra Galilæa og fra Judæa,"],[3,8,"og fra Jerusalem og fra Idumæa og hiin Side Jordan, og de ved Tyrus og Sidon, en stor Mængde, som hørte, hvor store Gjerninger han gjorde, kom til ham.","og fra Jerusalem og fra Idumæa og hiin Side Jordan, og de ved Tyrus og Sidon, en stor Mængde, som hørte, hvor store Gjerninger han gjorde, kom til ham."],[3,9,"Og han sagde til sine Disciple, at et lidet Skib skulle være tilrede fra ham, for Folkets Skyld, at de ikke skulde trænge ham.","Og han sagde til sine Disciple, at et lidet Skib skulle være tilrede fra ham, for Folkets Skyld, at de ikke skulde trænge ham."],[3,10,"Thi han helbredte Mange, saa at Alle, som havde Plager, styrtede ind paa ham, at de kunde røre ved ham.","Thi han helbredte Mange, saa at Alle, som havde Plager, styrtede ind paa ham, at de kunde røre ved ham."],[3,11,"Og naar de urene Aander saae ham, faldt de ned for ham, og raabte og sagde: du er den Guds Søn.","Og naar de urene Aander saae ham, faldt de ned for ham, og raabte og sagde: du er den Guds Søn."],[3,12,"Og han truede dem strengeligen, at de ikke skulde sige, hvo han var.","Og han truede dem strengeligen, at de ikke skulde sige, hvo han var."],[3,13,"Og han gik op paa et Bjerg, og kaldte til sig, hvilke han selv vilde; og de gik hen til ham.","Og han gik op paa et Bjerg, og kaldte til sig, hvilke han selv vilde; og de gik hen til ham."],[3,14,"Og han beskikkede Tolv, at de skulde være hos ham, og at han kunde udsende dem at prædike,","Og han beskikkede Tolv, at de skulde være hos ham, og at han kunde udsende dem at prædike,"],[3,15,"og at have Magt til at helbrede Sygdomme og til at uddrive Djævle:","og at have Magt til at helbrede Sygdomme og til at uddrive Djævle:"],[3,16,"Simon, hvem han tillagde det Navn Petrus;","Simon, hvem han tillagde det Navn Petrus;"],[3,17,"og Jakob, Zebedæus’ Søn, og Johannes, Jakobs Broder, hvilke han tillagde Navnet Boanerges, det er Tordensønner;","og Jakob, Zebedæus’ Søn, og Johannes, Jakobs Broder, hvilke han tillagde Navnet Boanerges, det er Tordensønner;"],[3,18,"og Andreas og Philippus, og Bartholomæus, og Matthæus, og Thomas, og Jakob, Alphæus’ Søn, og Thaddæus, og Simon Cananites,","og Andreas og Philippus, og Bartholomæus, og Matthæus, og Thomas, og Jakob, Alphæus’ Søn, og Thaddæus, og Simon Cananites,"],[3,19,"og Judas Ischariotes, som og forraadte ham.","og Judas Ischariotes, som og forraadte ham."],[3,20,"Og de kom til Huset, og Folket samledes atter, saa at de end ikke kunde faae Mad.","Og de kom til Huset, og Folket samledes atter, saa at de end ikke kunde faae Mad."],[3,21,"Og de, som vare omkring ham, hørte det, gik de ud for at drage ham til sig; thi de sagde: han er afmægtig.","Og de, som vare omkring ham, hørte det, gik de ud for at drage ham til sig; thi de sagde: han er afmægtig."],[3,22,"Og de Skriftkloge, som vare komne ned fra Jerusalem, sagde: han haver Beelzebul, og ved den øverste Djævel uddriver han Djævle.","Og de Skriftkloge, som vare komne ned fra Jerusalem, sagde: han haver Beelzebul, og ved den øverste Djævel uddriver han Djævle."],[3,23,"Og han kaldte dem til sig, og sagde til dem i Lignelser: hvorledes kan en Satan uddrive den anden?","Og han kaldte dem til sig, og sagde til dem i Lignelser: hvorledes kan en Satan uddrive den anden?"],[3,24,"Og dersom et Rige bliver splidagtigt med sig selv, kan samme Rige ikke bestaae.","Og dersom et Rige bliver splidagtigt med sig selv, kan samme Rige ikke bestaae."],[3,25,"Og dersom et Huus bliver splidagtigt med sig selv, kan samme Huus ikke bestaae.","Og dersom et Huus bliver splidagtigt med sig selv, kan samme Huus ikke bestaae."],[3,26,"Og dersom Satan haver sat sig op imod sig selv, og er bleven splidagtig, kan han ikke bestaae, men det er ude med ham.","Og dersom Satan haver sat sig op imod sig selv, og er bleven splidagtig, kan han ikke bestaae, men det er ude med ham."],[3,27,"Der kan jo Ingen gaae ind i den Stærkes Huus og røve hans Redskab, uden han først binder den Stærke, og da kan han plyndre hans Huus.","Der kan jo Ingen gaae ind i den Stærkes Huus og røve hans Redskab, uden han først binder den Stærke, og da kan han plyndre hans Huus."],[3,28,"Sandelig siger jeg Eder: alle Synder kunne forlades Menneskens Børn, ogsaa Bespottelser, hvor store Bespottelser de end tale;","Sandelig siger jeg Eder: alle Synder kunne forlades Menneskens Børn, ogsaa Bespottelser, hvor store Bespottelser de end tale;"],[3,29,"men hvo som taler bespottelig mod den Hellig Aand, haver ingen Forladelse evindelig, men er skyldig til en evig Dom.","men hvo som taler bespottelig mod den Hellig Aand, haver ingen Forladelse evindelig, men er skyldig til en evig Dom."],[3,30,"Thi de havde sagt: han haver en ureen Aand.","Thi de havde sagt: han haver en ureen Aand."],[3,31,"Da kom hans Brødre og Moder, og stode udenfor og sendte til ham og lode ham kalde.","Da kom hans Brødre og Moder, og stode udenfor og sendte til ham og lode ham kalde."],[3,32,"Og Folket sad omkring, men de sagde til ham: see, din Moder og dine Brødre udenfor spørge efter dig.","Og Folket sad omkring, men de sagde til ham: see, din Moder og dine Brødre udenfor spørge efter dig."],[3,33,"Og han svarede dem og sagde: hvo er min Moder, eller mine Brødre?","Og han svarede dem og sagde: hvo er min Moder, eller mine Brødre?"],[3,34,"Og han saae trindt omkring paa dem, som sadde om ham og sagde: see, min Moder og mine Brødre.","Og han saae trindt omkring paa dem, som sadde om ham og sagde: see, min Moder og mine Brødre."],[3,35,"Thi hvo som gjør Guds Villie, denne er min Broder og min Søster og Moder.","Thi hvo som gjør Guds Villie, denne er min Broder og min Søster og Moder."],[4,1,"Og han begyndte atter at lære ved Søen, og meget Folk forsamledes til ham, saa at han maatte træde ind og sætte sig i et Skib paa Søen; og alt Folket var paa Landet ved Søen.","Og han begyndte atter at lære ved Søen, og meget Folk forsamledes til ham, saa at han maatte træde ind og sætte sig i et Skib paa Søen; og alt Folket var paa Landet ved Søen."],[4,2,"Og han lærte dem meget ved Lignelser og sagde til dem i sin Underviisning:","Og han lærte dem meget ved Lignelser og sagde til dem i sin Underviisning:"],[4,3,"Hører til! see, en Sædemand gik ud at saae.","Hører til! see, en Sædemand gik ud at saae."],[4,4,"Og det skete, idet han saaede, at Noget faldt ved Veien, og Himmelens Fugle kom og aade det op.","Og det skete, idet han saaede, at Noget faldt ved Veien, og Himmelens Fugle kom og aade det op."],[4,5,"Men Noget faldt paa Steengrund, hvor det havde ikke megen Jord; og det voxte snart op, fordi det ikke havde dyb Jord.","Men Noget faldt paa Steengrund, hvor det havde ikke megen Jord; og det voxte snart op, fordi det ikke havde dyb Jord."],[4,6,"Men der Solen gik op, blev det forbrændt, og efterdi det ikke havde Rod, visnede det.","Men der Solen gik op, blev det forbrændt, og efterdi det ikke havde Rod, visnede det."],[4,7,"Og Noget faldt iblandt Torne; og Tornene voxte op og kvalte det, og det bar ikke Frugt.","Og Noget faldt iblandt Torne; og Tornene voxte op og kvalte det, og det bar ikke Frugt."],[4,8,"Og Noget faldt i god Jord og bar Frugt, som voxte op og blev stor; og Noget bar tredive Fold, og Noget tresindstyve Fold, og Noget Hundrede Fold.","Og Noget faldt i god Jord og bar Frugt, som voxte op og blev stor; og Noget bar tredive Fold, og Noget tresindstyve Fold, og Noget Hundrede Fold."],[4,9,"Og han sagde til dem: hvo som haver Øren at høre med, han høre!","Og han sagde til dem: hvo som haver Øren at høre med, han høre!"],[4,10,"Men der han var alene, spurgte de, som vare om ham, tilligemed de Tolv, ham om Lignelsen.","Men der han var alene, spurgte de, som vare om ham, tilligemed de Tolv, ham om Lignelsen."],[4,11,"Og han sagde til dem: Eder er det givet, at vide Guds Riges Hemmelighed; med dem, som ere udenfor, meddeles Alt ved Lignelser;","Og han sagde til dem: Eder er det givet, at vide Guds Riges Hemmelighed; med dem, som ere udenfor, meddeles Alt ved Lignelser;"],[4,12,"at de see med Øinene, og ikke skjønne, og høre med Ørene, og ikke forstaae; at de ingenlunde omvende sig, og Synderne forlades dem.","at de see med Øinene, og ikke skjønne, og høre med Ørene, og ikke forstaae; at de ingenlunde omvende sig, og Synderne forlades dem."],[4,13,"Og han sagde til dem: forstaae I ikke denne Lignelse? hvorledes ville I da forstaae alle de andre Lignelser?","Og han sagde til dem: forstaae I ikke denne Lignelse? hvorledes ville I da forstaae alle de andre Lignelser?"],[4,14,"Den, som saaer, saaer Ordet.","Den, som saaer, saaer Ordet."],[4,15,"Men de ved Veien ere de, hvor Ordet bliver saaet, og naar de have hørt det, kommer strax Satan, og tager Ordet bort, som var saaet i deres Hjerter.","Men de ved Veien ere de, hvor Ordet bliver saaet, og naar de have hørt det, kommer strax Satan, og tager Ordet bort, som var saaet i deres Hjerter."],[4,16,"Og ligeledes de, som fik Sæden paa Steengrund, ere de, som naar de have hørt Ordet, annamme det strax med Glæde;","Og ligeledes de, som fik Sæden paa Steengrund, ere de, som naar de have hørt Ordet, annamme det strax med Glæde;"],[4,17,"dog have de ingen Rod i sig, men blive ved til en Tid; naar siden Trængsel eller Forfølgelse skeer for Ordets Skyld, forarges de strax.","dog have de ingen Rod i sig, men blive ved til en Tid; naar siden Trængsel eller Forfølgelse skeer for Ordets Skyld, forarges de strax."],[4,18,"Og de, som fik Sæden blandt Torne, ere de, som høre Ordet;","Og de, som fik Sæden blandt Torne, ere de, som høre Ordet;"],[4,19,"og denne Verdens Bekymringer og Rigdommens Forførelse og Begjerligheder efter de andre Ting trænge ind og kvæle Ordet, saa det bliver uden Frugt.","og denne Verdens Bekymringer og Rigdommens Forførelse og Begjerligheder efter de andre Ting trænge ind og kvæle Ordet, saa det bliver uden Frugt."],[4,20,"Og de, der fik Sæden i god Jord, ere de, som høre Ordet og annamme det, og bære Frugt, Endeel tredive Fold, Endeel tresindstyve Fold, og Endeel hundrede Fold.","Og de, der fik Sæden i god Jord, ere de, som høre Ordet og annamme det, og bære Frugt, Endeel tredive Fold, Endeel tresindstyve Fold, og Endeel hundrede Fold."],[4,21,"Og han sagde til dem: kommer Lyset ind, for at sættes under Skjeppen eller under Bordet? monne ikke, for at sættes paa Lysestagen?","Og han sagde til dem: kommer Lyset ind, for at sættes under Skjeppen eller under Bordet? monne ikke, for at sættes paa Lysestagen?"],[4,22,"Thi Intet er skjult, som jo skal aabenbares: ei heller skeer det lønligt, men for at komme til Lyset.","Thi Intet er skjult, som jo skal aabenbares: ei heller skeer det lønligt, men for at komme til Lyset."],[4,23,"Dersom Nogen haver Øren at høre med, han høre!","Dersom Nogen haver Øren at høre med, han høre!"],[4,24,"Og han sagde til dem: agter paa, hvad I høre: med hvad Maade I maale, skal Eder maales, og Eder, som høre, skal end gives Mere.","Og han sagde til dem: agter paa, hvad I høre: med hvad Maade I maale, skal Eder maales, og Eder, som høre, skal end gives Mere."],[4,25,"Thi hvo som haver, han skal gives; og hvo som ikke haver, fra ham skal endog det fratages, som han haver.","Thi hvo som haver, han skal gives; og hvo som ikke haver, fra ham skal endog det fratages, som han haver."],[4,26,"Og han sagde: med Guds Rige haver det sig saaledes, som naar et Menneske kaster Sæd i Jorden,","Og han sagde: med Guds Rige haver det sig saaledes, som naar et Menneske kaster Sæd i Jorden,"],[4,27,"og sover, og staaer op Nat og Dag; og Sæden voxer og bliver høi, han veed ei selv hvorledes.","og sover, og staaer op Nat og Dag; og Sæden voxer og bliver høi, han veed ei selv hvorledes."],[4,28,"Thi Jorden bærer Frugt af sig selv, først Græs, derefter Ax, derefter fuldt Korn i Axet.","Thi Jorden bærer Frugt af sig selv, først Græs, derefter Ax, derefter fuldt Korn i Axet."],[4,29,"Men naar Frugten er fuldkommen, skikker han strax Seglen hen; thi Høsten er forhaanden.","Men naar Frugten er fuldkommen, skikker han strax Seglen hen; thi Høsten er forhaanden."],[4,30,"Og han sagde: hvorved ville vi ligne Guds Rige? eller med hvad Lignelse ville vi forestille det?","Og han sagde: hvorved ville vi ligne Guds Rige? eller med hvad Lignelse ville vi forestille det?"],[4,31,"Det er som med Senepskornet, hvilket, naar det saaes i Jorden, er mindre end alt andet Frø paa Jorden;","Det er som med Senepskornet, hvilket, naar det saaes i Jorden, er mindre end alt andet Frø paa Jorden;"],[4,32,"og naar det er saaet, voxer det op, og bliver større end alle Urter, og faaer store Grene, saa at Himmelens Fugle kunne gjøre Rede under dets Skygge.","og naar det er saaet, voxer det op, og bliver større end alle Urter, og faaer store Grene, saa at Himmelens Fugle kunne gjøre Rede under dets Skygge."],[4,33,"Og han talede Ordet til dem ved mange saadanne Lignelser, eftersom de det kunde fatte.","Og han talede Ordet til dem ved mange saadanne Lignelser, eftersom de det kunde fatte."],[4,34,"Men uden Lignelse talede han ikke til dem; men i Eenrum udlagde han sine Disciple det altsammen.","Men uden Lignelse talede han ikke til dem; men i Eenrum udlagde han sine Disciple det altsammen."],[4,35,"Og den samme Dag, der det var blevet Aften, sagde han til dem; lader os fare over til hiin Side.","Og den samme Dag, der det var blevet Aften, sagde han til dem; lader os fare over til hiin Side."],[4,36,"Og de lode Folke gaae, og tage ham med, som han sad i Skibet; men der vare og andre Skibe med ham.","Og de lode Folke gaae, og tage ham med, som han sad i Skibet; men der vare og andre Skibe med ham."],[4,37,"Og der kom en stærk Hvirvelvind, og den kastede Bølgerne ind i Skibet, saa at det allerede fyldtes.","Og der kom en stærk Hvirvelvind, og den kastede Bølgerne ind i Skibet, saa at det allerede fyldtes."],[4,38,"Og han var i Bagstavnen og sov paa en Hovedpude; og de vakte ham op og sagde til ham: Mester! bekymrer du dig ikke om, at vi forgaae?","Og han var i Bagstavnen og sov paa en Hovedpude; og de vakte ham op og sagde til ham: Mester! bekymrer du dig ikke om, at vi forgaae?"],[4,39,"Og han stod op, og truede Veiret, og sagde til Søen, ti, vær stille! og Veiret lagde sig, og det blev ganske blikstille.","Og han stod op, og truede Veiret, og sagde til Søen, ti, vær stille! og Veiret lagde sig, og det blev ganske blikstille."],[4,40,"Og han sagde til dem: hvi ere I saa frygtagtige? hvorledes have I ikke Tro?","Og han sagde til dem: hvi ere I saa frygtagtige? hvorledes have I ikke Tro?"],[4,41,"Og de frygtede saare og sagde til hverandre; hvo er da denne, at baade Vind og Sø ere ham lydige?","Og de frygtede saare og sagde til hverandre; hvo er da denne, at baade Vind og Sø ere ham lydige?"],[5,1,"Og de kom paa hiin Side Søen til de Gadareners Egn.","Og de kom paa hiin Side Søen til de Gadareners Egn."],[5,2,"Og der han traadte ud af Skibet, mødte ham strax et Menneske fra Gravene, som havde en ureen Aand.","Og der han traadte ud af Skibet, mødte ham strax et Menneske fra Gravene, som havde en ureen Aand."],[5,3,"Han havde sin Bolig i Gravene, og Ingen kunde binde ham, end ikke med Lænker.","Han havde sin Bolig i Gravene, og Ingen kunde binde ham, end ikke med Lænker."],[5,4,"Thi han havde ofte været bunden med Bøier og Lænker, og Lænkerne vare sønderrykte af ham, og Bøierne sønderslidte, og Ingen kunde tæmme ham.","Thi han havde ofte været bunden med Bøier og Lænker, og Lænkerne vare sønderrykte af ham, og Bøierne sønderslidte, og Ingen kunde tæmme ham."],[5,5,"Og han var altid Nat og Dag paa Bjergene og i Gravene, skreg og slog sig selv med Stene.","Og han var altid Nat og Dag paa Bjergene og i Gravene, skreg og slog sig selv med Stene."],[5,6,"Men der han saae Jesus langt borte, løb han hen og kastede sig ned for ham,","Men der han saae Jesus langt borte, løb han hen og kastede sig ned for ham,"],[5,7,"og raabte med høi Røst og sagde: hvad haver jeg med dig at gjøre, Jesus, den allerhøieste Guds Søn? jeg besværger dig ved Gud, at du ikke piner mig.","og raabte med høi Røst og sagde: hvad haver jeg med dig at gjøre, Jesus, den allerhøieste Guds Søn? jeg besværger dig ved Gud, at du ikke piner mig."],[5,8,"Thi han sagde til ham: far ud, du urene Aand, af dette Menneske!","Thi han sagde til ham: far ud, du urene Aand, af dette Menneske!"],[5,9,"Og han spurgte ham: hvad er dit Navn? og han svarede og sagde: Legion er mit Navn; thi vi ere mange.","Og han spurgte ham: hvad er dit Navn? og han svarede og sagde: Legion er mit Navn; thi vi ere mange."],[5,10,"Og han bad ham meget, at han ikke skulle drive ham ud af Landet.","Og han bad ham meget, at han ikke skulle drive ham ud af Landet."],[5,11,"Men der var sammesteds ved Bjergene en stor Hjord Sviin, som græssede;","Men der var sammesteds ved Bjergene en stor Hjord Sviin, som græssede;"],[5,12,"og alle de Djævle bade ham og sagde: send og i Svinene, at vi maae fare i dem.","og alle de Djævle bade ham og sagde: send og i Svinene, at vi maae fare i dem."],[5,13,"Og Jesus tilstedte dem det strax. Og de urene Aander fore ud og fore ind i Svinene; og Hjorden styrtede sig af Brinken i Søen, (men de vare ved to tusinde), og de druknede i Søen.","Og Jesus tilstedte dem det strax. Og de urene Aander fore ud og fore ind i Svinene; og Hjorden styrtede sig af Brinken i Søen, (men de vare ved to tusinde), og de druknede i Søen."],[5,14,"Men Svinehyrderne flyede, og kundgjorde det i Staden og paa Landet; og de gik ud at see, hvad det var, som var skeet.","Men Svinehyrderne flyede, og kundgjorde det i Staden og paa Landet; og de gik ud at see, hvad det var, som var skeet."],[5,15,"Og de kom til Jesus, og saae ham, som havde været besat, at han sad og var paaklædt og var ved Sands, nemlig ham, som havde havt Legionen, og de forfærdedes.","Og de kom til Jesus, og saae ham, som havde været besat, at han sad og var paaklædt og var ved Sands, nemlig ham, som havde havt Legionen, og de forfærdedes."],[5,16,"Men de, som det havde seet, fortalte dem, hvorledes det var gaaet den Besatte, og om Svinene.","Men de, som det havde seet, fortalte dem, hvorledes det var gaaet den Besatte, og om Svinene."],[5,17,"Og de begyndte at bede ham, at han ville drage bort fra deres Egne.","Og de begyndte at bede ham, at han ville drage bort fra deres Egne."],[5,18,"Og der han traadte ind i Skibet, bad den, som havde været besat, ham, at han maatte være hos ham.","Og der han traadte ind i Skibet, bad den, som havde været besat, ham, at han maatte være hos ham."],[5,19,"Men Jesus tilstedte ham det ikke, men sagde til ham: gik hen i dit Huus, til Dine, og forkynd dem, hvor store Ting Herren, haver gjort dig, at han haver forbarmet sig over dig.","Men Jesus tilstedte ham det ikke, men sagde til ham: gik hen i dit Huus, til Dine, og forkynd dem, hvor store Ting Herren, haver gjort dig, at han haver forbarmet sig over dig."],[5,20,"Og han gik bort og begyndte at forkynde i Dekapolis, hvor store Ting Jesus havde gjort imod ham; og de forundrede sig alle.","Og han gik bort og begyndte at forkynde i Dekapolis, hvor store Ting Jesus havde gjort imod ham; og de forundrede sig alle."],[5,21,"Og der Jesus igjen var faren over i Skibet til hiin Side, forsamledes meget Folk til ham, og han var ved Søen.","Og der Jesus igjen var faren over i Skibet til hiin Side, forsamledes meget Folk til ham, og han var ved Søen."],[5,22,"Og see, der kom een af Synagog-Forstanderne ved Navn Jairus, og der han saae ham, faldt han ned for hans Fødder.","Og see, der kom een af Synagog-Forstanderne ved Navn Jairus, og der han saae ham, faldt han ned for hans Fødder."],[5,23,"Og han bad ham meget og sagde: min Datter er paa sit Yderste; o! at du vilde komme og lægge Hænderne paa hende, at hun maa frelses, da skal hun leve.","Og han bad ham meget og sagde: min Datter er paa sit Yderste; o! at du vilde komme og lægge Hænderne paa hende, at hun maa frelses, da skal hun leve."],[5,24,"Og han gik bort med ham, og meget Folk fulgte ham, og de trængte ham.","Og han gik bort med ham, og meget Folk fulgte ham, og de trængte ham."],[5,25,"Og der var en Kvinde, som havde havt Blodflod i tolv Aar.","Og der var en Kvinde, som havde havt Blodflod i tolv Aar."],[5,26,"Og hun havde lidt meget af mange Læger, og havde tilsat alt det, hun havde, og hun var ikke bleven hjulpen; men det var blevet værre med hende.","Og hun havde lidt meget af mange Læger, og havde tilsat alt det, hun havde, og hun var ikke bleven hjulpen; men det var blevet værre med hende."],[5,27,"Der hun hørte om Jesus, kom hun iblandt Folket bag fra, og rørte ved hans Klædebon.","Der hun hørte om Jesus, kom hun iblandt Folket bag fra, og rørte ved hans Klædebon."],[5,28,"Thi hun sagde: om jeg ikkun kan røre ved hans Klæder, da bliver jeg frelst.","Thi hun sagde: om jeg ikkun kan røre ved hans Klæder, da bliver jeg frelst."],[5,29,"Og Strax tørredes hendes Blods Kilde, og hun fornam i Legemet, at hun var bleven helbredet fra denne Plage.","Og Strax tørredes hendes Blods Kilde, og hun fornam i Legemet, at hun var bleven helbredet fra denne Plage."],[5,30,"Og Jesus fornam strax paa sig selv, at en Kraft udgik af ham, og vendte sig om iblandt Folket og sagde: hvo haver rørt ved mine Klæder?","Og Jesus fornam strax paa sig selv, at en Kraft udgik af ham, og vendte sig om iblandt Folket og sagde: hvo haver rørt ved mine Klæder?"],[5,31,"Og hans Disciple sagde til ham: du seer, at Folket trænger dig, og du siger: hvo rørte ved mig?","Og hans Disciple sagde til ham: du seer, at Folket trænger dig, og du siger: hvo rørte ved mig?"],[5,32,"Og han saae sig om, for at see hende, som havde gjort dette.","Og han saae sig om, for at see hende, som havde gjort dette."],[5,33,"Men Kvinden frygtede og bævede, da hun vidste, hvad hende var skeet, og kom og faldt ned for ham, og sagde ham al Sandheden.","Men Kvinden frygtede og bævede, da hun vidste, hvad hende var skeet, og kom og faldt ned for ham, og sagde ham al Sandheden."],[5,34,"Men han sagde til hende: Datter! din Tro haver frelst dig; gak bort med Fred, og vær helbredt fra din Plage.","Men han sagde til hende: Datter! din Tro haver frelst dig; gak bort med Fred, og vær helbredt fra din Plage."],[5,35,"Der han endnu talede, kom Nogle fra Synagog-Forstanderens Huus og sagde: din Datter er død, hvi umager du Mesteren længere?","Der han endnu talede, kom Nogle fra Synagog-Forstanderens Huus og sagde: din Datter er død, hvi umager du Mesteren længere?"],[5,36,"Men Jesus hørte strax, hvad der blev talet, og han sagde til Synagog-Forstanderen: frygt ikke, tro ikkun!","Men Jesus hørte strax, hvad der blev talet, og han sagde til Synagog-Forstanderen: frygt ikke, tro ikkun!"],[5,37,"Og han tilstedte Ingen at følge med sig, uden Peter og Jakob og Johannes, Jakobs Broder.","Og han tilstedte Ingen at følge med sig, uden Peter og Jakob og Johannes, Jakobs Broder."],[5,38,"Og han kom i Synagog-Forstanderens Huus, og saae Larmen, at de græd og hylede meget.","Og han kom i Synagog-Forstanderens Huus, og saae Larmen, at de græd og hylede meget."],[5,39,"Og han gik ind og sagde til dem: hvi larme I og græde? Barnet er ikke dødt, men sover.","Og han gik ind og sagde til dem: hvi larme I og græde? Barnet er ikke dødt, men sover."],[5,40,"Og de beloe ham; men han drev dem alle ud, og tog Barnets Fader og Moder med sig og dem, som vare med ham, og gik ind, hvor Barnet laae.","Og de beloe ham; men han drev dem alle ud, og tog Barnets Fader og Moder med sig og dem, som vare med ham, og gik ind, hvor Barnet laae."],[5,41,"Og han tog Barnet ved Haanden og sagde til det: talitha kumi! som er udlagt: Pige, jeg siger dig, staae op!","Og han tog Barnet ved Haanden og sagde til det: talitha kumi! som er udlagt: Pige, jeg siger dig, staae op!"],[5,42,"Og Pigen stod strax op og gik omkring; thi hun var tolv Aar gammel. Og de forfærdedes overmaade.","Og Pigen stod strax op og gik omkring; thi hun var tolv Aar gammel. Og de forfærdedes overmaade."],[5,43,"Og han bød dem meget, at Ingen skulde faae det at vide; og han sagde, at de skulde give hende at æde.","Og han bød dem meget, at Ingen skulde faae det at vide; og han sagde, at de skulde give hende at æde."],[6,1,"Og han gik bort derfra og kom til sit Fædreneland; og hans Disciple fulgte ham.","Og han gik bort derfra og kom til sit Fædreneland; og hans Disciple fulgte ham."],[6,2,"Og der Sabbaten var kommen, begyndte han at lære i Synagogen, og Mange, som det hørte, forundrede sig saare og sagde: hveden haver denne Saadant? og hvad er det for en Viisdom, som ham er given, at og saadanne kraftige Gjerninger skee ved hans Hænder?","Og der Sabbaten var kommen, begyndte han at lære i Synagogen, og Mange, som det hørte, forundrede sig saare og sagde: hveden haver denne Saadant? og hvad er det for en Viisdom, som ham er given, at og saadanne kraftige Gjerninger skee ved hans Hænder?"],[6,3,"Er denne ikke den Tømmermand, Marias Søn, Jakobs og Joses’ og Judas’ og Simons Broder? ere ikke og hans Søstre her hos os? Og de forargedes paa ham.","Er denne ikke den Tømmermand, Marias Søn, Jakobs og Joses’ og Judas’ og Simons Broder? ere ikke og hans Søstre her hos os? Og de forargedes paa ham."],[6,4,"Men Jesus sagde til dem: en Prophet er ikke foragtet uden i sit Fædreneland og iblandt sine Slægtninge i sit Huus.","Men Jesus sagde til dem: en Prophet er ikke foragtet uden i sit Fædreneland og iblandt sine Slægtninge i sit Huus."],[6,5,"Og han kunde der slet ingen kraftig Gjerning gjøre, uden at han lagde Hænderne paa nogle faa Syge, og helbredte dem.","Og han kunde der slet ingen kraftig Gjerning gjøre, uden at han lagde Hænderne paa nogle faa Syge, og helbredte dem."],[6,6,"Og han forundrede sig over deres Vantro, og gik omkring i Byerne og lærte.","Og han forundrede sig over deres Vantro, og gik omkring i Byerne og lærte."],[6,7,"Og han fremkaldte de Tolv, og han begyndte at udsende dem, to og to, og gav dem Magt over de urene Aander.","Og han fremkaldte de Tolv, og han begyndte at udsende dem, to og to, og gav dem Magt over de urene Aander."],[6,8,"Og han bød dem, at de skulde Intet tage med paa Reisen uden alene en Stav, ei Taske, ei Brød, ei Penninge i Beltet;","Og han bød dem, at de skulde Intet tage med paa Reisen uden alene en Stav, ei Taske, ei Brød, ei Penninge i Beltet;"],[6,9,"men have anbundne Skoe paa, og ikke iføre sig to Kjortler.","men have anbundne Skoe paa, og ikke iføre sig to Kjortler."],[6,10,"Og han sagde til dem: hvor I gaae ind i et Huus, bliver der, indtil I drage bort fra Stedet.","Og han sagde til dem: hvor I gaae ind i et Huus, bliver der, indtil I drage bort fra Stedet."],[6,11,"Og hvorsomhelst de ikke annamme Eder og ei høre Eder, gaaer bort derfra og afryster Støvet under Eders Fødder til Vidnesbyrd imod dem. Sandelig siger jeg Eder: det skal gaae Sodoma og Gomorra lideligere paa Dommens Dag end den Stad.","Og hvorsomhelst de ikke annamme Eder og ei høre Eder, gaaer bort derfra og afryster Støvet under Eders Fødder til Vidnesbyrd imod dem. Sandelig siger jeg Eder: det skal gaae Sodoma og Gomorra lideligere paa Dommens Dag end den Stad."],[6,12,"Og de gik ud og prædikede, at man skulde omvende sig.","Og de gik ud og prædikede, at man skulde omvende sig."],[6,13,"Og de dreve mange Djævle ud, og salvede mange Syge med Olie og helbredte dem.","Og de dreve mange Djævle ud, og salvede mange Syge med Olie og helbredte dem."],[6,14,"Kong Herodes hørte det, (thi hans Navn var bleven bekjendt), og han sagde: Johannes den Døber er opreist fra de Døde, og derfor tee sig de kraftige Gjerninger i ham.","Kong Herodes hørte det, (thi hans Navn var bleven bekjendt), og han sagde: Johannes den Døber er opreist fra de Døde, og derfor tee sig de kraftige Gjerninger i ham."],[6,15,"Andre sagde: han er Elias; men Andre sagde: han er en Prophet, eller som een af Propheterne.","Andre sagde: han er Elias; men Andre sagde: han er en Prophet, eller som een af Propheterne."],[6,16,"Men der Herodes hørte det, sagde ham: Johannes, som jeg haver ladet halshugge, ham er det; han er opreist fra de Døde.","Men der Herodes hørte det, sagde ham: Johannes, som jeg haver ladet halshugge, ham er det; han er opreist fra de Døde."],[6,17,"Thi Herodes havde selv sendt hen og ladet Johannes gribe og kaste i Fængsel, for Herodias’, sin Broder Philippus’ Hustrues Skyld; thi han havde taget hende tilægte.","Thi Herodes havde selv sendt hen og ladet Johannes gribe og kaste i Fængsel, for Herodias’, sin Broder Philippus’ Hustrues Skyld; thi han havde taget hende tilægte."],[6,18,"Thi Johannes sagde til Herodes: det er dig ikke tilladt at have din Broders Hustru.","Thi Johannes sagde til Herodes: det er dig ikke tilladt at have din Broders Hustru."],[6,19,"Men Herodias efterstræbte ham og vilde omkomme ham, og kunde ikke.","Men Herodias efterstræbte ham og vilde omkomme ham, og kunde ikke."],[6,20,"Thi Herodes frygtede for Johannes, fordi han vidste, at han var en retfærdig og hellig Mand, og holdt sin Haand over ham; og naar han havde hørt ham, gjorde han meget deraf, og han hørte ham gjerne.","Thi Herodes frygtede for Johannes, fordi han vidste, at han var en retfærdig og hellig Mand, og holdt sin Haand over ham; og naar han havde hørt ham, gjorde han meget deraf, og han hørte ham gjerne."],[6,21,"Og da der kom en beleilig Dag, der Herodes gjorde sine Store og de øverste Høvedsmænd og de Ypperste i Galilæa et Gjestebud paa sin Fødselsdag,","Og da der kom en beleilig Dag, der Herodes gjorde sine Store og de øverste Høvedsmænd og de Ypperste i Galilæa et Gjestebud paa sin Fødselsdag,"],[6,22,"og Herodias’ Datter kom ind og dandsede og behagede Herodes og Gjesterne, sagde Kongen til Pigen: bed af mig, hvad du vil, saa vil jeg give dig det.","og Herodias’ Datter kom ind og dandsede og behagede Herodes og Gjesterne, sagde Kongen til Pigen: bed af mig, hvad du vil, saa vil jeg give dig det."],[6,23,"Og han svoer hende: hvad du beder om, vil jeg give dig, indtil Halvdelen af mit Rige.","Og han svoer hende: hvad du beder om, vil jeg give dig, indtil Halvdelen af mit Rige."],[6,24,"Men hun gik ud og sagde til sin Moder: hvad skal jeg bede om? Men hun sagde: Johannes den Døbers Hoved.","Men hun gik ud og sagde til sin Moder: hvad skal jeg bede om? Men hun sagde: Johannes den Døbers Hoved."],[6,25,"Og hun gik strax hastelig ind til Kongen, bad og sagde: jeg vil, at du strax giver mig paa et Fad Johannes den Døbers Hoved.","Og hun gik strax hastelig ind til Kongen, bad og sagde: jeg vil, at du strax giver mig paa et Fad Johannes den Døbers Hoved."],[6,26,"Og Kongen blev bedrøvet, dog for Edernes og Gjesternes Skyld vilde han ikke afvise hende.","Og Kongen blev bedrøvet, dog for Edernes og Gjesternes Skyld vilde han ikke afvise hende."],[6,27,"Og Kongen sendte strax En af Vagten, og befoel at hente hans Hoved.","Og Kongen sendte strax En af Vagten, og befoel at hente hans Hoved."],[6,28,"Denne gik hen og halshuggede ham i Fængslet; og han bar hans Hoved frem paa et Fad, og gav Pigen det, og Pigen gav sin Moder det.","Denne gik hen og halshuggede ham i Fængslet; og han bar hans Hoved frem paa et Fad, og gav Pigen det, og Pigen gav sin Moder det."],[6,29,"Og der hans Disciple hørte det, kom de og toge hans Legeme og lagde det i en Grav.","Og der hans Disciple hørte det, kom de og toge hans Legeme og lagde det i en Grav."],[6,30,"Og Apostlene forsamledes til Jesus og forkyndte ham alle Ting, baade hvad de havde gjort, og hvad de havde lært.","Og Apostlene forsamledes til Jesus og forkyndte ham alle Ting, baade hvad de havde gjort, og hvad de havde lært."],[6,31,"Og han sagde til dem: kommer I afsides til et øde Sted og hviler lidet; thi de vare mange, som gik til og fra, og de havde ikke engang Leilighed til at æde.","Og han sagde til dem: kommer I afsides til et øde Sted og hviler lidet; thi de vare mange, som gik til og fra, og de havde ikke engang Leilighed til at æde."],[6,32,"Og de fore bort i et Skib til et øde Sted afsides.","Og de fore bort i et Skib til et øde Sted afsides."],[6,33,"Og Folket saae dem fare bort, og Mange kjendte ham, og over Land løb de fra alle Stæder tilsammen derhen og kom førend de, og kom til ham.","Og Folket saae dem fare bort, og Mange kjendte ham, og over Land løb de fra alle Stæder tilsammen derhen og kom førend de, og kom til ham."],[6,34,"Og Jesus gik ud og saae meget Folk, og han ynkedes inderligen over dem, thi de vare som Faar, der ikke have Hyrde; og han begyndte at lære dem meget.","Og Jesus gik ud og saae meget Folk, og han ynkedes inderligen over dem, thi de vare som Faar, der ikke have Hyrde; og han begyndte at lære dem meget."],[6,35,"Og der Dagen var nu fast forløben, gik hans Disciple til ham og sagde: det er et øde Sted og Dagen er nu fast forløben.","Og der Dagen var nu fast forløben, gik hans Disciple til ham og sagde: det er et øde Sted og Dagen er nu fast forløben."],[6,36,"Lad dem fare, at de kunne gaae hen i de omliggende Landsbyer og Flækker at kjøbe sig Brød; thi de have Intet at æde.","Lad dem fare, at de kunne gaae hen i de omliggende Landsbyer og Flækker at kjøbe sig Brød; thi de have Intet at æde."],[6,37,"Men han svarede og sagde til dem: giver I dem at æde. Og de sagde til ham: skulle vi gaae bort og kjøbe Brød for to hundrede Penninge, og give dem at æde?","Men han svarede og sagde til dem: giver I dem at æde. Og de sagde til ham: skulle vi gaae bort og kjøbe Brød for to hundrede Penninge, og give dem at æde?"],[6,38,"Men han sagde til dem: hvor mange Brød have I? gaaer bort og seer. Og der de havde forfaret det, sagde de: fem, og to Fiske.","Men han sagde til dem: hvor mange Brød have I? gaaer bort og seer. Og der de havde forfaret det, sagde de: fem, og to Fiske."],[6,39,"Og han bød dem, at lade dem alle sætte sig ned i adskillige Hobe paa det grønne Græs.","Og han bød dem, at lade dem alle sætte sig ned i adskillige Hobe paa det grønne Græs."],[6,40,"Og de satte sig ned, Hob ved Hob, i somme hundrede, og i somme halvtredsindstyve.","Og de satte sig ned, Hob ved Hob, i somme hundrede, og i somme halvtredsindstyve."],[6,41,"Og han tog de fem Brød og de to Fiske, saae op til Himmelen, og velsignede dem; og han brød Brødene, og gav sine Disciple dem at lægge for Folket, og han delede de to Fiske iblandt dem alle.","Og han tog de fem Brød og de to Fiske, saae op til Himmelen, og velsignede dem; og han brød Brødene, og gav sine Disciple dem at lægge for Folket, og han delede de to Fiske iblandt dem alle."],[6,42,"Og de aade alle og bleve mætte.","Og de aade alle og bleve mætte."],[6,43,"Og de opsamlede tolv Kurve, fulde af Stykker og af Fiskene.","Og de opsamlede tolv Kurve, fulde af Stykker og af Fiskene."],[6,44,"Og de, som aade Brødene, vare ved fem tusinde Mænd.","Og de, som aade Brødene, vare ved fem tusinde Mænd."],[6,45,"Og strax nødte han sine Disciple til at gaae i Skibet og iforveien sætte over til hiin Side til Bethsaida, indtil han havde ladet Folket fare.","Og strax nødte han sine Disciple til at gaae i Skibet og iforveien sætte over til hiin Side til Bethsaida, indtil han havde ladet Folket fare."],[6,46,"Og der han havde taget Afsked fra dem, gik han op paa et Bjerg, at bede.","Og der han havde taget Afsked fra dem, gik han op paa et Bjerg, at bede."],[6,47,"Og der det var blevet Aften, var Skibet midt paa Søen, og han alene paa Landet.","Og der det var blevet Aften, var Skibet midt paa Søen, og han alene paa Landet."],[6,48,"Og han saae, at de lede Nød, idet de roede, (thi Veiret var dem imod), og ved den fjerde Nattevagt kom han til dem vandrende paa Søen, og han vilde gaae dem forbi.","Og han saae, at de lede Nød, idet de roede, (thi Veiret var dem imod), og ved den fjerde Nattevagt kom han til dem vandrende paa Søen, og han vilde gaae dem forbi."],[6,49,"Men der de saae ham vandre paa Søen, meente de, at det var et Spøgelse, og de skrege.","Men der de saae ham vandre paa Søen, meente de, at det var et Spøgelse, og de skrege."],[6,50,"(Thi de saae ham alle og bleve forskrækkede). Og han talede strax med dem og sagde til dem: værer frimodige, det er mig, frygter ikke!","(Thi de saae ham alle og bleve forskrækkede). Og han talede strax med dem og sagde til dem: værer frimodige, det er mig, frygter ikke!"],[6,51,"Og han raadte i Skibet til dem, og Veiret stilledes, og de forfærdedes over al Maade ved sig selv, og forundrede sig.","Og han raadte i Skibet til dem, og Veiret stilledes, og de forfærdedes over al Maade ved sig selv, og forundrede sig."],[6,52,"Thi de havde ikke faaet Forstand af det, fordi deres Hjerte var forhærdet.","Thi de havde ikke faaet Forstand af det, fordi deres Hjerte var forhærdet."],[6,53,"Og der de vare satte over, kom de til det Land Genezareth, og lagde til Land.","Og der de vare satte over, kom de til det Land Genezareth, og lagde til Land."],[6,54,"Og der de traadte ud af Skibet, kjendte man ham strax.","Og der de traadte ud af Skibet, kjendte man ham strax."],[6,55,"Og de løb om i den ganske omliggende Egn, og begyndte at føre dem, som lede ilde, omkring paa Sengene, hvor de hørte, at han var.","Og de løb om i den ganske omliggende Egn, og begyndte at føre dem, som lede ilde, omkring paa Sengene, hvor de hørte, at han var."],[6,56,"Og hvor han gik ind i Flækker eller Stræder eller Landsbyer, lagde de de Syge paa Torvene, og bade ham, at de maatte ikkun røre ved Sømmen paa hans Klædebon; og alle de, som rørte ved ham, bleve helbredte.","Og hvor han gik ind i Flækker eller Stræder eller Landsbyer, lagde de de Syge paa Torvene, og bade ham, at de maatte ikkun røre ved Sømmen paa hans Klædebon; og alle de, som rørte ved ham, bleve helbredte."],[7,1,"Og Pharisæerne og nogle af de Skriftkloge, som vare komne fra Jerusalem, forsamledes til ham.","Og Pharisæerne og nogle af de Skriftkloge, som vare komne fra Jerusalem, forsamledes til ham."],[7,2,"Og der de saae nogle af hans Disciple æde Brød med vanhellige, det er, med utoede Hænder, lastede de det.","Og der de saae nogle af hans Disciple æde Brød med vanhellige, det er, med utoede Hænder, lastede de det."],[7,3,"(Thi Pharisæerne og alle Jøderne æde ikke, uden flittigen at toe Hænderne, overholdende de Ældstes Skik.","(Thi Pharisæerne og alle Jøderne æde ikke, uden flittigen at toe Hænderne, overholdende de Ældstes Skik."],[7,4,"Og af det, der er kjøbt paa Torvet, æde de ikke, uden først at toe det; og der ere mange andre Ting, som de have vedtaget at holde, med at udtoe Bægere og Kruus og Kobberkar og Bænke).","Og af det, der er kjøbt paa Torvet, æde de ikke, uden først at toe det; og der ere mange andre Ting, som de have vedtaget at holde, med at udtoe Bægere og Kruus og Kobberkar og Bænke)."],[7,5,"Derefter spurgte Pharisæerne og de Skriftkloge ham ad: hvi vandre ikke dine Disciple efter de Ældstes Skik, men æde med utoede Hænder?","Derefter spurgte Pharisæerne og de Skriftkloge ham ad: hvi vandre ikke dine Disciple efter de Ældstes Skik, men æde med utoede Hænder?"],[7,6,"Men han svarede og sagde til dem: Esaias haver spaaet retteligen om Eder, I Øienskalke! som skrevet er: dette Folk ærer mig med Læberne, men deres Hjerte er langt fra mig.","Men han svarede og sagde til dem: Esaias haver spaaet retteligen om Eder, I Øienskalke! som skrevet er: dette Folk ærer mig med Læberne, men deres Hjerte er langt fra mig."],[7,7,"Men de dyrke mig forgjeves, idet de lære saadanne Lærdomme, som ere Menneskers Bud.","Men de dyrke mig forgjeves, idet de lære saadanne Lærdomme, som ere Menneskers Bud."],[7,8,"Thi I forlade Guds Bud og holde Menneskers Skik, med at udtoe Kruus og Bægere; og I gjøre mange andre saadanne Ting.","Thi I forlade Guds Bud og holde Menneskers Skik, med at udtoe Kruus og Bægere; og I gjøre mange andre saadanne Ting."],[7,9,"Og han sagde til dem: smukt aflægge I Guds Bud, paa det I kunne holde Eders Skik.","Og han sagde til dem: smukt aflægge I Guds Bud, paa det I kunne holde Eders Skik."],[7,10,"Thi Moses haver sagt: ær din Fader og din Moder, og hvo som bander Fader eller Moder, skal visselig døe.","Thi Moses haver sagt: ær din Fader og din Moder, og hvo som bander Fader eller Moder, skal visselig døe."],[7,11,"Men I sige: naar Nogen siger til Fader eller Moder: det, hvormed jeg kunde hjulpet dig, er Korban (det er en Gave):","Men I sige: naar Nogen siger til Fader eller Moder: det, hvormed jeg kunde hjulpet dig, er Korban (det er en Gave):"],[7,12,"da tilstede I ham ikke ydermere at yde sin Fader eller Moder nogen Hjælp.","da tilstede I ham ikke ydermere at yde sin Fader eller Moder nogen Hjælp."],[7,13,"Og I gjøre Guds Ord til Intet ved Eders Skik, som I have paalagt; og I gjøre meget saadant.","Og I gjøre Guds Ord til Intet ved Eders Skik, som I have paalagt; og I gjøre meget saadant."],[7,14,"Og han kaldte alt Folket til sig og sagde til dem: hører mig Alle, og forstaaer.","Og han kaldte alt Folket til sig og sagde til dem: hører mig Alle, og forstaaer."],[7,15,"Der er Intet udenfor Mennesket, som, naar det kommer ind i ham, kan gjøre ham ureen; men hvad som gaaer ud af ham, dette er det, som gjør Mennesket ureent.","Der er Intet udenfor Mennesket, som, naar det kommer ind i ham, kan gjøre ham ureen; men hvad som gaaer ud af ham, dette er det, som gjør Mennesket ureent."],[7,16,"Dersom Nogen haver Øren at høre med, han høre!","Dersom Nogen haver Øren at høre med, han høre!"],[7,17,"Og der han var indgangen i Huset fra Folket, spurgte hans Disciple ham om denne Lignelse.","Og der han var indgangen i Huset fra Folket, spurgte hans Disciple ham om denne Lignelse."],[7,18,"Og han sagde til dem: ere I og saa uforstandige? forstaae I ikke, at Intet, som udenfra kommer ind i Mennesket, kan gjøre ham ureen?","Og han sagde til dem: ere I og saa uforstandige? forstaae I ikke, at Intet, som udenfra kommer ind i Mennesket, kan gjøre ham ureen?"],[7,19,"Thi det kommer ikke ind i hans Hjerte, men i Bugen, og gaaer ud ved den naturlige Gang, og saaledes renses al Maden.","Thi det kommer ikke ind i hans Hjerte, men i Bugen, og gaaer ud ved den naturlige Gang, og saaledes renses al Maden."],[7,20,"Men han sagde: hvad som udgaaer af Mennesket, det gjør Mennesket ureent.","Men han sagde: hvad som udgaaer af Mennesket, det gjør Mennesket ureent."],[7,21,"Thi indvortes af Menneskenes Hjerte udgaae onde Tanker, Hoer, Skjørlevnet, Mord,","Thi indvortes af Menneskenes Hjerte udgaae onde Tanker, Hoer, Skjørlevnet, Mord,"],[7,22,"Tyveri, Gjerrighed, Ondskab, Svig, Uteerlighed, et ondt Øie, Gudsbespottelse, Hovmod, Uforstandighed;","Tyveri, Gjerrighed, Ondskab, Svig, Uteerlighed, et ondt Øie, Gudsbespottelse, Hovmod, Uforstandighed;"],[7,23,"alle disse onde Ting udgaae indvortes fra, og gjøre Mennesket ureent.","alle disse onde Ting udgaae indvortes fra, og gjøre Mennesket ureent."],[7,24,"Og han stod op og gik derfra til Tyrus’ og Sidons Grændser, og gik ind i et Huus, og vilde Ingen lade vide det, og det kunde dog ikke blive skjult.","Og han stod op og gik derfra til Tyrus’ og Sidons Grændser, og gik ind i et Huus, og vilde Ingen lade vide det, og det kunde dog ikke blive skjult."],[7,25,"Thi en Kvinde, som havde hørt om ham, hvis Datter havde en ureen Aand, kom og faldt ned for hans Fødder;","Thi en Kvinde, som havde hørt om ham, hvis Datter havde en ureen Aand, kom og faldt ned for hans Fødder;"],[7,26,"(men hun var en grækisk Kvinde, af Slægt en Syro-Phoenicerinde), og hun bad ham, at han vilde uddrive Djævelen af hendes Datter.","(men hun var en grækisk Kvinde, af Slægt en Syro-Phoenicerinde), og hun bad ham, at han vilde uddrive Djævelen af hendes Datter."],[7,27,"Men Jesus sagde til hende: lad først Børnene mættes; thi det er ikke smukt, at tage Børnenes Brød, og kaste det for smaa Hunde.","Men Jesus sagde til hende: lad først Børnene mættes; thi det er ikke smukt, at tage Børnenes Brød, og kaste det for smaa Hunde."],[7,28,"Men hun svarede og sagde til ham: jo, Herre! thi og smaa Hunde æde under Bordet af Børnenes Smuler.","Men hun svarede og sagde til ham: jo, Herre! thi og smaa Hunde æde under Bordet af Børnenes Smuler."],[7,29,"Og han sagde til hende: for dette Ords Skyld gak bort; Djævelen er udfaren af din Datter.","Og han sagde til hende: for dette Ords Skyld gak bort; Djævelen er udfaren af din Datter."],[7,30,"Og hun gik bort til sit Huus og fandt, at Djævelen var udfaren, og Datteren laae paa Sengen.","Og hun gik bort til sit Huus og fandt, at Djævelen var udfaren, og Datteren laae paa Sengen."],[7,31,"Og der han gik ud igjen af Tyrus’ og Sidons Egne, kom han til den galilæiske Sø, midt igjennem Dekapolis’ Grændser.","Og der han gik ud igjen af Tyrus’ og Sidons Egne, kom han til den galilæiske Sø, midt igjennem Dekapolis’ Grændser."],[7,32,"Og de førte en Døv til ham, som besværlig kunde tale; og de bade ham, at han vilde lægge Haanden paa ham.","Og de førte en Døv til ham, som besværlig kunde tale; og de bade ham, at han vilde lægge Haanden paa ham."],[7,33,"Og han tog ham afsides fra Folket og lagde sine Fingre i hans Øren, og spyttede og rørte ved hans Tunge,","Og han tog ham afsides fra Folket og lagde sine Fingre i hans Øren, og spyttede og rørte ved hans Tunge,"],[7,34,"og saae op til Himmelen, sukkede, og sagde til ham: Ephata! det er: lad dig op!","og saae op til Himmelen, sukkede, og sagde til ham: Ephata! det er: lad dig op!"],[7,35,"Og strax aabnedes hans Øren, og hans Tunges Baand løsnedes, og han talede ret.","Og strax aabnedes hans Øren, og hans Tunges Baand løsnedes, og han talede ret."],[7,36,"Og han bød dem, at de skulde Ingen sige det; men jo mere han bød dem, desto mere kundgjorde de det.","Og han bød dem, at de skulde Ingen sige det; men jo mere han bød dem, desto mere kundgjorde de det."],[7,37,"Og de forundrede sig overmaade og sagde: han haver gjort alle Ting vel; baade gjør han, at de Døve høre, og at de Maalløse tale.","Og de forundrede sig overmaade og sagde: han haver gjort alle Ting vel; baade gjør han, at de Døve høre, og at de Maalløse tale."],[8,1,"I de samme Dage, da der var saare meget Folk, og de Intet havde at æde, kaldte Jesus sine Disciple til sig og sagde til dem:\nOg han sagde til dem: sandelig siger jeg Eder, der ere Nogle af dem, som her staae, som ingenlunde skulle smage Døden, førend de see Guds Rige at være kommet med Kraft.","I de samme Dage, da der var saare meget Folk, og de Intet havde at æde, kaldte Jesus sine Disciple til sig og sagde til dem:\nOg han sagde til dem: sandelig siger jeg Eder, der ere Nogle af dem, som her staae, som ingenlunde skulle smage Døden, førend de see Guds Rige at være kommet med Kraft."],[8,2,"mig ynkes inderligen over Folket; thi de have nu tøvet hos mig i tre Dage, og have Intet at æde.","mig ynkes inderligen over Folket; thi de have nu tøvet hos mig i tre Dage, og have Intet at æde."],[8,3,"Og dersom jeg lader dem fare fastende hjem, maatte de forsmægte paa Veien; thi Nogle af dem ere komne langt fra.","Og dersom jeg lader dem fare fastende hjem, maatte de forsmægte paa Veien; thi Nogle af dem ere komne langt fra."],[8,4,"Og hans Disciple svarede ham: hvorfra skulde Nogen kunne mætte disse med Brød her i Ørken?","Og hans Disciple svarede ham: hvorfra skulde Nogen kunne mætte disse med Brød her i Ørken?"],[8,5,"Og han spurgte dem ad: hvor mange Brød have I? Men de sagde: syv.","Og han spurgte dem ad: hvor mange Brød have I? Men de sagde: syv."],[8,6,"Og han bød Folket sætte sig ned paa Jorden, og tog de syv Brød, takkede, brød dem, og gav sine Disciple dem, at de skulde lægge dem for dem; og de lagde dem for Folket.","Og han bød Folket sætte sig ned paa Jorden, og tog de syv Brød, takkede, brød dem, og gav sine Disciple dem, at de skulde lægge dem for dem; og de lagde dem for Folket."],[8,7,"Og de havde faa smaa Fiske; og han velsignede dem og bød, at ogsaa disse skulde lægges for.","Og de havde faa smaa Fiske; og han velsignede dem og bød, at ogsaa disse skulde lægges for."],[8,8,"Men de aade og bleve mætte; og optoge af de levnede Stykker syv Kurve.","Men de aade og bleve mætte; og optoge af de levnede Stykker syv Kurve."],[8,9,"Men de vare ved fire Tusinde, som havde ædet, og han lod dem fare.","Men de vare ved fire Tusinde, som havde ædet, og han lod dem fare."],[8,10,"Og strax traadte han i Skibet med Disciplene og kom til Dalmanuthas Egne.","Og strax traadte han i Skibet med Disciplene og kom til Dalmanuthas Egne."],[8,11,"Og Pharisæerne gik ud og begyndte at bespørge sig med ham, og begjerede af ham et Tegn fra Himmelen for at friste ham.","Og Pharisæerne gik ud og begyndte at bespørge sig med ham, og begjerede af ham et Tegn fra Himmelen for at friste ham."],[8,12,"Og han sukkede dybt i sin Aand og sagde: hvi søger denne Slægt Tegn? Sandelig siger jeg Eder, at intet Tegn skal gives denne Slægt.","Og han sukkede dybt i sin Aand og sagde: hvi søger denne Slægt Tegn? Sandelig siger jeg Eder, at intet Tegn skal gives denne Slægt."],[8,13,"Og han lod dem fare, og traadte i Skibet igjen og foer til hiin Side.","Og han lod dem fare, og traadte i Skibet igjen og foer til hiin Side."],[8,14,"Og de havde glemt at tage Brød med, og havde ikke mere med sig i Skibet end eet Brød.","Og de havde glemt at tage Brød med, og havde ikke mere med sig i Skibet end eet Brød."],[8,15,"Og han bød dem og sagde: seer til, tager Eder vare for Pharisæernes Suurdeig og Herodes’ Suurdeig.","Og han bød dem og sagde: seer til, tager Eder vare for Pharisæernes Suurdeig og Herodes’ Suurdeig."],[8,16,"Og de bespurgte sig indbyrdes og sagde: det er, fordi vi ikke have Brød.","Og de bespurgte sig indbyrdes og sagde: det er, fordi vi ikke have Brød."],[8,17,"Og da Jesus fornam det, sagde han til dem: hvi bespørge I Eder derom, at I ikke have Brød? Besinde I Eder ikke endnu, og forstaae I ei heller, er Eders Hjerte endnu forhærdet?","Og da Jesus fornam det, sagde han til dem: hvi bespørge I Eder derom, at I ikke have Brød? Besinde I Eder ikke endnu, og forstaae I ei heller, er Eders Hjerte endnu forhærdet?"],[8,18,"Have I Øine, og see ikke? og have I Øren, og høre ikke? og komme I ikke ihu?","Have I Øine, og see ikke? og have I Øren, og høre ikke? og komme I ikke ihu?"],[8,19,"Da jeg brød fem Brød til fem Tusinde, hvor mange Kurve fulde af Stykker toge I da op? De sagde til ham: tolv.","Da jeg brød fem Brød til fem Tusinde, hvor mange Kurve fulde af Stykker toge I da op? De sagde til ham: tolv."],[8,20,"Men da jeg brød de syv til de fire Tusinde, hvor mange Kurve fulde af Stykker toge I da op? De sagde: syv.","Men da jeg brød de syv til de fire Tusinde, hvor mange Kurve fulde af Stykker toge I da op? De sagde: syv."],[8,21,"Og han sagde til dem; hvorledes forstaae I da ikke?","Og han sagde til dem; hvorledes forstaae I da ikke?"],[8,22,"Og han kom til Bethsaida; og de førte en Blind til ham og bade ham, at han vilde røre ved ham.","Og han kom til Bethsaida; og de førte en Blind til ham og bade ham, at han vilde røre ved ham."],[8,23,"Og han tog den Blinde ved Haanden, og ledte ham hen udenfor Byen, og spyttede i hans Øine, og lagde Hænderne paa ham, og spurgte ham, og han saae Noget.","Og han tog den Blinde ved Haanden, og ledte ham hen udenfor Byen, og spyttede i hans Øine, og lagde Hænderne paa ham, og spurgte ham, og han saae Noget."],[8,24,"Og han saae op og sagde: jeg seer Mennesker, som Træer, gaae omkring.","Og han saae op og sagde: jeg seer Mennesker, som Træer, gaae omkring."],[8,25,"Derefter lagde han atter Hænderne paa hans Øine og kom ham til at see, og han blev helbredet og saae Alle klarlig.","Derefter lagde han atter Hænderne paa hans Øine og kom ham til at see, og han blev helbredet og saae Alle klarlig."],[8,26,"Og han sendte ham til hans Huus og sagde: du skal hverken gaae ind i Byen, ei heller sige det til Nogen i Byen.","Og han sendte ham til hans Huus og sagde: du skal hverken gaae ind i Byen, ei heller sige det til Nogen i Byen."],[8,27,"Og Jesus og hans Disciple gik ud til de Byer ved Cæsarea Philippi; og paa Veien spurgte han sine Disciple og sagde til dem: hvem sige Menneskene mig at være?","Og Jesus og hans Disciple gik ud til de Byer ved Cæsarea Philippi; og paa Veien spurgte han sine Disciple og sagde til dem: hvem sige Menneskene mig at være?"],[8,28,"Men de svarede: Nogle sige, du er Johannes den Døber; og Andre, Elias; men Andre, een af Propheterne.","Men de svarede: Nogle sige, du er Johannes den Døber; og Andre, Elias; men Andre, een af Propheterne."],[8,29,"Og han sagde til dem: men I, hvem sige I, at jeg er? Da svarede Peter og sagde til ham: du er Christus.","Og han sagde til dem: men I, hvem sige I, at jeg er? Da svarede Peter og sagde til ham: du er Christus."],[8,30,"Og han bød dem strengeligen, at de ikke skulde sige Nogen dette om ham.","Og han bød dem strengeligen, at de ikke skulde sige Nogen dette om ham."],[8,31,"Og han begyndte at lære dem, at Menneskens Søn skulde lide meget, og forskydes af de Ældste og Ypperstepræster og Skriftkloge, og ihjelslaaes, og opstaae efter tre Dage.","Og han begyndte at lære dem, at Menneskens Søn skulde lide meget, og forskydes af de Ældste og Ypperstepræster og Skriftkloge, og ihjelslaaes, og opstaae efter tre Dage."],[8,32,"Og han talede dette frit ud. Og Peter tog ham til sig, og begyndte at straffe ham.","Og han talede dette frit ud. Og Peter tog ham til sig, og begyndte at straffe ham."],[8,33,"Men han vendte sig om og saae paa sine Disciple, og straffede Peter og sagde: vig bag mig, Satan! thi du sandser ikke, hvad Guds er, men hvad Menneskens er.","Men han vendte sig om og saae paa sine Disciple, og straffede Peter og sagde: vig bag mig, Satan! thi du sandser ikke, hvad Guds er, men hvad Menneskens er."],[8,34,"Og han kaldte Folket til sig tilligemed sine Disciple og sagde til dem: hvo som vil komme efter mig, han skal fornegte sig selv, og tage sit Kors op, og følge mig.","Og han kaldte Folket til sig tilligemed sine Disciple og sagde til dem: hvo som vil komme efter mig, han skal fornegte sig selv, og tage sit Kors op, og følge mig."],[8,35,"Thi hvo som vil frelse sit Liv, skal miste det; men hvo som mister sit Liv for min og Evangeliums Skyld, han skal frelse det.","Thi hvo som vil frelse sit Liv, skal miste det; men hvo som mister sit Liv for min og Evangeliums Skyld, han skal frelse det."],[8,36,"Thi hvad kan det gavne et Menneske, dersom han vandt den ganske Verden og tog Skade paa sin Sjæl?","Thi hvad kan det gavne et Menneske, dersom han vandt den ganske Verden og tog Skade paa sin Sjæl?"],[8,37,"Eller hvad kan et Menneske give til Vederlag for sin Sjæl?","Eller hvad kan et Menneske give til Vederlag for sin Sjæl?"],[8,38,"Thi hvo som skammer sig ved mig og mine Ord iblandt denne vanartige og syndige Slægt, ved den skal og Menneskens Søn skamme sig, naar han kommer i sin Faders Herlighed med de hellige Engle.","Thi hvo som skammer sig ved mig og mine Ord iblandt denne vanartige og syndige Slægt, ved den skal og Menneskens Søn skamme sig, naar han kommer i sin Faders Herlighed med de hellige Engle."],[9,2,"Og sex Dage derefter tog Jesus Peter og Jakob og Johannes til sig, og førte dem afsides op paa et høit Bjerg, og han blev forvandlet for dem.","Og sex Dage derefter tog Jesus Peter og Jakob og Johannes til sig, og førte dem afsides op paa et høit Bjerg, og han blev forvandlet for dem."],[9,3,"Og hans Klæder bleve skinnende, meget hvide, som Snee, saa at ingen Farver paa Jorden kan gjøre dem saa hvide.","Og hans Klæder bleve skinnende, meget hvide, som Snee, saa at ingen Farver paa Jorden kan gjøre dem saa hvide."],[9,4,"Og Elias tilligemed Moses viste sig for dem, og de talede med Jesus.","Og Elias tilligemed Moses viste sig for dem, og de talede med Jesus."],[9,5,"Og Peter svarede og sagde til Jesus: Rabbi! her er os godt at være, og vi ville gjøre tre Boliger, dig een og Moses een og Elias een.","Og Peter svarede og sagde til Jesus: Rabbi! her er os godt at være, og vi ville gjøre tre Boliger, dig een og Moses een og Elias een."],[9,6,"Thi han vidste ikke, hvad han talede; thi de vare heel forfærdede.","Thi han vidste ikke, hvad han talede; thi de vare heel forfærdede."],[9,7,"Og der kom en Sky, som overskyggede dem; og en Røst kom af Skyen, som sagde: denne er min Søn, den Elskelige, hører ham!","Og der kom en Sky, som overskyggede dem; og en Røst kom af Skyen, som sagde: denne er min Søn, den Elskelige, hører ham!"],[9,8,"Og strax, der de skuede omkring sig, saae de Ingen mere, uden Jesus alene med dem.","Og strax, der de skuede omkring sig, saae de Ingen mere, uden Jesus alene med dem."],[9,9,"Men der de gik ned af Bjerget, bød ham dem, at de skulde Ingen fortælle, hvad de havde seet, førend Menneskens Søn var opstanden fra de Døde.","Men der de gik ned af Bjerget, bød ham dem, at de skulde Ingen fortælle, hvad de havde seet, førend Menneskens Søn var opstanden fra de Døde."],[9,10,"Og de holdt dette hos sig selv, og bespurgte sig med hverandre, hvad det er, at opstaae fra de Døde.","Og de holdt dette hos sig selv, og bespurgte sig med hverandre, hvad det er, at opstaae fra de Døde."],[9,11,"Og de spurgte ham og sagde: sige dog de Skriftkloge, at Elias bør først komme?","Og de spurgte ham og sagde: sige dog de Skriftkloge, at Elias bør først komme?"],[9,12,"Men han svarede og sagde til dem: Elias bør først komme og skikke alle Ting tilrette; og det skal skee, som det er skrevet om Menneskens Søn, at han skal lide meget og foragtes.","Men han svarede og sagde til dem: Elias bør først komme og skikke alle Ting tilrette; og det skal skee, som det er skrevet om Menneskens Søn, at han skal lide meget og foragtes."],[9,13,"Men jeg siger Eder, at baade er Elias kommen, og de gjorde ved ham, hvad de vilde, eftersom det er skrevet om ham.","Men jeg siger Eder, at baade er Elias kommen, og de gjorde ved ham, hvad de vilde, eftersom det er skrevet om ham."],[9,14,"Og da han kom til Disciplene, saae han meget Folk omkring dem og de Skriftkloge, som bespurgte sig med dem.","Og da han kom til Disciplene, saae han meget Folk omkring dem og de Skriftkloge, som bespurgte sig med dem."],[9,15,"Og strax forbausedes alt Folket, der de saae ham, og de løb til og hilsede ham.","Og strax forbausedes alt Folket, der de saae ham, og de løb til og hilsede ham."],[9,16,"Og han spurgte de Skriftkloge: hvorom bespørge I Eder indbyrdes?","Og han spurgte de Skriftkloge: hvorom bespørge I Eder indbyrdes?"],[9,17,"Og Een af Folket svarede og sagde: Mester! jeg haver ført min Søn til dig; han haver en maalløs Aand.","Og Een af Folket svarede og sagde: Mester! jeg haver ført min Søn til dig; han haver en maalløs Aand."],[9,18,"Og naar den faaer fat paa ham, slider den ham, og han fraader og skærer med sine Tænder, og han henvisner; og jeg haver begjeret af dine Disciple, at de skulde uddrive den, og de kunde ikke.","Og naar den faaer fat paa ham, slider den ham, og han fraader og skærer med sine Tænder, og han henvisner; og jeg haver begjeret af dine Disciple, at de skulde uddrive den, og de kunde ikke."],[9,19,"Men han svarede dem og sagde: o du vantroe Slægt! hvorlænge skal jeg være hos Eder? hvorlænge skal jeg taale Eder? Bringer ham til mig.","Men han svarede dem og sagde: o du vantroe Slægt! hvorlænge skal jeg være hos Eder? hvorlænge skal jeg taale Eder? Bringer ham til mig."],[9,20,"Og de ledte ham frem til ham; og der han saae ham, sled Aanden ham strax, og han faldt paa Jorden og væltede sig og fraadede.","Og de ledte ham frem til ham; og der han saae ham, sled Aanden ham strax, og han faldt paa Jorden og væltede sig og fraadede."],[9,21,"Og han spurgte hans Fader: hvor længe er det, at dette vederfares ham? Men han sagde: fra Barndommen;","Og han spurgte hans Fader: hvor længe er det, at dette vederfares ham? Men han sagde: fra Barndommen;"],[9,22,"og den haver ofte kastet ham baade i Ild og Vand, at den kunde omkomme ham; men formaaer du noget, da forbarm dig over os og hjælp os!","og den haver ofte kastet ham baade i Ild og Vand, at den kunde omkomme ham; men formaaer du noget, da forbarm dig over os og hjælp os!"],[9,23,"Men Jesus sagde til ham: dersom du kan troe; alle Ting ere den mulige, som troer.","Men Jesus sagde til ham: dersom du kan troe; alle Ting ere den mulige, som troer."],[9,24,"Og strax raabte Barnets Fader grædende og sagde: jeg troer, Herre! hjælp min Vantro.","Og strax raabte Barnets Fader grædende og sagde: jeg troer, Herre! hjælp min Vantro."],[9,25,"Men der Jesus saae, at Folket løb til, truede han den urene Aand og sagde til den: du maalløse og døve Aand! jeg byder dig, far ud af ham, og at du ikke herefter farer ind i ham.","Men der Jesus saae, at Folket løb til, truede han den urene Aand og sagde til den: du maalløse og døve Aand! jeg byder dig, far ud af ham, og at du ikke herefter farer ind i ham."],[9,26,"Da skreg og sled den ham saare, og foer ud, og han blev ligesom død, saa at Mange sagde: han er død.","Da skreg og sled den ham saare, og foer ud, og han blev ligesom død, saa at Mange sagde: han er død."],[9,27,"Men Jesus tog ham fat ved Haanden og reiste ham op; og han stod op.","Men Jesus tog ham fat ved Haanden og reiste ham op; og han stod op."],[9,28,"Og der han var indgangen i Huset, spurgte hans Disciple ham i Eenrum: hvi kunde vi ikke uddrive den?","Og der han var indgangen i Huset, spurgte hans Disciple ham i Eenrum: hvi kunde vi ikke uddrive den?"],[9,29,"Og han sagde til dem: dette Slags kan ikke fare ud ved Noget, uden ved Bøn og Faste.","Og han sagde til dem: dette Slags kan ikke fare ud ved Noget, uden ved Bøn og Faste."],[9,30,"Og da de gik ud derfra, vandrede de igjennem Galilæa; og han vilde ikke, at Nogen skulde vide det.","Og da de gik ud derfra, vandrede de igjennem Galilæa; og han vilde ikke, at Nogen skulde vide det."],[9,31,"Thi han lærte sine Disciple og sagde til dem: Menneskens Søn skal overantvordes i Menneskenes Hænder, og de skulde ihjelslaae ham; og naar han er ihjelslagen, skal han opstaae paa den tredie Dag.","Thi han lærte sine Disciple og sagde til dem: Menneskens Søn skal overantvordes i Menneskenes Hænder, og de skulde ihjelslaae ham; og naar han er ihjelslagen, skal han opstaae paa den tredie Dag."],[9,32,"Men de forstode ikke det Ord og frygtede at spørge ham.","Men de forstode ikke det Ord og frygtede at spørge ham."],[9,33,"Og han kom til Capernaum, og der han var i Huset, spurgte han dem: hvorom bespurgte I Eder indbyrdes paa Veien?","Og han kom til Capernaum, og der han var i Huset, spurgte han dem: hvorom bespurgte I Eder indbyrdes paa Veien?"],[9,34,"Men de taug, thi de havde bespurgt sig med hverandre paa Veien, hvilken der skulde være den Største.","Men de taug, thi de havde bespurgt sig med hverandre paa Veien, hvilken der skulde være den Største."],[9,35,"Og han satte sig og kaldte de Tolv og sagde til dem: dersom Nogen vil være den Første, han skal være den Sidste iblandt Alle og Alles Tjener.","Og han satte sig og kaldte de Tolv og sagde til dem: dersom Nogen vil være den Første, han skal være den Sidste iblandt Alle og Alles Tjener."],[9,36,"Og han tog et lidet Barn, og stillede det midt iblandt dem, og tog det i Favn og sagde til dem:","Og han tog et lidet Barn, og stillede det midt iblandt dem, og tog det i Favn og sagde til dem:"],[9,37,"hvo som annammer eet af saadanne smaa Børn i mit Navn, annammer mig; og hvo mig annammer, annammer ikke mig, men den, som mig udsendte.","hvo som annammer eet af saadanne smaa Børn i mit Navn, annammer mig; og hvo mig annammer, annammer ikke mig, men den, som mig udsendte."],[9,38,"Men Johannes svarede ham og sagde: Mester! vi saae En, som ikke følger os, at uddrive Djævle i dit Navn; og vi forbøde ham det, fordi han ikke følger os.","Men Johannes svarede ham og sagde: Mester! vi saae En, som ikke følger os, at uddrive Djævle i dit Navn; og vi forbøde ham det, fordi han ikke følger os."],[9,39,"Men Jesus sagde: forbyder ham det ikke; thi der er Ingen, som gjør en kraftig Gjerning i mit Navn, og kan snart derpaa tale ilde om mig.","Men Jesus sagde: forbyder ham det ikke; thi der er Ingen, som gjør en kraftig Gjerning i mit Navn, og kan snart derpaa tale ilde om mig."],[9,40,"Thi hvo som ikke er imod os, er med os.","Thi hvo som ikke er imod os, er med os."],[9,41,"Thi hvo som skjenker Eder med et Bæger Vand i mit Navn, fordi I høre Christus til, sandelig siger jeg Eder, han skal ingenlunde miste sin Løn.","Thi hvo som skjenker Eder med et Bæger Vand i mit Navn, fordi I høre Christus til, sandelig siger jeg Eder, han skal ingenlunde miste sin Løn."],[9,42,"Og hvo som forarger een af disse Smaa, som troe paa mig, ham vare det bedre, at der blev hængt en Møllesteen om hans Hals, og han blev kastet i Havet.","Og hvo som forarger een af disse Smaa, som troe paa mig, ham vare det bedre, at der blev hængt en Møllesteen om hans Hals, og han blev kastet i Havet."],[9,43,"Og dersom din Haand forarger dig, hug den af; det er dig bedre at gaae en Krøbling ind i Livet, end at have to Hænder, og fare hen til Helvede i den uslukkelige Ild,","Og dersom din Haand forarger dig, hug den af; det er dig bedre at gaae en Krøbling ind i Livet, end at have to Hænder, og fare hen til Helvede i den uslukkelige Ild,"],[9,44,"hvor deres Orm ikke døer, og Ilden ikke udslukkes.","hvor deres Orm ikke døer, og Ilden ikke udslukkes."],[9,45,"Og dersom din Fod forarger dig, hug den af; det er dig bedre at gaae halt ind i Livet, end at have to Fødder og blive kastet i Helvede i den uslukkelige Ild,","Og dersom din Fod forarger dig, hug den af; det er dig bedre at gaae halt ind i Livet, end at have to Fødder og blive kastet i Helvede i den uslukkelige Ild,"],[9,46,"hvor deres Orm ikke døer, og Ilden ikke udslukkes.","hvor deres Orm ikke døer, og Ilden ikke udslukkes."],[9,47,"Og dersom dit Øie forarger dig, kast det fra dig; det er dig bedre at gaae eenøiet ind i Guds Rige, end at have to Øine og blive kastet i Helvedes Ild,","Og dersom dit Øie forarger dig, kast det fra dig; det er dig bedre at gaae eenøiet ind i Guds Rige, end at have to Øine og blive kastet i Helvedes Ild,"],[9,48,"hvor deres Orm ikke døer, og Ilden ikke udslukkes.","hvor deres Orm ikke døer, og Ilden ikke udslukkes."],[9,49,"Thi hver skal saltes med Ild, og alt Offer skal saltes med Salt.","Thi hver skal saltes med Ild, og alt Offer skal saltes med Salt."],[9,50,"Saltet er godt; men dersom Saltet mister sin Kraft, hvormed ville I give det sin Smag igjen? Haver Salt i Eder selv, og holder Fred med hverandre!","Saltet er godt; men dersom Saltet mister sin Kraft, hvormed ville I give det sin Smag igjen? Haver Salt i Eder selv, og holder Fred med hverandre!"],[10,1,"Og han stod op derfra, og kom til Judæas Grændser igjennem det Land paa hiin Side Jordan, og Folket gik atter til ham i Hobetal; og han lærte dem atter, som han pleiede.","Og han stod op derfra, og kom til Judæas Grændser igjennem det Land paa hiin Side Jordan, og Folket gik atter til ham i Hobetal; og han lærte dem atter, som han pleiede."],[10,2,"Og Pharisæerne gik til ham og spurgte ham, om det var en Mand tilladt at skille sig fra sin Hustru; for at friste ham.","Og Pharisæerne gik til ham og spurgte ham, om det var en Mand tilladt at skille sig fra sin Hustru; for at friste ham."],[10,3,"Men han svarede og sagde til dem: hvad haver Moses budet Eder?","Men han svarede og sagde til dem: hvad haver Moses budet Eder?"],[10,4,"Men de sagde: Moses tilstedte at skrive et Skilsmissebrev, og skille sig fra hende.","Men de sagde: Moses tilstedte at skrive et Skilsmissebrev, og skille sig fra hende."],[10,5,"Og Jesus svarede og sagde til dem: for Eders Hjerters Haardheds Skyld skrev han Eder dette Bud.","Og Jesus svarede og sagde til dem: for Eders Hjerters Haardheds Skyld skrev han Eder dette Bud."],[10,6,"Men fra Skabningens Begyndelse gjorde Gud dem Mand og Kvinde;","Men fra Skabningens Begyndelse gjorde Gud dem Mand og Kvinde;"],[10,7,"derfor skal Manden forlade sin Fader og Moder, og blive fast hos sin Hustru;","derfor skal Manden forlade sin Fader og Moder, og blive fast hos sin Hustru;"],[10,8,"og de To skulle være til eet Kjød, saa at de ikke længere ere To, men eet Kjød.","og de To skulle være til eet Kjød, saa at de ikke længere ere To, men eet Kjød."],[10,9,"Derfor, hvad Gud haver tilsammenføiet, skal Mennesket ikke adskille.","Derfor, hvad Gud haver tilsammenføiet, skal Mennesket ikke adskille."],[10,10,"Og hans Disciple spurgte ham atter i Huset om det Samme.","Og hans Disciple spurgte ham atter i Huset om det Samme."],[10,11,"Og han sagde til dem: hvo som skiller sig fra sin Hustru, og tager en Anden tilægte, han bedriver Hoer imod hende.","Og han sagde til dem: hvo som skiller sig fra sin Hustru, og tager en Anden tilægte, han bedriver Hoer imod hende."],[10,12,"Og dersom en Kvinde skiller sig fra sin Mand og ægtes af en anden, hun bedriver Hoer.","Og dersom en Kvinde skiller sig fra sin Mand og ægtes af en anden, hun bedriver Hoer."],[10,13,"Og de førte smaa Børn til ham, at kan skulde røre ved dem; men Disciplene truede dem, som bare dem frem.","Og de førte smaa Børn til ham, at kan skulde røre ved dem; men Disciplene truede dem, som bare dem frem."],[10,14,"Men der Jesus det saae, blev han vred og sagde til dem: lader de smaa Børn komme til mig, og formener dem ikke; thi Guds Rige hører saadanne til.","Men der Jesus det saae, blev han vred og sagde til dem: lader de smaa Børn komme til mig, og formener dem ikke; thi Guds Rige hører saadanne til."],[10,15,"Sandelig siger jeg Eder: hvo som ikke annammer Guds Rige som et lidet Barn, han skal ingenlunde komme ind i det.","Sandelig siger jeg Eder: hvo som ikke annammer Guds Rige som et lidet Barn, han skal ingenlunde komme ind i det."],[10,16,"Og han tog dem i Favn, og lagde Hænderne paa dem, og velsignede dem.","Og han tog dem i Favn, og lagde Hænderne paa dem, og velsignede dem."],[10,17,"Og der han var udgangen paa Veien, løb En til, og faldt paa Knæ for ham, og spurgte ham: gode Mester! hvad skal jeg gjøre, at jeg kan arve det evige Liv?","Og der han var udgangen paa Veien, løb En til, og faldt paa Knæ for ham, og spurgte ham: gode Mester! hvad skal jeg gjøre, at jeg kan arve det evige Liv?"],[10,18,"Men Jesus sagde til ham: hvi kalder du mig god? Ingen er god uden een, som er Gud.","Men Jesus sagde til ham: hvi kalder du mig god? Ingen er god uden een, som er Gud."],[10,19,"Du veed Budene: du skal ikke bedrive Hoer; du skal ikke slaae ihjel; du skal ikke stjæle; du skal ikke tale falsk Vidnesbyrd; du skal ikke besvige; ær din Fader og din Moder.","Du veed Budene: du skal ikke bedrive Hoer; du skal ikke slaae ihjel; du skal ikke stjæle; du skal ikke tale falsk Vidnesbyrd; du skal ikke besvige; ær din Fader og din Moder."],[10,20,"Men han svarede og sagde til ham: Mester! alt dette haver jeg holdt fra min Ungdom.","Men han svarede og sagde til ham: Mester! alt dette haver jeg holdt fra min Ungdom."],[10,21,"Men Jesus saae paa ham, og fattede Kjærlighed til ham, og sagde til ham: een Ting fattes dig; gak bort, sælg, hvad du haver, og giv de Fattige det, saa skal du have et Liggendefæ i Himmelen; og kom, tag Korset og følg mig.","Men Jesus saae paa ham, og fattede Kjærlighed til ham, og sagde til ham: een Ting fattes dig; gak bort, sælg, hvad du haver, og giv de Fattige det, saa skal du have et Liggendefæ i Himmelen; og kom, tag Korset og følg mig."],[10,22,"Men han blev ilde tilfreds over den Tale og gik bedrøvet bort; thi han havde meget Gods.","Men han blev ilde tilfreds over den Tale og gik bedrøvet bort; thi han havde meget Gods."],[10,23,"Og Jesus saae sig omkring og sagde til sine Disciple: hvor vanskelig skulle de, som have Rigdom, komme ind i Guds Rige.","Og Jesus saae sig omkring og sagde til sine Disciple: hvor vanskelig skulle de, som have Rigdom, komme ind i Guds Rige."],[10,24,"Men Disciplene bleve forfærdede over hans Taler. Men Jesus svarede igjen og sagde til dem: Børn! hvor vanskeligt er det, at de, som forlade sig paa Rigdom, kunne komme ind i Guds Rige.","Men Disciplene bleve forfærdede over hans Taler. Men Jesus svarede igjen og sagde til dem: Børn! hvor vanskeligt er det, at de, som forlade sig paa Rigdom, kunne komme ind i Guds Rige."],[10,25,"Det er lettere, at en Kameel gaaer igjennem et Naaleøie, end at en Rig kommer ind i Guds Rige.","Det er lettere, at en Kameel gaaer igjennem et Naaleøie, end at en Rig kommer ind i Guds Rige."],[10,26,"Da forfærdedes de end meget mere og sagde til hverandre: hvo kan da blive salig?","Da forfærdedes de end meget mere og sagde til hverandre: hvo kan da blive salig?"],[10,27,"Men Jesus saae paa dem og sagde: for Menneskene er det umuligt, men ikke for Gud; thi alle Ting ere mulige for Gud.","Men Jesus saae paa dem og sagde: for Menneskene er det umuligt, men ikke for Gud; thi alle Ting ere mulige for Gud."],[10,28,"Men Peter tog til Orde og sagde til ham: see, vi have forladt alle Ting og fulgt dig.","Men Peter tog til Orde og sagde til ham: see, vi have forladt alle Ting og fulgt dig."],[10,29,"Men Jesus svarede og sagde: sandelig siger jeg Eder, der er Ingen, som haver forladt Huus eller Brødre eller Søstre eller Fader eller Moder eller Hustru eller Børn eller Agre for min og Evangeliums Skyld,","Men Jesus svarede og sagde: sandelig siger jeg Eder, der er Ingen, som haver forladt Huus eller Brødre eller Søstre eller Fader eller Moder eller Hustru eller Børn eller Agre for min og Evangeliums Skyld,"],[10,30,"der jo skal faae hundrede Fold igjen, nu i denne Tid Huse og Brødre og Søstre og Mødre og Børn og Agre med Forfølgelser, og i den tilkommende Verden et evigt Liv.","der jo skal faae hundrede Fold igjen, nu i denne Tid Huse og Brødre og Søstre og Mødre og Børn og Agre med Forfølgelser, og i den tilkommende Verden et evigt Liv."],[10,31,"Men Mange, som ere de Første, skulle blive de Sidste, og de Sidste blive de Første.","Men Mange, som ere de Første, skulle blive de Sidste, og de Sidste blive de Første."],[10,32,"Men de vare paa Veien, og gik op til Jerusalem; og Jesus gik foran dem, og de vare forfærdede og fulgte ham med Frygt. Og han tog atter de Tolv til sig og begyndte at sige dem, hvad han skulde vederfares.","Men de vare paa Veien, og gik op til Jerusalem; og Jesus gik foran dem, og de vare forfærdede og fulgte ham med Frygt. Og han tog atter de Tolv til sig og begyndte at sige dem, hvad han skulde vederfares."],[10,33,"See, vi gaae op til Jerusalem og Menneskens Søn skal overantvordes de Ypperstepræster og Skriftkloge, og de skulle fordømme ham til Døden, og overantvorde Hedninger ham;","See, vi gaae op til Jerusalem og Menneskens Søn skal overantvordes de Ypperstepræster og Skriftkloge, og de skulle fordømme ham til Døden, og overantvorde Hedninger ham;"],[10,34,"og de skulle bespotte ham og hudstryge ham, og bespytte ham og ihjelslaae ham, og paa den tredie Dag skal han opstaae.","og de skulle bespotte ham og hudstryge ham, og bespytte ham og ihjelslaae ham, og paa den tredie Dag skal han opstaae."],[10,35,"Da gik Jakob og Johannes, Zebedæus’ Sønner, til ham og sagde: Mester, vi ønske, at du tilstaaer os det, vi ville bede om.","Da gik Jakob og Johannes, Zebedæus’ Sønner, til ham og sagde: Mester, vi ønske, at du tilstaaer os det, vi ville bede om."],[10,36,"Han sagde til dem: hvad ville I, at jeg skal gjøre Eder?","Han sagde til dem: hvad ville I, at jeg skal gjøre Eder?"],[10,37,"Men de sagde til ham: giv os, at vi maa sidde den ene ved din høire Side og den anden ved din venstre Side, i din Herlighed.","Men de sagde til ham: giv os, at vi maa sidde den ene ved din høire Side og den anden ved din venstre Side, i din Herlighed."],[10,38,"Men Jesus sagde til dem: I vide ikke, hvad I bede. Kunne I drikke den Kalk, som jeg drikker, og døbes med den Daab, som jeg døbes med?","Men Jesus sagde til dem: I vide ikke, hvad I bede. Kunne I drikke den Kalk, som jeg drikker, og døbes med den Daab, som jeg døbes med?"],[10,39,"Men de sagde til ham: vi kunne. Men Jesus sagde til dem: I skulle vel drikke den Kalk, som jeg drikker, og døbes med den Daab, som jeg døbes med;","Men de sagde til ham: vi kunne. Men Jesus sagde til dem: I skulle vel drikke den Kalk, som jeg drikker, og døbes med den Daab, som jeg døbes med;"],[10,40,"men at sidde ved min høire og ved min venstre Side, hører ikke mig til at give Nogen, uden den, som det er beredt.","men at sidde ved min høire og ved min venstre Side, hører ikke mig til at give Nogen, uden den, som det er beredt."],[10,41,"Og der de Ti hørte det, begyndte de at blive vrede paa Jakob og Johannes.","Og der de Ti hørte det, begyndte de at blive vrede paa Jakob og Johannes."],[10,42,"Da kaldte Jesus dem og sagde til dem: I vide, at de, der ere i Anseelse som Folkenes Fyrster, herske over dem, og de Store iblandt dem bruge Myndighed over dem.","Da kaldte Jesus dem og sagde til dem: I vide, at de, der ere i Anseelse som Folkenes Fyrster, herske over dem, og de Store iblandt dem bruge Myndighed over dem."],[10,43,"Men det skal ikke være saa iblandt Eder; men hvo som vil blive stor iblandt Eder, skal være Eders Tjener;","Men det skal ikke være saa iblandt Eder; men hvo som vil blive stor iblandt Eder, skal være Eders Tjener;"],[10,44,"og hvo som vil blive den Ypperste iblandt Eder, skal være Alles Tjener;","og hvo som vil blive den Ypperste iblandt Eder, skal være Alles Tjener;"],[10,45,"thi Menneskens Søn er ikke kommen for at lade sig tjene, men for at tjene; og at give sit Liv til en Igjenløselses Betaling for Mange.","thi Menneskens Søn er ikke kommen for at lade sig tjene, men for at tjene; og at give sit Liv til en Igjenløselses Betaling for Mange."],[10,46,"Og de kom til Jericho; og der han gik ud af Jericho tilligemed sine Disciple og meget Folk, sad Timæus’ Søn, Bartimæus den Blinde, ved Veien og tiggede.","Og de kom til Jericho; og der han gik ud af Jericho tilligemed sine Disciple og meget Folk, sad Timæus’ Søn, Bartimæus den Blinde, ved Veien og tiggede."],[10,47,"Og der han hørte, at det var Jesus fra Nazareth, begyndte han at raabe og sige: Jesus, du Davids Søn, forbarm dig over mig.","Og der han hørte, at det var Jesus fra Nazareth, begyndte han at raabe og sige: Jesus, du Davids Søn, forbarm dig over mig."],[10,48,"Og Mange truede ham, at han skulde tie; men han raabte meget mere: du Davids Søn, forbarm dig over mig!","Og Mange truede ham, at han skulde tie; men han raabte meget mere: du Davids Søn, forbarm dig over mig!"],[10,49,"Og Jesus stod stille og sagde, de skulde kalde ham; og de kaldte den Blinde og sagde til ham: vær frimodig, staa op! han kalder ad dig.","Og Jesus stod stille og sagde, de skulde kalde ham; og de kaldte den Blinde og sagde til ham: vær frimodig, staa op! han kalder ad dig."],[10,50,"Men han kastede sin Overkjortel fra sig, stod op og kom til Jesus.","Men han kastede sin Overkjortel fra sig, stod op og kom til Jesus."],[10,51,"Og Jesus svarede og sagde til ham: hvad vil du, at jeg skal gjøre dig? Men den Blinde sagde til ham: Rabbuni, at jeg kan vorde seende!","Og Jesus svarede og sagde til ham: hvad vil du, at jeg skal gjøre dig? Men den Blinde sagde til ham: Rabbuni, at jeg kan vorde seende!"],[10,52,"Men Jesus sagde til ham: gak bort, din Tro haver frelst dig. Og strax blev han seende og fulgte Jesus paa Veien.","Men Jesus sagde til ham: gak bort, din Tro haver frelst dig. Og strax blev han seende og fulgte Jesus paa Veien."],[11,1,"Og der de kom nær til Jerusalem, til Bethphage og Bethanien ved Oliebjerget, sendte han to af sine Disciple og sagde til dem:","Og der de kom nær til Jerusalem, til Bethphage og Bethanien ved Oliebjerget, sendte han to af sine Disciple og sagde til dem:"],[11,2,"gaaer bort til den By, som ligger for Eder, og strax, naar I komme ind i den, skulle I finde et Føl bundet, paa hvilket intet Menneske haver siddet; løser det og fører det hid.","gaaer bort til den By, som ligger for Eder, og strax, naar I komme ind i den, skulle I finde et Føl bundet, paa hvilket intet Menneske haver siddet; løser det og fører det hid."],[11,3,"Og dersom Nogen siger til Eder: hvorfor gjøre I dette? da siger, at Herren haver det behov; saa skal han strax sende det hid.","Og dersom Nogen siger til Eder: hvorfor gjøre I dette? da siger, at Herren haver det behov; saa skal han strax sende det hid."],[11,4,"Men de gik hen og fandt Føllet bundet ved Døren, udenfor paa Veien, og løste det.","Men de gik hen og fandt Føllet bundet ved Døren, udenfor paa Veien, og løste det."],[11,5,"Og Nogle af dem som der stode, sagde til dem: hvad gjøre I, at I løse Føllet?","Og Nogle af dem som der stode, sagde til dem: hvad gjøre I, at I løse Føllet?"],[11,6,"Men de sagde til dem, ligesom Jesus havde befalet, og de tilstedte dem det.","Men de sagde til dem, ligesom Jesus havde befalet, og de tilstedte dem det."],[11,7,"Og de førte Føllet til Jesus, og lagde deres Klæder derpaa, og han satte sig derpaa.","Og de førte Føllet til Jesus, og lagde deres Klæder derpaa, og han satte sig derpaa."],[11,8,"Men Mange bredte deres Klæder paa Veien; men Andre huggede Grene af Træerne og strøede paa Veien.","Men Mange bredte deres Klæder paa Veien; men Andre huggede Grene af Træerne og strøede paa Veien."],[11,9,"Og de, som gik for, og de, som fulgte, raabte og sagde: Hosanna, velsignet være den, som kommer i Herrens Navn!","Og de, som gik for, og de, som fulgte, raabte og sagde: Hosanna, velsignet være den, som kommer i Herrens Navn!"],[11,10,"Velsignet være vor Fader Davids Rige, som kommer i Herrens Navn! Hosanna i det Høieste!","Velsignet være vor Fader Davids Rige, som kommer i Herrens Navn! Hosanna i det Høieste!"],[11,11,"Og Jesus gik ind i Jerusalem og i Templet, og da han havde beseet alle Ting, gik ham, der det allerede var Aftenstid, ud til Bethanien med de tolv.","Og Jesus gik ind i Jerusalem og i Templet, og da han havde beseet alle Ting, gik ham, der det allerede var Aftenstid, ud til Bethanien med de tolv."],[11,12,"Og den anden Dag, der de gik ud fra Bethanien, hungrede han.","Og den anden Dag, der de gik ud fra Bethanien, hungrede han."],[11,13,"Og han saae et Figentræ langt borte, som havde Blade; da traadte han til, om han kunde finde Noget derpaa, og der han kom til det, fandt han Intet uden Blade; thi det var ikke Figentid.","Og han saae et Figentræ langt borte, som havde Blade; da traadte han til, om han kunde finde Noget derpaa, og der han kom til det, fandt han Intet uden Blade; thi det var ikke Figentid."],[11,14,"Og Jesus talede til det: aldrig mere æde Nogen Frugt af dig! Og hans Disciple hørte det.","Og Jesus talede til det: aldrig mere æde Nogen Frugt af dig! Og hans Disciple hørte det."],[11,15,"Og de kom til Jerusalem; og Jesus gik ind i Templet og begyndte at uddrive dem, som solgte og kjøbte i Templet, og Vexelerernes Borde og Duekræmmernes Stole stødte han om.","Og de kom til Jerusalem; og Jesus gik ind i Templet og begyndte at uddrive dem, som solgte og kjøbte i Templet, og Vexelerernes Borde og Duekræmmernes Stole stødte han om."],[11,16,"Og han tilstedte ikke, at Nogen bar et Kar igjennem Templet.","Og han tilstedte ikke, at Nogen bar et Kar igjennem Templet."],[11,17,"Og han lærte og sagde til dem: er der ikke skrevet, at mit Huus skal kaldes et Bedehuus for alle Folkeslag? men I have gjort det til en Røverkule.","Og han lærte og sagde til dem: er der ikke skrevet, at mit Huus skal kaldes et Bedehuus for alle Folkeslag? men I have gjort det til en Røverkule."],[11,18,"Og de Skriftkloge og Ypperstepræster hørte det, og søgte, hvorledes de kunde omkomme ham; thi de frygtede for ham, eftersom alt Folket forundrede sig saare over hans Lærdom.","Og de Skriftkloge og Ypperstepræster hørte det, og søgte, hvorledes de kunde omkomme ham; thi de frygtede for ham, eftersom alt Folket forundrede sig saare over hans Lærdom."],[11,19,"Og da det var blevet Aften, gik han udenfor Staden.","Og da det var blevet Aften, gik han udenfor Staden."],[11,20,"Og om Morgenen, da de gik forbi, saae de, at Figentræet var visnet fra Roden af.","Og om Morgenen, da de gik forbi, saae de, at Figentræet var visnet fra Roden af."],[11,21,"Og da Peter kom det ihu, sagde han til ham: Rabbi! see Figentræet, det, du forbandede, er visnet.","Og da Peter kom det ihu, sagde han til ham: Rabbi! see Figentræet, det, du forbandede, er visnet."],[11,22,"Og Jesus svarede og sagde til dem: haver Tro til Gud.","Og Jesus svarede og sagde til dem: haver Tro til Gud."],[11,23,"Thi sandelig siger jeg Eder: at hvo som vilde sige til dette Bjerg: løft dig op, og kast dig i Havet, og ikke vilde tvivle i sit Hjerte, men troe, at det skal skee, som han siger, ham skal det skee, som han sagde.","Thi sandelig siger jeg Eder: at hvo som vilde sige til dette Bjerg: løft dig op, og kast dig i Havet, og ikke vilde tvivle i sit Hjerte, men troe, at det skal skee, som han siger, ham skal det skee, som han sagde."],[11,24,"Derfor siger jeg Eder: Alt, hvad I begjere i Bønnen, troer, at I skulle faae det, saa skal det vederfares Eder.","Derfor siger jeg Eder: Alt, hvad I begjere i Bønnen, troer, at I skulle faae det, saa skal det vederfares Eder."],[11,25,"Og naar I staae og bede, forlader, dersom I have Noget imod Nogen, at og Eders Fader, som er i Himlene, maa forlade Eder Eders Overtrædelser.","Og naar I staae og bede, forlader, dersom I have Noget imod Nogen, at og Eders Fader, som er i Himlene, maa forlade Eder Eders Overtrædelser."],[11,26,"Men dersom I ikke forlade, skal Eders Fader, som er i Himlene, ei heller forlade Eder Eders Overtrædelser.","Men dersom I ikke forlade, skal Eders Fader, som er i Himlene, ei heller forlade Eder Eders Overtrædelser."],[11,27,"Og de kom atter til Jerusalem; og der han gik i Templet, kom de Ypperstepræster og Skriftkloge og de Ældste til ham.","Og de kom atter til Jerusalem; og der han gik i Templet, kom de Ypperstepræster og Skriftkloge og de Ældste til ham."],[11,28,"Og de sagde til ham: af hvad Magt gjør du disse Ting? og hvo haver givet dig denne Magt, at du gjør disse Ting.","Og de sagde til ham: af hvad Magt gjør du disse Ting? og hvo haver givet dig denne Magt, at du gjør disse Ting."],[11,29,"Men Jesus svarede og sagde til dem: ogsaa jeg vil spørge Eder om een Sag, og svarer mig, saa vil jeg og sige Eder, af hvad Magt jeg gjør disse Ting.","Men Jesus svarede og sagde til dem: ogsaa jeg vil spørge Eder om een Sag, og svarer mig, saa vil jeg og sige Eder, af hvad Magt jeg gjør disse Ting."],[11,30,"Johannes’ Daab, var den af Himmelen eller af Mennesker? Svarer mig.","Johannes’ Daab, var den af Himmelen eller af Mennesker? Svarer mig."],[11,31,"Og de tænkte ved sig selv og sagde: sige vi, den var af Himmelen, da siger han: hvi troede I ham da ikke?","Og de tænkte ved sig selv og sagde: sige vi, den var af Himmelen, da siger han: hvi troede I ham da ikke?"],[11,32,"Men sige vi, den var af Mennesker, da frygtede de for for Folket; thi Alle holdt for, at Johannes virkelig var en Prophet.","Men sige vi, den var af Mennesker, da frygtede de for for Folket; thi Alle holdt for, at Johannes virkelig var en Prophet."],[11,33,"Og de svarede og sagde til Jesus: vi vide ikke. Og Jesus svarede og sagde dem: saa siger jeg Eder og ikke, af hvad Magt jeg gjør disse Ting.","Og de svarede og sagde til Jesus: vi vide ikke. Og Jesus svarede og sagde dem: saa siger jeg Eder og ikke, af hvad Magt jeg gjør disse Ting."],[12,1,"Og han begyndte at tale med dem ved Lignelser: et Menneske plantede en Viingaard og gjorde et Gjerde derom, og grov en Perse og byggede et Taarn, og leiede den til Viingaardsmænd, og drog udenlands.","Og han begyndte at tale med dem ved Lignelser: et Menneske plantede en Viingaard og gjorde et Gjerde derom, og grov en Perse og byggede et Taarn, og leiede den til Viingaardsmænd, og drog udenlands."],[12,2,"Og der Tiden kom, sendte han en Tjener til Viingaardsmændene, at han af Viingaardsmændene skulle modtage af Viintræets Frugt.","Og der Tiden kom, sendte han en Tjener til Viingaardsmændene, at han af Viingaardsmændene skulle modtage af Viintræets Frugt."],[12,3,"Men de grebe ham og sloge ham, og lode ham tomhændet fra sig.","Men de grebe ham og sloge ham, og lode ham tomhændet fra sig."],[12,4,"Og han sendte atter en anden Tjener til dem; og denne sloge de med Stene og saarede hans Hoved og lode ham forhaanet fra sig.","Og han sendte atter en anden Tjener til dem; og denne sloge de med Stene og saarede hans Hoved og lode ham forhaanet fra sig."],[12,5,"Og han sendte atter en Anden, og denne sloge de ihjel; og mange Andre, Nogle sloge de, men Nogle dræbte de.","Og han sendte atter en Anden, og denne sloge de ihjel; og mange Andre, Nogle sloge de, men Nogle dræbte de."],[12,6,"Men eftersom han endnu havde een Søn, sin Elskelige, sendte han tilsidst ogsaa denne til dem, og sagde; de skulle dog undsee sig for min Søn.","Men eftersom han endnu havde een Søn, sin Elskelige, sendte han tilsidst ogsaa denne til dem, og sagde; de skulle dog undsee sig for min Søn."],[12,7,"Men hine Viingaardsmænd sagde til hverandre: denne er Arvingen, kommer, lader os slaae ham ihjel, saa bliver Arven vores.","Men hine Viingaardsmænd sagde til hverandre: denne er Arvingen, kommer, lader os slaae ham ihjel, saa bliver Arven vores."],[12,8,"Og de grebe ham og sloge ham ihjel, og kastede ham udenfor Viingaarden.","Og de grebe ham og sloge ham ihjel, og kastede ham udenfor Viingaarden."],[12,9,"Hvad skal de Viingaardens Herre gjøre? Han skal komme og ødelægge Viingaardsmændene, og leie Viingaarden til Andre.","Hvad skal de Viingaardens Herre gjøre? Han skal komme og ødelægge Viingaardsmændene, og leie Viingaarden til Andre."],[12,10,"Da sagde Jesus: have I ikke læst, hvad skrevet er: den Steen, som Bygningsmændene forskøde, den er bleven til en Hovedhjørnesteen?","Da sagde Jesus: have I ikke læst, hvad skrevet er: den Steen, som Bygningsmændene forskøde, den er bleven til en Hovedhjørnesteen?"],[12,11,"Det er skeet af Herren, og er underligt for vore Øine","Det er skeet af Herren, og er underligt for vore Øine"],[12,12,"Og de søgte at gribe ham, men de frygtede for Folket; thi de forstode, at han sagde denne Lignelse imod dem; og de forlode ham og gik bort.","Og de søgte at gribe ham, men de frygtede for Folket; thi de forstode, at han sagde denne Lignelse imod dem; og de forlode ham og gik bort."],[12,13,"Og de sendte Nogle til ham af Pharisæerne og af de Herodianer, at de skulde fange ham i Ord.","Og de sendte Nogle til ham af Pharisæerne og af de Herodianer, at de skulde fange ham i Ord."],[12,14,"Men de kom og sagde til ham: Mester! vi vide, at du er sanddru, og skjøtter om Ingen; thi du anseer ikke Menneskers Person, men lærer Guds Vei i Sandhed. Er det tilladt at give Keiseren Skat, eller ei? skulle vi give eller ikke give?","Men de kom og sagde til ham: Mester! vi vide, at du er sanddru, og skjøtter om Ingen; thi du anseer ikke Menneskers Person, men lærer Guds Vei i Sandhed. Er det tilladt at give Keiseren Skat, eller ei? skulle vi give eller ikke give?"],[12,15,"Men da han vidste deres Øienskalkhed, sagde han til dem: hvi friste I mig? Tager mig hid en Penge, at jeg kan see den.","Men da han vidste deres Øienskalkhed, sagde han til dem: hvi friste I mig? Tager mig hid en Penge, at jeg kan see den."],[12,16,"Men de bragte den frem. Og han sagde til dem: hvis er dette Billede og Overskrift? Men de sagde til ham: Keiserens.","Men de bragte den frem. Og han sagde til dem: hvis er dette Billede og Overskrift? Men de sagde til ham: Keiserens."],[12,17,"Og Jesus svarede og sagde til dem: giver Keiseren, hvad Keiserens er, og Gud, hvad Guds er. Og de forundrede sig over ham.","Og Jesus svarede og sagde til dem: giver Keiseren, hvad Keiserens er, og Gud, hvad Guds er. Og de forundrede sig over ham."],[12,18,"Og Sadducæer kom til ham, hvilke sige, at der ikke er Opstandelse; og de adspurgte ham og sagde:","Og Sadducæer kom til ham, hvilke sige, at der ikke er Opstandelse; og de adspurgte ham og sagde:"],[12,19,"Mester! Moses foreskrev os, at naar Nogens Broder døer, og efterlader en Hustru, men efterlader ikke Børn, da skal hans Broder tage hans Hustru og opreise sin Broder Sæd.","Mester! Moses foreskrev os, at naar Nogens Broder døer, og efterlader en Hustru, men efterlader ikke Børn, da skal hans Broder tage hans Hustru og opreise sin Broder Sæd."],[12,20,"Nu have der været syv Brødre, og den første tog en Hustru, og døde, og efterlod ikke Sæd.","Nu have der været syv Brødre, og den første tog en Hustru, og døde, og efterlod ikke Sæd."],[12,21,"Og den anden tog hende, og døde, og han efterlod ikke Sæd, og den tredie ligesaa.","Og den anden tog hende, og døde, og han efterlod ikke Sæd, og den tredie ligesaa."],[12,22,"Og de toge hende alle syv ,og efterlade ikke Sæd. Sidst af dem alle døde og Kvinden.","Og de toge hende alle syv ,og efterlade ikke Sæd. Sidst af dem alle døde og Kvinden."],[12,23,"I Opstandelsen nu, naar de opstaae, hvis Hustru af disse skal hun være? thi de have alle syv havt hende til Hustru.","I Opstandelsen nu, naar de opstaae, hvis Hustru af disse skal hun være? thi de have alle syv havt hende til Hustru."],[12,24,"Da svarede Jesus og sagde til dem: fare I ikke derfor vild, at I ikke kjende Skrifterne, ei heller Guds Kraft?","Da svarede Jesus og sagde til dem: fare I ikke derfor vild, at I ikke kjende Skrifterne, ei heller Guds Kraft?"],[12,25,"Thi naar de ere opstandne fra de Døde, da hverken gifte de sig, ei heller giftes, men de ere som Engle i Himlene.","Thi naar de ere opstandne fra de Døde, da hverken gifte de sig, ei heller giftes, men de ere som Engle i Himlene."],[12,26,"Men om de Døde, at de opstaae, have I ikke læst i Mosebog i Stedet om Tornebusken, hvorledes Gud talede til ham og sagde: jeg er Abrahams Gud, og Isaaks Gud og Jakobs Gud.","Men om de Døde, at de opstaae, have I ikke læst i Mosebog i Stedet om Tornebusken, hvorledes Gud talede til ham og sagde: jeg er Abrahams Gud, og Isaaks Gud og Jakobs Gud."],[12,27,"Gud er ikke de Dødes, men de Levendes Gud; derfor fare I meget vild.","Gud er ikke de Dødes, men de Levendes Gud; derfor fare I meget vild."],[12,28,"Og een af de Skriftkloge, som havde hørt dem, da de bespurgte sig med hverandre, gik til ham, og eftersom han skjønnede, at han havde svaret dem vel, spurgte han ham ad: hvilket er det fornemste Bud af alle?","Og een af de Skriftkloge, som havde hørt dem, da de bespurgte sig med hverandre, gik til ham, og eftersom han skjønnede, at han havde svaret dem vel, spurgte han ham ad: hvilket er det fornemste Bud af alle?"],[12,29,"Men Jesus svarede ham: det første Bud af alle er dette: hør, Israel! Herren, vor Gud, Herren er een;","Men Jesus svarede ham: det første Bud af alle er dette: hør, Israel! Herren, vor Gud, Herren er een;"],[12,30,"og du skal elske Herren din Gud af dit ganske Hjerte, og af din ganske Sjæl, og af dit ganske Sind, og af din ganske Styrke, dette er det første Bud.","og du skal elske Herren din Gud af dit ganske Hjerte, og af din ganske Sjæl, og af dit ganske Sind, og af din ganske Styrke, dette er det første Bud."],[12,31,"Og det andet, ligt dette, er: du skal elske din Næste ligesom dig selv. Der er intet andet Bud større end disse.","Og det andet, ligt dette, er: du skal elske din Næste ligesom dig selv. Der er intet andet Bud større end disse."],[12,32,"Og den Skriftkloge sagde til ham: Mester! du haver talet vel og efter Sandhed; thi der er een Gud, og der er ingen anden foruden ham.","Og den Skriftkloge sagde til ham: Mester! du haver talet vel og efter Sandhed; thi der er een Gud, og der er ingen anden foruden ham."],[12,33,"Og at elske ham af ganske Hjerte, og af ganske Forstand, og af ganske Sjæl, og af ganske Styrke, og at elske sin Næste ligesom sig selv, er mere end alle Brænd-Offere og Slagt-Offere.","Og at elske ham af ganske Hjerte, og af ganske Forstand, og af ganske Sjæl, og af ganske Styrke, og at elske sin Næste ligesom sig selv, er mere end alle Brænd-Offere og Slagt-Offere."],[12,34,"Og der Jesus saae, at han svarede forstandigen, sagde han til ham: du er ikke langt fra Guds Rige. Og der turde Ingen spørge ham ydermere.","Og der Jesus saae, at han svarede forstandigen, sagde han til ham: du er ikke langt fra Guds Rige. Og der turde Ingen spørge ham ydermere."],[12,35,"Og der Jesus lærte i Templet, tog han til Orde og sagde: hvorledes sige de Skriftkloge, at Christus er Davids Søn!","Og der Jesus lærte i Templet, tog han til Orde og sagde: hvorledes sige de Skriftkloge, at Christus er Davids Søn!"],[12,36,"Thi David siger selv, dreven af den Hellig Aand: Herren sagde til min Herre: sæt dig ved min høire Haand, indtil jeg lægger dine Fjender til dine Fødders Skammel.","Thi David siger selv, dreven af den Hellig Aand: Herren sagde til min Herre: sæt dig ved min høire Haand, indtil jeg lægger dine Fjender til dine Fødders Skammel."],[12,37,"Altsaa kalder da David ham selv en Herre; hvorledes er han da hans Søn? Og meget Folk hørte han gjerne.","Altsaa kalder da David ham selv en Herre; hvorledes er han da hans Søn? Og meget Folk hørte han gjerne."],[12,38,"Og han sagde dem i sin Underviisning: tager Eder vare for de Skriftkloge, som gjerne gaae i lange Klæder og lade sig hilse paa Torvene,","Og han sagde dem i sin Underviisning: tager Eder vare for de Skriftkloge, som gjerne gaae i lange Klæder og lade sig hilse paa Torvene,"],[12,39,"og ville have de fornemste Stolestader i Synagogerne, og sidde øverst til Bords i Nadverne;","og ville have de fornemste Stolestader i Synagogerne, og sidde øverst til Bords i Nadverne;"],[12,40,"de, som opæde Enkers Huse, og paa Skrømt bede længe, disse skulle faae des haardere Dom.","de, som opæde Enkers Huse, og paa Skrømt bede længe, disse skulle faae des haardere Dom."],[12,41,"Og Jesus satte sig lige overfor Templets Kiste og saae, hvorledes Folket lagde Penge i Kisten, og mange Rige lagde meget derudi.","Og Jesus satte sig lige overfor Templets Kiste og saae, hvorledes Folket lagde Penge i Kisten, og mange Rige lagde meget derudi."],[12,42,"Og en fattig Enke kom og lagde to Skjerve udi, som er en Hvid.","Og en fattig Enke kom og lagde to Skjerve udi, som er en Hvid."],[12,43,"Og han kaldte sine Disciple til sig og sagde til dem: sandelig siger jeg Eder, at denne fattige Enke haver lagt mere deri, end alle de, som lade i Kisten.","Og han kaldte sine Disciple til sig og sagde til dem: sandelig siger jeg Eder, at denne fattige Enke haver lagt mere deri, end alle de, som lade i Kisten."],[12,44,"Thi de lagde alle af deres Overlod; men denne lagde af sin Fattigdom alt det, hun havde, hendes ganske Eiendom.","Thi de lagde alle af deres Overlod; men denne lagde af sin Fattigdom alt det, hun havde, hendes ganske Eiendom."],[13,1,"Og der han gik ud af Templet, siger een af hans Disciple til ham: Mester, see, hvilke Stene og hvilke Bygninger.","Og der han gik ud af Templet, siger een af hans Disciple til ham: Mester, see, hvilke Stene og hvilke Bygninger."],[13,2,"Og Jesus svarede og sagde til ham: seer du disse store Bygninger? Der skal ikke lades Steen paa Steen, som jo skal nedbrydes.","Og Jesus svarede og sagde til ham: seer du disse store Bygninger? Der skal ikke lades Steen paa Steen, som jo skal nedbrydes."],[13,3,"Og der han sad paa Oliebjerget, tvert over for Templet, spurgte Peter og Jakob og Johannes og Andreas ham i Eenrum:","Og der han sad paa Oliebjerget, tvert over for Templet, spurgte Peter og Jakob og Johannes og Andreas ham i Eenrum:"],[13,4,"siig os, naar skulle disse Ting skee? og hvad Tegn skal der være, naar alt dette skal fuldkommes?","siig os, naar skulle disse Ting skee? og hvad Tegn skal der være, naar alt dette skal fuldkommes?"],[13,5,"Men Jesus svarede dem og begyndte at sige: seer til, at ikke Nogen forfører Eder.","Men Jesus svarede dem og begyndte at sige: seer til, at ikke Nogen forfører Eder."],[13,6,"Thi Mange skulle komme i mit Navn og sige: jeg er Christus; og de skulle forføre Mange.","Thi Mange skulle komme i mit Navn og sige: jeg er Christus; og de skulle forføre Mange."],[13,7,"Men naar I høre Krig og Rygte om Krig, da forskrækkes ikke, thi det maa skee, men Enden er ikke endda.","Men naar I høre Krig og Rygte om Krig, da forskrækkes ikke, thi det maa skee, men Enden er ikke endda."],[13,8,"Thi Folk skal reise sig imod Folk, og Rige imod Rige, og der skal skee Jordskjælv her og der, og der skal være Hunger og Oprør. Dette er Veernes Begyndelse.","Thi Folk skal reise sig imod Folk, og Rige imod Rige, og der skal skee Jordskjælv her og der, og der skal være Hunger og Oprør. Dette er Veernes Begyndelse."],[13,9,"Men I, tager vare paa Eder selv; thi de skulle overantvorde Eder for Raadet og for Synagoger; I skulle hudstryges og stilles for Fyrster og Konger for min Skyld, dem til et Vidnesbyrd.","Men I, tager vare paa Eder selv; thi de skulle overantvorde Eder for Raadet og for Synagoger; I skulle hudstryges og stilles for Fyrster og Konger for min Skyld, dem til et Vidnesbyrd."],[13,10,"Og Evangelium bør føst at prædikes for alle Folk.","Og Evangelium bør føst at prædikes for alle Folk."],[13,11,"Men naar de føre Eder hen at overantvorde Eder, da bekymrer Eder ikke forud, hvad I skulle tale, betænker Eder ei heller derpaa; men hvad som Eder bliver givet i den samme Time, det taler; thi I ere Ikke de, som tale, men den Hellig Aand.","Men naar de føre Eder hen at overantvorde Eder, da bekymrer Eder ikke forud, hvad I skulle tale, betænker Eder ei heller derpaa; men hvad som Eder bliver givet i den samme Time, det taler; thi I ere Ikke de, som tale, men den Hellig Aand."],[13,12,"Men en Broder skal overantvorde den anden til Døden, og Faderen Barnet; og Børn skulle sætte sig op mod Forældre og slaae dem ihjel.","Men en Broder skal overantvorde den anden til Døden, og Faderen Barnet; og Børn skulle sætte sig op mod Forældre og slaae dem ihjel."],[13,13,"Og I skulle hades af Alle for mit Navns Skyld, men hvor som bliver bestandig indtil Enden, han skal blive salig.","Og I skulle hades af Alle for mit Navns Skyld, men hvor som bliver bestandig indtil Enden, han skal blive salig."],[13,14,"Men naar I see Ødelæggelsens Vederstyggelighed, om hvilken Propheten Daniel haver talet, at staae, hvor den ikke bør, (hvo det læser, han give Agt derpaa!) da flye til Bjergene de, som ere i Judæa;","Men naar I see Ødelæggelsens Vederstyggelighed, om hvilken Propheten Daniel haver talet, at staae, hvor den ikke bør, (hvo det læser, han give Agt derpaa!) da flye til Bjergene de, som ere i Judæa;"],[13,15,"men hvo som er paa Taget, stige ikke ned i Huset eller gaae ind at hente Noget af sit Huus;","men hvo som er paa Taget, stige ikke ned i Huset eller gaae ind at hente Noget af sit Huus;"],[13,16,"og hvo som er paa Ageren, vende ikke tilbage at hente sit Klædebon.","og hvo som er paa Ageren, vende ikke tilbage at hente sit Klædebon."],[13,17,"Men vee de Frugtsommelige og dem, som give Die, i de Dage!","Men vee de Frugtsommelige og dem, som give Die, i de Dage!"],[13,18,"Men beder, at Eders Flugt ikke skal skee om Vinteren!","Men beder, at Eders Flugt ikke skal skee om Vinteren!"],[13,19,"Thi i de Dage skal være saa stor en Trængsel, som ikke haver været fra Skabningens Begyndelse, som Gud skabte, indtil nu, og som ikke heller skal blive.","Thi i de Dage skal være saa stor en Trængsel, som ikke haver været fra Skabningens Begyndelse, som Gud skabte, indtil nu, og som ikke heller skal blive."],[13,20,"Og dersom Herren ikke forkortede de Dage, blev intet Menneske frelst; men for de Udvalgtes Skyld, som han haver udvalgt, haver han forkortet de Dage.","Og dersom Herren ikke forkortede de Dage, blev intet Menneske frelst; men for de Udvalgtes Skyld, som han haver udvalgt, haver han forkortet de Dage."],[13,21,"Og naar Nogen da siger til Eder: see, her er Christus, eller see der! da skulle I ikke troe det.","Og naar Nogen da siger til Eder: see, her er Christus, eller see der! da skulle I ikke troe det."],[13,22,"Thi falske Christi og falske Propheter skulle opstaae, og gjøre Tegn og underlige Gjerninger for at forføre, om det var muligt, endog de Udvalgte.","Thi falske Christi og falske Propheter skulle opstaae, og gjøre Tegn og underlige Gjerninger for at forføre, om det var muligt, endog de Udvalgte."],[13,23,"Men vogter I Eder; see, jeg haver sagt Eder Alt forud.","Men vogter I Eder; see, jeg haver sagt Eder Alt forud."],[13,24,"Men i de Dage efter den Trængsel skal Solen formørkes, og Maanen ikke give sit Skin,","Men i de Dage efter den Trængsel skal Solen formørkes, og Maanen ikke give sit Skin,"],[13,25,"og Himmelens Stjerner skulle nedfalde, og de Kræfter, som ere i Himlene, skulle røres.","og Himmelens Stjerner skulle nedfalde, og de Kræfter, som ere i Himlene, skulle røres."],[13,26,"Og da skulle de see Menneskens Søn komme i Skyerne med megen Kraft og Herlighed.","Og da skulle de see Menneskens Søn komme i Skyerne med megen Kraft og Herlighed."],[13,27,"Og da skal han sende sine Engle og forsamle sine Udvalgte fra de fire Veir, fra Jordens Ende indtil Himmelens Ende.","Og da skal han sende sine Engle og forsamle sine Udvalgte fra de fire Veir, fra Jordens Ende indtil Himmelens Ende."],[13,28,"Lærer en Lignelse af Figentræet: naar Vædsken er kommen i dets Grene, og Bladene skyde ud, saa vide I, at Sommeren er nær.","Lærer en Lignelse af Figentræet: naar Vædsken er kommen i dets Grene, og Bladene skyde ud, saa vide I, at Sommeren er nær."],[13,29,"Ligesaa og I, naar I see, at disse Ting skee, vider, at han er nær vor Dørene.","Ligesaa og I, naar I see, at disse Ting skee, vider, at han er nær vor Dørene."],[13,30,"Sandelig siger jeg Eder: denne Slægt skal ingenlunde forgaae, førend disse Ting skee allesammen.","Sandelig siger jeg Eder: denne Slægt skal ingenlunde forgaae, førend disse Ting skee allesammen."],[13,31,"Himmelen og Jorden skulle forgaae, men mine Ord skulle ingenlunde forgaae.","Himmelen og Jorden skulle forgaae, men mine Ord skulle ingenlunde forgaae."],[13,32,"Men om den Dag og Time veed Ingen, hverken Englene, som ere i Himmelen, ikke heller Sønnen, men alene Faderen.","Men om den Dag og Time veed Ingen, hverken Englene, som ere i Himmelen, ikke heller Sønnen, men alene Faderen."],[13,33,"Seer til, vaager og beder; thi I vide ikke, naar den Tid er.","Seer til, vaager og beder; thi I vide ikke, naar den Tid er."],[13,34,"Ligesom et Menneske, som drog udenlands, forlod sit Huus, og gav sine Tjenere Magt og hver sin Gjerning, og bød Dørvogteren, at han skulde vaage.","Ligesom et Menneske, som drog udenlands, forlod sit Huus, og gav sine Tjenere Magt og hver sin Gjerning, og bød Dørvogteren, at han skulde vaage."],[13,35,"Derfor vaager; (thi I vide ikke, naar Husets Herre kommer, om Aftenen eller ved Midnat eller ved Hanegal eller om Morgenen),","Derfor vaager; (thi I vide ikke, naar Husets Herre kommer, om Aftenen eller ved Midnat eller ved Hanegal eller om Morgenen),"],[13,36,"at han ikke, nar han kommer hastelig, skal finde Eder sovende.","at han ikke, nar han kommer hastelig, skal finde Eder sovende."],[13,37,"Men hvad jeg siger Eder, det siger jeg Alle: vaager!","Men hvad jeg siger Eder, det siger jeg Alle: vaager!"],[14,1,"Men det var Paaske og de usyrede Brøds Høitid to Dage derefter. Og de Ypperstepræster og de Skriftkloge søgte, hvorledes de med List kunde gribe og ihjelslaae ham.","Men det var Paaske og de usyrede Brøds Høitid to Dage derefter. Og de Ypperstepræster og de Skriftkloge søgte, hvorledes de med List kunde gribe og ihjelslaae ham."],[14,2,"Men de sagde: ikke paa Høitiden, at der ikke skal blive Larm iblandt Folket.","Men de sagde: ikke paa Høitiden, at der ikke skal blive Larm iblandt Folket."],[14,3,"Og der han var i Bethanien, i Simon den Spedalskes Huus, og sad til Bords, kom en Kvinde, som havde en Alabasterkrukke med uforfalsket, meget kostelig Nardussalve; og hun sønderbrød Alabasterkrukken og udgød den paa hans Hoved.","Og der han var i Bethanien, i Simon den Spedalskes Huus, og sad til Bords, kom en Kvinde, som havde en Alabasterkrukke med uforfalsket, meget kostelig Nardussalve; og hun sønderbrød Alabasterkrukken og udgød den paa hans Hoved."],[14,4,"Men der vare Nogle, som bleve fortrydelige ved sig selv og sagde: hvortil blev denne Salve spildt?","Men der vare Nogle, som bleve fortrydelige ved sig selv og sagde: hvortil blev denne Salve spildt?"],[14,5,"Thi den kunde bleven solgt for mere end tre hundrede Penninge og givet de Fattige; og de overfusede hende.","Thi den kunde bleven solgt for mere end tre hundrede Penninge og givet de Fattige; og de overfusede hende."],[14,6,"Men Jesus sagde: lader hende med Fred, hvi gjøre I hende Fortred? Hun gjorde en god Gjerning imod mig.","Men Jesus sagde: lader hende med Fred, hvi gjøre I hende Fortred? Hun gjorde en god Gjerning imod mig."],[14,7,"Thi I have altid Fattige hos Eder, og naar I ville, kunne I gjøre dem tilgode; men mig have I ikke altid.","Thi I have altid Fattige hos Eder, og naar I ville, kunne I gjøre dem tilgode; men mig have I ikke altid."],[14,8,"Hun gjorde, hvad hun kunde; hun haver forud salvet mit Legeme til Begravelsen.","Hun gjorde, hvad hun kunde; hun haver forud salvet mit Legeme til Begravelsen."],[14,9,"Sandelig siger jeg Eder: hvorsomhelst dette Evangelium bliver prædiket i den ganske Verden, skal og det, som hun haver gjort, siges til hendes Ihukommelse.","Sandelig siger jeg Eder: hvorsomhelst dette Evangelium bliver prædiket i den ganske Verden, skal og det, som hun haver gjort, siges til hendes Ihukommelse."],[14,10,"Og Judas Ischariotes, een af de Tolv, gik hen til de Ypperstepræster, for at forraade ham til dem.","Og Judas Ischariotes, een af de Tolv, gik hen til de Ypperstepræster, for at forraade ham til dem."],[14,11,"Men der de hørte det, bleve de glade, og de lovede at give ham Penge; og han søgte, hvorledes han kunde beleiligen forraade ham.","Men der de hørte det, bleve de glade, og de lovede at give ham Penge; og han søgte, hvorledes han kunde beleiligen forraade ham."],[14,12,"Og paa de usyrede Brøds første Dag, der man slagtede Paaskelam, sagde hans Disciple til ham: hvor vil du, at vi skulle gaae hen og berede, at du kan æde Paaskelammet?","Og paa de usyrede Brøds første Dag, der man slagtede Paaskelam, sagde hans Disciple til ham: hvor vil du, at vi skulle gaae hen og berede, at du kan æde Paaskelammet?"],[14,13,"Og han sendte to af sine Disciple og sagde til dem: gaaer hen i Staden, og et Menneske skal møde Eder, som bærer en Vandkrukke; følger ham;","Og han sendte to af sine Disciple og sagde til dem: gaaer hen i Staden, og et Menneske skal møde Eder, som bærer en Vandkrukke; følger ham;"],[14,14,"og hvor han gaaer ind, der siger til Huusbonden: Mesteren siger: hvor er det Herberge, der jeg kan æde Paaskelammet med mine Disciple?","og hvor han gaaer ind, der siger til Huusbonden: Mesteren siger: hvor er det Herberge, der jeg kan æde Paaskelammet med mine Disciple?"],[14,15,"Og han skal vise Eder en stor Sal, tillavet og rede, der bereder det for os.","Og han skal vise Eder en stor Sal, tillavet og rede, der bereder det for os."],[14,16,"Og hans Disciple gik bort og kom i Staden og fandt det, ligesom han havde sagt dem; og de beredte Paaskelammet.","Og hans Disciple gik bort og kom i Staden og fandt det, ligesom han havde sagt dem; og de beredte Paaskelammet."],[14,17,"Og der det var blevet Aften, kom han med de Tolv.","Og der det var blevet Aften, kom han med de Tolv."],[14,18,"Og da de sadde til Bords og aade, sagde Jesus: sandelig siger jeg Eder, at een af Eder, som æder med mig, skal forraade mig.","Og da de sadde til Bords og aade, sagde Jesus: sandelig siger jeg Eder, at een af Eder, som æder med mig, skal forraade mig."],[14,19,"Men de begyndte at bedrøves og at sige til ham, een efter een: er jeg den? og en anden: er jeg den?","Men de begyndte at bedrøves og at sige til ham, een efter een: er jeg den? og en anden: er jeg den?"],[14,20,"Men han svarede og sagde til dem: een af de Tolv, den, som dypper med mig i Fadet.","Men han svarede og sagde til dem: een af de Tolv, den, som dypper med mig i Fadet."],[14,21,"Menneskens Søn gaaer vel bort, som det er skrevet om ham; dog vee det Menneske, ved hvilket Menneskens Søn bliver forraadt! Det var dette Menneske godt, om han aldrig var født.","Menneskens Søn gaaer vel bort, som det er skrevet om ham; dog vee det Menneske, ved hvilket Menneskens Søn bliver forraadt! Det var dette Menneske godt, om han aldrig var født."],[14,22,"Og der de aade, tog Jesus Brødet, velsignede, og brød det, og gav dem, og sagde: tager, æder; dette er mit Legeme.","Og der de aade, tog Jesus Brødet, velsignede, og brød det, og gav dem, og sagde: tager, æder; dette er mit Legeme."],[14,23,"Og han tog Kalken, takkede, og gav dem den; og de drak alle deraf.","Og han tog Kalken, takkede, og gav dem den; og de drak alle deraf."],[14,24,"Og han sagde til dem: dette er mit Blod, det nye Testamentes, hvilket udgydes for Mange.","Og han sagde til dem: dette er mit Blod, det nye Testamentes, hvilket udgydes for Mange."],[14,25,"Sandelig siger jeg Eder, at jeg skal herefter ikke mere drikke af Viintræets Frugt, indtil paa hiin Dag, naar jeg skal drikke den ny i Guds Rige.","Sandelig siger jeg Eder, at jeg skal herefter ikke mere drikke af Viintræets Frugt, indtil paa hiin Dag, naar jeg skal drikke den ny i Guds Rige."],[14,26,"Og der de havde sjunget Lovsangen, gik de ud til Oliebjerget.","Og der de havde sjunget Lovsangen, gik de ud til Oliebjerget."],[14,27,"Og Jesus sagde til dem: i denne Nat skulle I alle forarges paa mig; thi der er skrevet: jeg skal slaae Hyrden, og Faarene skulle adspredes.","Og Jesus sagde til dem: i denne Nat skulle I alle forarges paa mig; thi der er skrevet: jeg skal slaae Hyrden, og Faarene skulle adspredes."],[14,28,"Men efterat jeg er opstanden, vil jeg gaae forud for Eder til Galilæa.","Men efterat jeg er opstanden, vil jeg gaae forud for Eder til Galilæa."],[14,29,"Men Peter sagde til ham; dersom de endog alle forarges, vil jeg dog ikke forarges.","Men Peter sagde til ham; dersom de endog alle forarges, vil jeg dog ikke forarges."],[14,30,"Og Jesus sagde til ham: sandelig siger jeg dig, at i Dag, i denne Nat, førend Hanen galer to Gange, skal du fornegte mig tre Gange.","Og Jesus sagde til ham: sandelig siger jeg dig, at i Dag, i denne Nat, førend Hanen galer to Gange, skal du fornegte mig tre Gange."],[14,31,"Men han sagde endydermere: dersom jeg end skulde døe med dig, vil jeg dog ikke fornegte dig. Men ligesaa sagde de og alle.","Men han sagde endydermere: dersom jeg end skulde døe med dig, vil jeg dog ikke fornegte dig. Men ligesaa sagde de og alle."],[14,32,"Og de kom til en Gaard, hvis Navn var Gethsemane; og han sagde til sine Disciple: sætter Eder her, imedens jeg beder.","Og de kom til en Gaard, hvis Navn var Gethsemane; og han sagde til sine Disciple: sætter Eder her, imedens jeg beder."],[14,33,"Og han tog Peter og Jakob og Johannes til sig, og begyndte at skjælve og svarligen at ængstes.","Og han tog Peter og Jakob og Johannes til sig, og begyndte at skjælve og svarligen at ængstes."],[14,34,"Og han sagde til dem: min Sjæl er ganske bedrøvet indtil Døden; bliver her og vaager!","Og han sagde til dem: min Sjæl er ganske bedrøvet indtil Døden; bliver her og vaager!"],[14,35,"Og han gik lidet frem, faldt ned paa Jorden og bad, at denne Time maatte gaae ham forbi, om det var muligt.","Og han gik lidet frem, faldt ned paa Jorden og bad, at denne Time maatte gaae ham forbi, om det var muligt."],[14,36,"Og han sagde: Abba Fader! Alting er dig muligt; tag denne Kalk fra mig; dog ikke hvad jeg vil, men hvad du vil.","Og han sagde: Abba Fader! Alting er dig muligt; tag denne Kalk fra mig; dog ikke hvad jeg vil, men hvad du vil."],[14,37,"Og han kom og fandt dem sovende, og sagde til Peter: Simon, sover du? kunde du ikke vaage een Time?","Og han kom og fandt dem sovende, og sagde til Peter: Simon, sover du? kunde du ikke vaage een Time?"],[14,38,"Vaager og beder, at I ikke skulle falde i Fristelse; Aanden er vel redebon, men Kjødet er skrøbeligt.","Vaager og beder, at I ikke skulle falde i Fristelse; Aanden er vel redebon, men Kjødet er skrøbeligt."],[14,39,"Og han gik atter hen, og bad og sagde de samme Ord.","Og han gik atter hen, og bad og sagde de samme Ord."],[14,40,"Og han kom igjen, og fandt dem atter sovende; thi deres Øine vare betyngede, og de vidste ikke, hvad de skulde svare ham.","Og han kom igjen, og fandt dem atter sovende; thi deres Øine vare betyngede, og de vidste ikke, hvad de skulde svare ham."],[14,41,"Og han kom tredie Gang og sagde til dem: sove I fremdeles og hvile Eder? Det er forbi, Timen er kommen; see, Menneskens Søn forraades i Synderes Hænder.","Og han kom tredie Gang og sagde til dem: sove I fremdeles og hvile Eder? Det er forbi, Timen er kommen; see, Menneskens Søn forraades i Synderes Hænder."],[14,42,"Staaer op, lader os gaae; see, han er nær, som forraader mig.","Staaer op, lader os gaae; see, han er nær, som forraader mig."],[14,43,"Og strax, som han endnu talede, kom Judas, een af de Tolv, og en stor Skare med ham, med Sværd og Stænger, fra de Ypperstepræster og Skriftkloge og de Ældste.","Og strax, som han endnu talede, kom Judas, een af de Tolv, og en stor Skare med ham, med Sværd og Stænger, fra de Ypperstepræster og Skriftkloge og de Ældste."],[14,44,"Men den, som forraadte ham, havde givet dem et aftalt Tegn og sagt: hvilken jeg kysser, den er det; griber ham og fører ham sikkert bort.","Men den, som forraadte ham, havde givet dem et aftalt Tegn og sagt: hvilken jeg kysser, den er det; griber ham og fører ham sikkert bort."],[14,45,"Og der han kom traadte han strax til ham og sagde: Rabbi! Rabbi! og han kyssede ham.","Og der han kom traadte han strax til ham og sagde: Rabbi! Rabbi! og han kyssede ham."],[14,46,"Men de lagde deres Hænder paa ham og grebe ham.","Men de lagde deres Hænder paa ham og grebe ham."],[14,47,"Men een af dem, som stode hos, drog Sværdet ud, slog den Ypperstepræsts Tjener og afhuggede hans Øre.","Men een af dem, som stode hos, drog Sværdet ud, slog den Ypperstepræsts Tjener og afhuggede hans Øre."],[14,48,"Og Jesus svarede og sagde til dem: I ere udgangne ligesom til en Røver, med Sværd og med Stænger, at tage fat paa mig.","Og Jesus svarede og sagde til dem: I ere udgangne ligesom til en Røver, med Sværd og med Stænger, at tage fat paa mig."],[14,49,"Jeg haver været daglig hos Eder i Templet og lært, og I grebe mig ikke; men dette skeer, paa det Skrifterne skulle fuldkommes.","Jeg haver været daglig hos Eder i Templet og lært, og I grebe mig ikke; men dette skeer, paa det Skrifterne skulle fuldkommes."],[14,50,"Og de forlode ham alle og flyede.","Og de forlode ham alle og flyede."],[14,51,"Og et ungt Menneske fulgte ham, som havde et Linklæde over det blotte Legeme; og Karlene toge fat paa ham.","Og et ungt Menneske fulgte ham, som havde et Linklæde over det blotte Legeme; og Karlene toge fat paa ham."],[14,52,"Men han slap Linklædet og flyede nøgen fra dem.","Men han slap Linklædet og flyede nøgen fra dem."],[14,53,"Og de førte Jesus hen til den Ypperstepræst; og alle de Ypperstepræster og Ældste og Skriftkloge kom tilsammen hos ham.","Og de førte Jesus hen til den Ypperstepræst; og alle de Ypperstepræster og Ældste og Skriftkloge kom tilsammen hos ham."],[14,54,"Og Peter fulgte ham langt bag efter, til ind i den Ypperstepræsts Pallads, og han sad hos Tjenerne og varmede sig ved Ilden.","Og Peter fulgte ham langt bag efter, til ind i den Ypperstepræsts Pallads, og han sad hos Tjenerne og varmede sig ved Ilden."],[14,55,"Men de Ypperstepræster og det ganske Raad søgte Vidnesbyrd mod Jesus, paa det de kunde aflive ham; men de fandt intet.","Men de Ypperstepræster og det ganske Raad søgte Vidnesbyrd mod Jesus, paa det de kunde aflive ham; men de fandt intet."],[14,56,"Thi Mange bare falske Vidnesbyrd mod ham, men Vidnesbyrdene kom ikke overeens.","Thi Mange bare falske Vidnesbyrd mod ham, men Vidnesbyrdene kom ikke overeens."],[14,57,"Og nogle stode op, og bare falsk Vidnesbyrd mod ham og sagde:","Og nogle stode op, og bare falsk Vidnesbyrd mod ham og sagde:"],[14,58,"vi have hørt, at han sagde: jeg vil nedbryde dette Tempel, som er gjort med Hænder, og i tre Dage bygge et andet, som ikke er gjort med Hænder.","vi have hørt, at han sagde: jeg vil nedbryde dette Tempel, som er gjort med Hænder, og i tre Dage bygge et andet, som ikke er gjort med Hænder."],[14,59,"Og end ikke saaledes kom deres Vidnesbyrd overeens.","Og end ikke saaledes kom deres Vidnesbyrd overeens."],[14,60,"Og den Ypperstepræst stod op midt i blandt dem, og adspurgte Jesus; svarer du slet intet? hvad vidne disse imod dig?","Og den Ypperstepræst stod op midt i blandt dem, og adspurgte Jesus; svarer du slet intet? hvad vidne disse imod dig?"],[14,61,"Men han taug og svarede Intet. Da spurgte den Ypperstepræst ham atter og sagde til ham: er du den Christus, den Høilovedes Søn?","Men han taug og svarede Intet. Da spurgte den Ypperstepræst ham atter og sagde til ham: er du den Christus, den Høilovedes Søn?"],[14,62,"Men Jesus sagde: jeg er det; og I skulle see Menneskens Søn sidde hos Kraftens høire Haand og komme med Himmelens Skyer.","Men Jesus sagde: jeg er det; og I skulle see Menneskens Søn sidde hos Kraftens høire Haand og komme med Himmelens Skyer."],[14,63,"Da sønderrev den Ypperstepræst sine Klæder og sagde: hvad have vi længere Vidner behov?","Da sønderrev den Ypperstepræst sine Klæder og sagde: hvad have vi længere Vidner behov?"],[14,64,"I have hørt Gudsbespottelsen; hvad tykkes Eder? Men de fordømte ham at være skyldig til Døden.","I have hørt Gudsbespottelsen; hvad tykkes Eder? Men de fordømte ham at være skyldig til Døden."],[14,65,"Og Nogle begyndte at bespytte ham og skjule hans Ansigt, og slaae ham med Næver, og sige til ham: spaa! og Tjenerne sloge ham paa Munden.","Og Nogle begyndte at bespytte ham og skjule hans Ansigt, og slaae ham med Næver, og sige til ham: spaa! og Tjenerne sloge ham paa Munden."],[14,66,"Og da Peter var nede i Gaarden, kom een af den Ypperstepræstes Piger,","Og da Peter var nede i Gaarden, kom een af den Ypperstepræstes Piger,"],[14,67,"Og der hun saae Peter varme sig, saae hun paa ham og sagde: du haver ogsaa været med Jesus af Nazareth.","Og der hun saae Peter varme sig, saae hun paa ham og sagde: du haver ogsaa været med Jesus af Nazareth."],[14,68,"Men han negtede og sagde: jeg kjender ham ikke, veed og ikke, hvad du siger; og han gik ud i Forgaarden, og Hanen goel.","Men han negtede og sagde: jeg kjender ham ikke, veed og ikke, hvad du siger; og han gik ud i Forgaarden, og Hanen goel."],[14,69,"Og Pigen saae ham igjen og begyndte at sige til dem, som stode hos: denne er En af dem.","Og Pigen saae ham igjen og begyndte at sige til dem, som stode hos: denne er En af dem."],[14,70,"Men han negtede atter. Og lidet derefter sagde atter de, som stode hos, til Peter: sandelig du er af dem; thi du er og en Galilæer, og dit Maal er ligt derefter.","Men han negtede atter. Og lidet derefter sagde atter de, som stode hos, til Peter: sandelig du er af dem; thi du er og en Galilæer, og dit Maal er ligt derefter."],[14,71,"Men han begyndte at forbande sig og sværge: jeg kjender det Menneske ikke, om hvem I tale.","Men han begyndte at forbande sig og sværge: jeg kjender det Menneske ikke, om hvem I tale."],[14,72,"Og Hanen goel anden Gang. Og Peter kom det Ord i hu, som Jesus sagde til ham: førend Hanen galer to Gange, skal du fornegte mig tre Gange; og han brast i Graad.","Og Hanen goel anden Gang. Og Peter kom det Ord i hu, som Jesus sagde til ham: førend Hanen galer to Gange, skal du fornegte mig tre Gange; og han brast i Graad."],[15,1,"Og strax om Morgenen, der de Ypperstepræster med de Ældste og Skriftkloge og det ganske Raad havde holdt Raadslag, bandt de Jesus og førte ham bort og overantvordede Pilatus ham.","Og strax om Morgenen, der de Ypperstepræster med de Ældste og Skriftkloge og det ganske Raad havde holdt Raadslag, bandt de Jesus og førte ham bort og overantvordede Pilatus ham."],[15,2,"Og Pilatus spurgte ham: er du den Jødernes Konge? Med han svarede og sagde til ham: du siger det.","Og Pilatus spurgte ham: er du den Jødernes Konge? Med han svarede og sagde til ham: du siger det."],[15,3,"Og de Ypperstepræster anklagede ham meget.","Og de Ypperstepræster anklagede ham meget."],[15,4,"Pilatus spurgte ham atter og sagde: svarer du slet intet? See, hvor meget de vidne imod dig.","Pilatus spurgte ham atter og sagde: svarer du slet intet? See, hvor meget de vidne imod dig."],[15,5,"Men Jesus svarede endda Intet, saa at Pilatus forundrede sig.","Men Jesus svarede endda Intet, saa at Pilatus forundrede sig."],[15,6,"Men han pleiede at give dem een Fange løs om Høitiden, hvilken de begjerede.","Men han pleiede at give dem een Fange løs om Høitiden, hvilken de begjerede."],[15,7,"Men der var En, som hedte Barrabas, som var fangen med Oprørere, som udi et Opløb havde begaaet Mord.","Men der var En, som hedte Barrabas, som var fangen med Oprørere, som udi et Opløb havde begaaet Mord."],[15,8,"Og Folket Raabte og begyndte at begjere, at han vilde gjøre med dem, som han altid pleiede.","Og Folket Raabte og begyndte at begjere, at han vilde gjøre med dem, som han altid pleiede."],[15,9,"Men Pilatus svarede dem og sagde: ville I, at jeg skal give Eder den Jødernes Konge løs?","Men Pilatus svarede dem og sagde: ville I, at jeg skal give Eder den Jødernes Konge løs?"],[15,10,"Thi han vidste, at de Ypperstepræster havde overantvordet ham af Avind.","Thi han vidste, at de Ypperstepræster havde overantvordet ham af Avind."],[15,11,"Men de Ypperstepræster tilskyndte Folket at bede, at han hellere skulde give dem Barrabas løs.","Men de Ypperstepræster tilskyndte Folket at bede, at han hellere skulde give dem Barrabas løs."],[15,12,"Men Pilatus svarede og sagde atter til dem: hvad ville I da, jeg skal gjøre med ham, som I kaldte Jødernes Konge?","Men Pilatus svarede og sagde atter til dem: hvad ville I da, jeg skal gjøre med ham, som I kaldte Jødernes Konge?"],[15,13,"Men de raabte atter: korsfæst ham!","Men de raabte atter: korsfæst ham!"],[15,14,"Da sagde Pilatus til dem: hvad Ondt haver han da gjort? Men de raabte meget mere: korsfæst ham!","Da sagde Pilatus til dem: hvad Ondt haver han da gjort? Men de raabte meget mere: korsfæst ham!"],[15,15,"Men Pilatus vilde gjøre Folket fyldest, og gav dem Barrabas løs; og Jesus lod han hudstryge og gav ham hen til at korsfæstes.","Men Pilatus vilde gjøre Folket fyldest, og gav dem Barrabas løs; og Jesus lod han hudstryge og gav ham hen til at korsfæstes."],[15,16,"Men Stridsmændene førte ham hen til Palladset, nemlig Domhuset, og sammenkaldte den ganske Rode.","Men Stridsmændene førte ham hen til Palladset, nemlig Domhuset, og sammenkaldte den ganske Rode."],[15,17,"Og de iførte ham et Purpurklæde, og flettede en Tornekrone og satte den paa ham,","Og de iførte ham et Purpurklæde, og flettede en Tornekrone og satte den paa ham,"],[15,18,"og begyndte at hilse ham, sigende: hil være dig, du Jødernes Konge!","og begyndte at hilse ham, sigende: hil være dig, du Jødernes Konge!"],[15,19,"Og de sloge hans Hoved med et Rør og bespyttede ham, og faldt paa Knæ og tilbade ham.","Og de sloge hans Hoved med et Rør og bespyttede ham, og faldt paa Knæ og tilbade ham."],[15,20,"Og der de havde bespottet ham, toge de Purpurklædet af ham, og iførte ham hans egne Klæder, og de førte ham ud for at korsfæste ham.","Og der de havde bespottet ham, toge de Purpurklædet af ham, og iførte ham hans egne Klæder, og de førte ham ud for at korsfæste ham."],[15,21,"Og de tvang En, som gik forbi, Simon fra Cyrene, som kom fra Marken, Alexanders og Rufus’ Fader, til at bære hans Kors.","Og de tvang En, som gik forbi, Simon fra Cyrene, som kom fra Marken, Alexanders og Rufus’ Fader, til at bære hans Kors."],[15,22,"Og de førte ham til det Sted Golgatha, det er udlagt: Hovedpandested.","Og de førte ham til det Sted Golgatha, det er udlagt: Hovedpandested."],[15,23,"Og de gave ham Viin at drikke med Myrrha udi: men han tog det ikke.","Og de gave ham Viin at drikke med Myrrha udi: men han tog det ikke."],[15,24,"Og der de havde korsfæstet ham, skiftede de hans Klæder, og Kastede Lod om dem, hvad hver skulde tage.","Og der de havde korsfæstet ham, skiftede de hans Klæder, og Kastede Lod om dem, hvad hver skulde tage."],[15,25,"Men det var den tredie Time, da de korsfæstede ham.","Men det var den tredie Time, da de korsfæstede ham."],[15,26,"Og der var skreven en Overskrift med Beskyldningen mod ham: den Jødernes Konge.","Og der var skreven en Overskrift med Beskyldningen mod ham: den Jødernes Konge."],[15,27,"Og de korsfæstede to Røvere med ham, een ved hans høire, og een ved hans venstre Side.","Og de korsfæstede to Røvere med ham, een ved hans høire, og een ved hans venstre Side."],[15,28,"Og Skriften blev fuldkommet, som siger: han er regnet med Overtrædere.","Og Skriften blev fuldkommet, som siger: han er regnet med Overtrædere."],[15,29,"Og de, der gik forbi, bespottede ham, og rystede med deres Hoveder og sagde: tvi dig! du som nedbryder Templet og bygger det i tre Dage;","Og de, der gik forbi, bespottede ham, og rystede med deres Hoveder og sagde: tvi dig! du som nedbryder Templet og bygger det i tre Dage;"],[15,30,"frels dig selv, og stig ned af Korset!","frels dig selv, og stig ned af Korset!"],[15,31,"Ligesaa bespottede og de Ypperstepræster ham indbyrdes, tilligemed de Skriftkloge, og sagde: han haver frelst andre, sig selv kan han ikke frelse.","Ligesaa bespottede og de Ypperstepræster ham indbyrdes, tilligemed de Skriftkloge, og sagde: han haver frelst andre, sig selv kan han ikke frelse."],[15,32,"Den Christus, den Israels Konge, stige nu ned af Korset, at vi kunne see og troe! og de, som vare korsfæstede med ham, forhaanede ham.","Den Christus, den Israels Konge, stige nu ned af Korset, at vi kunne see og troe! og de, som vare korsfæstede med ham, forhaanede ham."],[15,33,"Men da den sjette Time var kommen, blev et Mørke over det ganske Land indtil den niende Time.","Men da den sjette Time var kommen, blev et Mørke over det ganske Land indtil den niende Time."],[15,34,"Og ved den niende Time raabte Jesus med stor Røst og sagde: Eloi! Eloi! Lama Sabachtani? det er udlagt: min Gud! min Gud! hvorfor haver du forladt mig?","Og ved den niende Time raabte Jesus med stor Røst og sagde: Eloi! Eloi! Lama Sabachtani? det er udlagt: min Gud! min Gud! hvorfor haver du forladt mig?"],[15,35,"Og Nogle af dem, som stode hos, der de hørte, sagde de: see, han kalder ad Elias.","Og Nogle af dem, som stode hos, der de hørte, sagde de: see, han kalder ad Elias."],[15,36,"Men En løb, og fyldte en Svamp med Eddike og stak den paa et Rør, og gav ham at drikke og sagde: holdt! lader os see, om Elias kommer at tage ham ned.","Men En løb, og fyldte en Svamp med Eddike og stak den paa et Rør, og gav ham at drikke og sagde: holdt! lader os see, om Elias kommer at tage ham ned."],[15,37,"Men Jesus raabte med stor Røst, og udgav Aanden.","Men Jesus raabte med stor Røst, og udgav Aanden."],[15,38,"Og Forhænget i Templet splittedes i to fra det Øverste indtil det Nederste.","Og Forhænget i Templet splittedes i to fra det Øverste indtil det Nederste."],[15,39,"Men Høvedsmanden, som stod hos tvært over for ham, og saae, at han udgav Aanden med saadant Raab, sagde: sandelig var dette Menneske Guds Søn.","Men Høvedsmanden, som stod hos tvært over for ham, og saae, at han udgav Aanden med saadant Raab, sagde: sandelig var dette Menneske Guds Søn."],[15,40,"Men der vare ogsaa Kvinder, som langtfra saae til; iblandt hvilke vare Maria Magdalene, og Maria, Jakob den Mindres og Joses’ Moder, og Salome;","Men der vare ogsaa Kvinder, som langtfra saae til; iblandt hvilke vare Maria Magdalene, og Maria, Jakob den Mindres og Joses’ Moder, og Salome;"],[15,41,"hvilke og havde fulgt ham og tjent ham, der han var i Galilæa, og mange andre Kvinder, som vare gangne op til Jerusalem med ham.","hvilke og havde fulgt ham og tjent ham, der han var i Galilæa, og mange andre Kvinder, som vare gangne op til Jerusalem med ham."],[15,42,"Og der det nu var blevet Aften, (efterdi det var Beredelsens Dag, hvilken er en For-Sabbat),","Og der det nu var blevet Aften, (efterdi det var Beredelsens Dag, hvilken er en For-Sabbat),"],[15,43,"kom Joseph af Arimathæa, en hæderlig Raadsherre, hvilken og selv ventede Guds Rige; han dristede sig til at gaae ind til Pilatus og bede om Jesu Legeme.","kom Joseph af Arimathæa, en hæderlig Raadsherre, hvilken og selv ventede Guds Rige; han dristede sig til at gaae ind til Pilatus og bede om Jesu Legeme."],[15,44,"Men Pilatus forundrede sig over, at han allerede skulde være død,","Men Pilatus forundrede sig over, at han allerede skulde være død,"],[15,45,"og kaldte Høvedsmanden og spurgte ham, om han havde længe været død; og der han fik det at vide af Høvedsmanden, skjenkte han Joseph Legemet.","og kaldte Høvedsmanden og spurgte ham, om han havde længe været død; og der han fik det at vide af Høvedsmanden, skjenkte han Joseph Legemet."],[15,46,"Og denne kjøbte et fiint Linklæde, og tog ham ned, svøbte ham i Linklædet, og lagde ham i en Grav, som var udhuggen i en Klippe, og væltede en Steen for Indgangen til Graven.","Og denne kjøbte et fiint Linklæde, og tog ham ned, svøbte ham i Linklædet, og lagde ham i en Grav, som var udhuggen i en Klippe, og væltede en Steen for Indgangen til Graven."],[15,47,"Men Maria Magdalene og Maria, Joses’ Moder, saae, hvor han blev lagt.","Men Maria Magdalene og Maria, Joses’ Moder, saae, hvor han blev lagt."],[16,1,"Og der Sabbaten var forgangen, kjøbte Maria Magdalene og Maria, Jakobs Moder, og Salome vellugtende Salver, for at komme og salve ham.","Og der Sabbaten var forgangen, kjøbte Maria Magdalene og Maria, Jakobs Moder, og Salome vellugtende Salver, for at komme og salve ham."],[16,2,"Og de kom til Graven paa den første Dag i Ugen meget aarle, der Solen gik op.","Og de kom til Graven paa den første Dag i Ugen meget aarle, der Solen gik op."],[16,3,"Og de sagde til hverandre: hvo skal vælte os Stenen fra Indgangen til Graven?","Og de sagde til hverandre: hvo skal vælte os Stenen fra Indgangen til Graven?"],[16,4,"Og der de saae hen, bleve de vaer, at Stenen var fravæltet; (thi den var var meget stor).","Og der de saae hen, bleve de vaer, at Stenen var fravæltet; (thi den var var meget stor)."],[16,5,"Og de gik ind i Graven, og saae en ung Person sidde ved den høire Side i et langt hvidt Klædebon, og de forfærdedes.","Og de gik ind i Graven, og saae en ung Person sidde ved den høire Side i et langt hvidt Klædebon, og de forfærdedes."],[16,6,"Men han sagde til dem: forfærdes ikke! I lede efter Jesus af Nazareth, den Korsfæstede; han er opstanden, han er ikke her, see, der er Stedet, hvor de lagde ham.","Men han sagde til dem: forfærdes ikke! I lede efter Jesus af Nazareth, den Korsfæstede; han er opstanden, han er ikke her, see, der er Stedet, hvor de lagde ham."],[16,7,"Men gaaer bort, siger hans Disciple og Peter, at han gaaer forud for Eder til Galilæa; der skulle I see ham, som han haver sagt Eder.","Men gaaer bort, siger hans Disciple og Peter, at han gaaer forud for Eder til Galilæa; der skulle I see ham, som han haver sagt Eder."],[16,8,"Og de gik hasteligen ud, og flyede fra Graven; men Bævelse og Forfærdelse betog dem, og de sagde Ingen Noget; thi de frygtede.","Og de gik hasteligen ud, og flyede fra Graven; men Bævelse og Forfærdelse betog dem, og de sagde Ingen Noget; thi de frygtede."],[16,9,"Men der han var opstanden aarle den første Dag i Ugen, aabenbaredes han først for Maria Magdalena, af hvilken han havde uddrevet syv Djævle.","Men der han var opstanden aarle den første Dag i Ugen, aabenbaredes han først for Maria Magdalena, af hvilken han havde uddrevet syv Djævle."],[16,10,"Hun gik bort, og kundgjorde det for dem, som havde været med ham, som sørgede og græd.","Hun gik bort, og kundgjorde det for dem, som havde været med ham, som sørgede og græd."],[16,11,"Men disse samme, der de hørte, at han levede, og var seet af hende, troede det ikke.","Men disse samme, der de hørte, at han levede, og var seet af hende, troede det ikke."],[16,12,"Men derefter aabenbaredes han for to af dem paa Veien i en anden Skikkelse, der de gik ud paa Landet.","Men derefter aabenbaredes han for to af dem paa Veien i en anden Skikkelse, der de gik ud paa Landet."],[16,13,"Og disse gik hen og forkyndte de Andre det; ikke heller dem troede de.","Og disse gik hen og forkyndte de Andre det; ikke heller dem troede de."],[16,14,"Paa det Sidste Aabenbaredes han for de Elleve, der de sadde tilbords, og bebreidede dem deres Vantro og Hjertes Haardhed, at de ikke havde troet dem, som havde seet ham opstanden.","Paa det Sidste Aabenbaredes han for de Elleve, der de sadde tilbords, og bebreidede dem deres Vantro og Hjertes Haardhed, at de ikke havde troet dem, som havde seet ham opstanden."],[16,15,"Og han sagde til dem: gaaer bort i al Verden, og prædiker Evangelium for al Skabningen!","Og han sagde til dem: gaaer bort i al Verden, og prædiker Evangelium for al Skabningen!"],[16,16,"Hvo som troer og bliver døbt, skal blive salig; men hvo som ikke troer, skal blive fordømt.","Hvo som troer og bliver døbt, skal blive salig; men hvo som ikke troer, skal blive fordømt."],[16,17,"Men disse Tegn skulle følge dem, som troe: i mit Navn skulle de uddrive Djævle; de skulle tale med nye Tunger;","Men disse Tegn skulle følge dem, som troe: i mit Navn skulle de uddrive Djævle; de skulle tale med nye Tunger;"],[16,18,"de skulle tage paa Slanger, og dersom de drikke nogen Forgift, skal det ikke skade dem; paa de Syge skulle de lægge Hænder, og de skulle helbredes.","de skulle tage paa Slanger, og dersom de drikke nogen Forgift, skal det ikke skade dem; paa de Syge skulle de lægge Hænder, og de skulle helbredes."],[16,19,"Da blev Herren, efterat han havde talet med dem, optagen til Himmelen og satte sig hos Guds høire Haand.","Da blev Herren, efterat han havde talet med dem, optagen til Himmelen og satte sig hos Guds høire Haand."],[16,20,"Men de gik ud og prædikede allevegne, og Herren arbeidede med, og stadfæstede Ordet ved medfølgende Tegn. Amen.","Men de gik ud og prædikede allevegne, og Herren arbeidede med, og stadfæstede Ordet ved medfølgende Tegn. Amen."]],"epo-londona":[[1,1,"La komenco de la evangelio de Jesuo Kristo, Filo de Dio.","La komenco de la evangelio de Jesuo Kristo, Filo de Dio."],[1,2,"Kiel estas skribite en la profeto Jesaja: Jen Mi sendas Mian anĝelon antaŭ via vizaĝo, Kaj li preparos vian vojon;","Kiel estas skribite en la profeto Jesaja: Jen Mi sendas Mian anĝelon antaŭ via vizaĝo, Kaj li preparos vian vojon;"],[1,3,"Voĉo de krianto en la dezerto: Pretigu la vojon de la Eternulo, Rektigu Liajn irejojn;","Voĉo de krianto en la dezerto: Pretigu la vojon de la Eternulo, Rektigu Liajn irejojn;"],[1,4,"venis Johano, kiu baptis en la dezerto kaj predikis la bapton de pento por la pardonado de pekoj.","venis Johano, kiu baptis en la dezerto kaj predikis la bapton de pento por la pardonado de pekoj."],[1,5,"Kaj eliris al li la tuta Juduja distrikto, kaj ĉiuj Jerusalemanoj; kaj ili estis baptitaj de li en la rivero Jordan, konfesante siajn pekojn.","Kaj eliris al li la tuta Juduja distrikto, kaj ĉiuj Jerusalemanoj; kaj ili estis baptitaj de li en la rivero Jordan, konfesante siajn pekojn."],[1,6,"Kaj Johano estis vestita per kamelharaĵo kaj leda zono ĉirkaŭ siaj lumboj, kaj li manĝadis akridojn kaj sovaĝan mielon.","Kaj Johano estis vestita per kamelharaĵo kaj leda zono ĉirkaŭ siaj lumboj, kaj li manĝadis akridojn kaj sovaĝan mielon."],[1,7,"Kaj li predikis, dirante: Venas post mi tiu, kiu estas pli potenca ol mi; la rimenon de liaj ŝuoj mi ne estas inda, kliniĝinte, malligi.","Kaj li predikis, dirante: Venas post mi tiu, kiu estas pli potenca ol mi; la rimenon de liaj ŝuoj mi ne estas inda, kliniĝinte, malligi."],[1,8,"Mi vin baptis per akvo; sed li vin baptos per la Sankta Spirito.","Mi vin baptis per akvo; sed li vin baptos per la Sankta Spirito."],[1,9,"Kaj en tiuj tagoj Jesuo venis el Nazaret de Galileo, kaj estis baptita de Johano en Jordan.","Kaj en tiuj tagoj Jesuo venis el Nazaret de Galileo, kaj estis baptita de Johano en Jordan."],[1,10,"Kaj tuj kiam li eliris el la akvo, li vidis la ĉielon fenditan, kaj la Spiriton kiel kolombo malsuprenirantan sur lin;","Kaj tuj kiam li eliris el la akvo, li vidis la ĉielon fenditan, kaj la Spiriton kiel kolombo malsuprenirantan sur lin;"],[1,11,"kaj venis voĉo el la ĉielo: Vi estas Mia Filo, la amata, en kiu Mi havas plezuron.","kaj venis voĉo el la ĉielo: Vi estas Mia Filo, la amata, en kiu Mi havas plezuron."],[1,12,"Kaj tuj la Spirito pelis lin for en la dezerton.","Kaj tuj la Spirito pelis lin for en la dezerton."],[1,13,"Kaj li estis en la dezerto kvardek tagojn, tentata de Satano; kaj li estis kun la sovaĝaj bestoj, kaj la anĝeloj servadis al li.","Kaj li estis en la dezerto kvardek tagojn, tentata de Satano; kaj li estis kun la sovaĝaj bestoj, kaj la anĝeloj servadis al li."],[1,14,"Kaj post kiam Johano estis arestita, Jesuo iris en Galileon, predikante la evangelion de Dio,","Kaj post kiam Johano estis arestita, Jesuo iris en Galileon, predikante la evangelion de Dio,"],[1,15,"kaj dirante: La tempo jam plenumiĝis, kaj la regno de Dio alproksimiĝis; pentu, kaj kredu al la evangelio.","kaj dirante: La tempo jam plenumiĝis, kaj la regno de Dio alproksimiĝis; pentu, kaj kredu al la evangelio."],[1,16,"Kaj irante apud la Galilea Maro, li vidis Simonon, kaj Andreon, fraton de Simon, ĵetantajn reton en la maron; ĉar ili estis fiŝkaptistoj.","Kaj irante apud la Galilea Maro, li vidis Simonon, kaj Andreon, fraton de Simon, ĵetantajn reton en la maron; ĉar ili estis fiŝkaptistoj."],[1,17,"Kaj Jesuo diris al ili: Venu post mi, kaj mi igos vin fariĝi kaptistoj de homoj.","Kaj Jesuo diris al ili: Venu post mi, kaj mi igos vin fariĝi kaptistoj de homoj."],[1,18,"Kaj ili tuj forlasis la retojn, kaj sekvis lin.","Kaj ili tuj forlasis la retojn, kaj sekvis lin."],[1,19,"Kaj irinte iom antaŭen, li vidis Jakobon, filon de Zebedeo, kaj Johanon, lian fraton, kiuj ankaŭ estis en la ŝipeto, riparante la retojn.","Kaj irinte iom antaŭen, li vidis Jakobon, filon de Zebedeo, kaj Johanon, lian fraton, kiuj ankaŭ estis en la ŝipeto, riparante la retojn."],[1,20,"Kaj tuj li alvokis ilin; kaj ili lasis sian patron Zebedeo en la ŝipeto kun la dungitoj, kaj foriris post li.","Kaj tuj li alvokis ilin; kaj ili lasis sian patron Zebedeo en la ŝipeto kun la dungitoj, kaj foriris post li."],[1,21,"Kaj ili iris en Kapernaumon, kaj tuj en la sabato li eniris en la sinagogon kaj instruis.","Kaj ili iris en Kapernaumon, kaj tuj en la sabato li eniris en la sinagogon kaj instruis."],[1,22,"Kaj oni miris pro lia instruado; ĉar li instruis kiel havanta aŭtoritaton, kaj ne kiel la skribistoj.","Kaj oni miris pro lia instruado; ĉar li instruis kiel havanta aŭtoritaton, kaj ne kiel la skribistoj."],[1,23,"Kaj en ilia sinagogo estis viro kun malpura spirito; kaj li ekkriis,","Kaj en ilia sinagogo estis viro kun malpura spirito; kaj li ekkriis,"],[1,24,"dirante: Kio estas inter ni kaj vi, Jesuo Nazaretano? ĉu vi venis, por pereigi nin? mi scias, kiu vi estas: la Sanktulo de Dio.","dirante: Kio estas inter ni kaj vi, Jesuo Nazaretano? ĉu vi venis, por pereigi nin? mi scias, kiu vi estas: la Sanktulo de Dio."],[1,25,"Kaj Jesuo severe admonis lin, dirante: Silentu, kaj eliru el li.","Kaj Jesuo severe admonis lin, dirante: Silentu, kaj eliru el li."],[1,26,"Kaj la malpura spirito konvulsiigis lin, kaj, laŭte kriinte, eliris el li.","Kaj la malpura spirito konvulsiigis lin, kaj, laŭte kriinte, eliris el li."],[1,27,"Kaj ĉiuj miregis tiom, ke ili diskutis inter si, dirante: Kio estas ĉi tio? jen nova instruado! kun aŭtoritato li ordonas eĉ al la malpuraj spiritoj, kaj ili obeas lin.","Kaj ĉiuj miregis tiom, ke ili diskutis inter si, dirante: Kio estas ĉi tio? jen nova instruado! kun aŭtoritato li ordonas eĉ al la malpuraj spiritoj, kaj ili obeas lin."],[1,28,"Kaj tuj la famo pri li disvastiĝis ĉie en la tutan ĉirkaŭaĵon de Galileo.","Kaj tuj la famo pri li disvastiĝis ĉie en la tutan ĉirkaŭaĵon de Galileo."],[1,29,"Kaj tuj, elirinte el la sinagogo, ili eniris en la domon de Simon kaj Andreo, kun Jakobo kaj Johano.","Kaj tuj, elirinte el la sinagogo, ili eniris en la domon de Simon kaj Andreo, kun Jakobo kaj Johano."],[1,30,"Sed la bopatrino de Simon kuŝis malsana de febro; kaj tuj oni sciigis al li pri ŝi;","Sed la bopatrino de Simon kuŝis malsana de febro; kaj tuj oni sciigis al li pri ŝi;"],[1,31,"kaj veninte, li prenis ŝian manon kaj levis ŝin; kaj la febro forlasis ŝin, kaj ŝi servis al ili.","kaj veninte, li prenis ŝian manon kaj levis ŝin; kaj la febro forlasis ŝin, kaj ŝi servis al ili."],[1,32,"Kaj vespere, kiam la suno subiris, oni venigis al li ĉiujn, kiuj estis malsanaj kaj demonhavantaj.","Kaj vespere, kiam la suno subiris, oni venigis al li ĉiujn, kiuj estis malsanaj kaj demonhavantaj."],[1,33,"Kaj la tuta urbo kolektiĝis ĉe la pordo.","Kaj la tuta urbo kolektiĝis ĉe la pordo."],[1,34,"Kaj li sanigis multajn, kiuj malsanis de diversaj malsanoj, kaj elpelis multajn demonojn; kaj li ne permesis al la demonoj paroli, ĉar ili konis lin.","Kaj li sanigis multajn, kiuj malsanis de diversaj malsanoj, kaj elpelis multajn demonojn; kaj li ne permesis al la demonoj paroli, ĉar ili konis lin."],[1,35,"Kaj matene, antaŭ ol la nokto pasis, li leviĝis, kaj foriris en dezertan lokon, kaj tie preĝadis.","Kaj matene, antaŭ ol la nokto pasis, li leviĝis, kaj foriris en dezertan lokon, kaj tie preĝadis."],[1,36,"Kaj Simon kaj liaj kunuloj elserĉis lin;","Kaj Simon kaj liaj kunuloj elserĉis lin;"],[1,37,"kaj ili trovis lin, kaj diris al li: Ĉiuj vin serĉas.","kaj ili trovis lin, kaj diris al li: Ĉiuj vin serĉas."],[1,38,"Kaj li diris al ili: Ni iru aliloken en la proksimajn urbetojn, por ke mi tie ankaŭ prediku; ĉar por tio mi venis.","Kaj li diris al ili: Ni iru aliloken en la proksimajn urbetojn, por ke mi tie ankaŭ prediku; ĉar por tio mi venis."],[1,39,"Kaj li iris, predikante en iliaj sinagogoj tra la tuta Galileo, kaj elpelante la demonojn.","Kaj li iris, predikante en iliaj sinagogoj tra la tuta Galileo, kaj elpelante la demonojn."],[1,40,"Kaj venis al li leprulo, alvokante lin, kaj genuinte, li diris al li: Se vi nur volas, vi povas min purigi.","Kaj venis al li leprulo, alvokante lin, kaj genuinte, li diris al li: Se vi nur volas, vi povas min purigi."],[1,41,"Kaj kortuŝite, li etendis la manon kaj tuŝis lin, kaj diris al li: Mi volas; estu purigita.","Kaj kortuŝite, li etendis la manon kaj tuŝis lin, kaj diris al li: Mi volas; estu purigita."],[1,42,"Kaj tuj la lepro foriris de li, kaj li fariĝis pura.","Kaj tuj la lepro foriris de li, kaj li fariĝis pura."],[1,43,"Kaj severe avertinte lin, li tuj forsendis lin,","Kaj severe avertinte lin, li tuj forsendis lin,"],[1,44,"kaj diris al li: Zorgu, ke vi diru nenion al iu; sed iru, montru vin al la pastro, kaj oferu pro via purigado tion, kion Moseo ordonis, por atesto al ili.","kaj diris al li: Zorgu, ke vi diru nenion al iu; sed iru, montru vin al la pastro, kaj oferu pro via purigado tion, kion Moseo ordonis, por atesto al ili."],[1,45,"Sed li eliris, kaj komencis diligente rakonti kaj disfamigi la aferon, tiel ke Jesuo jam ne povis malkaŝe eniri en urbon, sed restis ekstere en dezertaj lokoj; kaj oni venis al li el ĉie.","Sed li eliris, kaj komencis diligente rakonti kaj disfamigi la aferon, tiel ke Jesuo jam ne povis malkaŝe eniri en urbon, sed restis ekstere en dezertaj lokoj; kaj oni venis al li el ĉie."],[2,1,"Kaj kiam li revenis en Kapernaumon post kelke da tagoj, oni sciiĝis, ke li estas en domo.","Kaj kiam li revenis en Kapernaumon post kelke da tagoj, oni sciiĝis, ke li estas en domo."],[2,2,"Kaj multaj kunvenis, tiel ke jam ne estis loko eĉ apud la pordo; kaj li parolis al ili la vorton.","Kaj multaj kunvenis, tiel ke jam ne estis loko eĉ apud la pordo; kaj li parolis al ili la vorton."],[2,3,"Kaj oni venis, alportante al li paralizulon, portatan de kvar homoj.","Kaj oni venis, alportante al li paralizulon, portatan de kvar homoj."],[2,4,"Kaj ne povante alproksimiĝi al li pro la homamaso, ili malkovris la tegmenton, kie li estis; kaj trafosinte ĝin, ili mallevis la liton, sur kiu kuŝis la paralizulo.","Kaj ne povante alproksimiĝi al li pro la homamaso, ili malkovris la tegmenton, kie li estis; kaj trafosinte ĝin, ili mallevis la liton, sur kiu kuŝis la paralizulo."],[2,5,"Kaj Jesuo, vidante ilian fidon, diris al la paralizulo: Filo, viaj pekoj estas pardonitaj.","Kaj Jesuo, vidante ilian fidon, diris al la paralizulo: Filo, viaj pekoj estas pardonitaj."],[2,6,"Sed estis iuj el la skribistoj tie, sidantaj kaj diskutantaj en siaj koroj:","Sed estis iuj el la skribistoj tie, sidantaj kaj diskutantaj en siaj koroj:"],[2,7,"Kial tiu tiel parolas? li blasfemas: kiu povas pardoni pekojn, krom Dio sola?","Kial tiu tiel parolas? li blasfemas: kiu povas pardoni pekojn, krom Dio sola?"],[2,8,"Kaj Jesuo, tuj eksciante en sia spirito, ke tiel ili diskutas en si, diris al ili: Kial vi tion diskutas en viaj koroj?","Kaj Jesuo, tuj eksciante en sia spirito, ke tiel ili diskutas en si, diris al ili: Kial vi tion diskutas en viaj koroj?"],[2,9,"Kio estas pli facila: diri al la paralizulo: Viaj pekoj estas pardonitaj; aŭ diri: Leviĝu, prenu vian liton, kaj piediru?","Kio estas pli facila: diri al la paralizulo: Viaj pekoj estas pardonitaj; aŭ diri: Leviĝu, prenu vian liton, kaj piediru?"],[2,10,"Sed por ke vi sciu, ke la Filo de homo havas aŭtoritaton sur la tero pardoni pekojn — li diris al la paralizulo:","Sed por ke vi sciu, ke la Filo de homo havas aŭtoritaton sur la tero pardoni pekojn — li diris al la paralizulo:"],[2,11,"Mi diras al vi: Leviĝu, prenu vian liton, kaj iru al via domo.","Mi diras al vi: Leviĝu, prenu vian liton, kaj iru al via domo."],[2,12,"Kaj li leviĝis, kaj tuj prenis la liton, kaj eliris antaŭ ĉiuj, tiel ke ĉiuj miregis, kaj gloris Dion, dirante: Neniam ni vidis ion tian.","Kaj li leviĝis, kaj tuj prenis la liton, kaj eliris antaŭ ĉiuj, tiel ke ĉiuj miregis, kaj gloris Dion, dirante: Neniam ni vidis ion tian."],[2,13,"Kaj denove li eliris al la marbordo, kaj la tuta homamaso venis al li, kaj li instruis ilin.","Kaj denove li eliris al la marbordo, kaj la tuta homamaso venis al li, kaj li instruis ilin."],[2,14,"Kaj preterpasante, li vidis Levin, filon de Alfeo, sidantan ĉe la impostejo, kaj li diris al li: Sekvu min. Kaj li stariĝis, kaj sekvis lin.","Kaj preterpasante, li vidis Levin, filon de Alfeo, sidantan ĉe la impostejo, kaj li diris al li: Sekvu min. Kaj li stariĝis, kaj sekvis lin."],[2,15,"Kaj li sidis ĉe manĝo en lia domo, kaj multaj impostistoj kaj pekuloj kunsidis kun Jesuo kaj liaj disĉiploj; ĉar ili estis multaj, kaj ili sekvis lin.","Kaj li sidis ĉe manĝo en lia domo, kaj multaj impostistoj kaj pekuloj kunsidis kun Jesuo kaj liaj disĉiploj; ĉar ili estis multaj, kaj ili sekvis lin."],[2,16,"Kaj la skribistoj kaj la Fariseoj, vidante, ke li manĝas kun la pekuloj kaj la impostistoj, diris al liaj disĉiploj: Li manĝas kaj trinkas kun impostistoj kaj pekuloj.","Kaj la skribistoj kaj la Fariseoj, vidante, ke li manĝas kun la pekuloj kaj la impostistoj, diris al liaj disĉiploj: Li manĝas kaj trinkas kun impostistoj kaj pekuloj."],[2,17,"Kaj aŭdinte tion, Jesuo diris al ili: Ne la sanuloj bezonas kuraciston, sed la malsanuloj: mi venis, por alvoki ne justulojn, sed pekulojn.","Kaj aŭdinte tion, Jesuo diris al ili: Ne la sanuloj bezonas kuraciston, sed la malsanuloj: mi venis, por alvoki ne justulojn, sed pekulojn."],[2,18,"Kaj la disĉiploj de Johano kaj la Fariseoj estis fastantaj, kaj oni venis, kaj diris al li: Kial fastas la disĉiploj de Johano kaj de la Fariseoj, sed viaj ne fastas?","Kaj la disĉiploj de Johano kaj la Fariseoj estis fastantaj, kaj oni venis, kaj diris al li: Kial fastas la disĉiploj de Johano kaj de la Fariseoj, sed viaj ne fastas?"],[2,19,"Kaj Jesuo diris al ili: Ĉu la filoj de la edziĝejo povas fasti, dum la fianĉo estas kun ili? Tiel longe, kiel ili havas kun si la fianĉon, ili ne povas fasti.","Kaj Jesuo diris al ili: Ĉu la filoj de la edziĝejo povas fasti, dum la fianĉo estas kun ili? Tiel longe, kiel ili havas kun si la fianĉon, ili ne povas fasti."],[2,20,"Sed venos tagoj, kiam la fianĉo estos prenita for de ili, kaj tiam ili fastos en tiuj tagoj.","Sed venos tagoj, kiam la fianĉo estos prenita for de ili, kaj tiam ili fastos en tiuj tagoj."],[2,21,"Neniu alkudras flikaĵon el nefulita drapo sur malnovan veston; alie la nova plenigaĵo ion forprenas de la malnova ŝtofo, kaj pli malbona ŝiraĵo fariĝas.","Neniu alkudras flikaĵon el nefulita drapo sur malnovan veston; alie la nova plenigaĵo ion forprenas de la malnova ŝtofo, kaj pli malbona ŝiraĵo fariĝas."],[2,22,"Kaj neniu enverŝas novan vinon en malnovajn felsakojn; alie la vino krevigos la felsakojn, kaj la vino elfluos kaj la felsakoj detruiĝos; sed oni enverŝas novan vinon en novajn felsakojn.","Kaj neniu enverŝas novan vinon en malnovajn felsakojn; alie la vino krevigos la felsakojn, kaj la vino elfluos kaj la felsakoj detruiĝos; sed oni enverŝas novan vinon en novajn felsakojn."],[2,23,"Kaj en sabato li iris tra la grenkampoj, kaj liaj disĉiploj komencis dum la vojiro deŝiri la spikojn.","Kaj en sabato li iris tra la grenkampoj, kaj liaj disĉiploj komencis dum la vojiro deŝiri la spikojn."],[2,24,"Kaj la Fariseoj diris al li: Jen kial ili en la sabato faras tion, kio ne estas permesata?","Kaj la Fariseoj diris al li: Jen kial ili en la sabato faras tion, kio ne estas permesata?"],[2,25,"Kaj li diris al ili: Ĉu vi neniam legis, kion faris David, kiam li havis bezonon kaj malsatis, li kaj liaj kunuloj?","Kaj li diris al ili: Ĉu vi neniam legis, kion faris David, kiam li havis bezonon kaj malsatis, li kaj liaj kunuloj?"],[2,26,"Ke li eniris en la domon de Dio, kiam Ebjatar estis ĉefpastro, kaj manĝis la panojn de propono, kiujn manĝi ne estas permesate krom al la pastroj, kaj donis ankaŭ al siaj kunuloj?","Ke li eniris en la domon de Dio, kiam Ebjatar estis ĉefpastro, kaj manĝis la panojn de propono, kiujn manĝi ne estas permesate krom al la pastroj, kaj donis ankaŭ al siaj kunuloj?"],[2,27,"Kaj li diris al ili: La sabato estiĝis por la homo, kaj ne la homo por la sabato;","Kaj li diris al ili: La sabato estiĝis por la homo, kaj ne la homo por la sabato;"],[2,28,"tial la Filo de homo estas sinjoro eĉ de la sabato.","tial la Filo de homo estas sinjoro eĉ de la sabato."],[3,1,"Kaj denove li eniris en la sinagogon, kaj tie estis viro, havanta manon velkintan.","Kaj denove li eniris en la sinagogon, kaj tie estis viro, havanta manon velkintan."],[3,2,"Kaj oni observis lin, ĉu en la sabato li lin sanigos, por ke ili povu lin akuzi.","Kaj oni observis lin, ĉu en la sabato li lin sanigos, por ke ili povu lin akuzi."],[3,3,"Kaj li diris al la viro, kiu havis la velkintan manon: Stariĝu en la mezo.","Kaj li diris al la viro, kiu havis la velkintan manon: Stariĝu en la mezo."],[3,4,"Kaj li diris al ili: Ĉu estas permesate bonfari en sabato, aŭ malbonfari? savi vivon, aŭ mortigi? Sed ili silentis.","Kaj li diris al ili: Ĉu estas permesate bonfari en sabato, aŭ malbonfari? savi vivon, aŭ mortigi? Sed ili silentis."],[3,5,"Kaj kiam kun kolero li ĉirkaŭrigardis ilin, ĉagrenite pro la obstiniĝo de ilia koro, li diris al la viro: Etendu vian manon. Kaj li etendis ĝin, kaj lia mano resaniĝis.","Kaj kiam kun kolero li ĉirkaŭrigardis ilin, ĉagrenite pro la obstiniĝo de ilia koro, li diris al la viro: Etendu vian manon. Kaj li etendis ĝin, kaj lia mano resaniĝis."],[3,6,"Kaj la Fariseoj eliris, kaj tuj konsiliĝis kun la Herodanoj kontraŭ li, kiamaniere lin pereigi.","Kaj la Fariseoj eliris, kaj tuj konsiliĝis kun la Herodanoj kontraŭ li, kiamaniere lin pereigi."],[3,7,"Kaj Jesuo kun siaj disĉiploj foriris ĝis la maro; kaj granda homamaso el Galileo sekvis lin. Kaj el Judujo","Kaj Jesuo kun siaj disĉiploj foriris ĝis la maro; kaj granda homamaso el Galileo sekvis lin. Kaj el Judujo"],[3,8,"kaj el Jerusalem kaj el Edom kaj el Transjordano kaj el ĉirkaŭ Tiro kaj Cidon, grandnombra homamaso, aŭdinte ĉion, kion li faris, venis al li.","kaj el Jerusalem kaj el Edom kaj el Transjordano kaj el ĉirkaŭ Tiro kaj Cidon, grandnombra homamaso, aŭdinte ĉion, kion li faris, venis al li."],[3,9,"Kaj li diris al siaj disĉiploj, ke malgranda ŝipeto estu je lia dispono, pro la homamaso, por ke oni ne premu lin;","Kaj li diris al siaj disĉiploj, ke malgranda ŝipeto estu je lia dispono, pro la homamaso, por ke oni ne premu lin;"],[3,10,"ĉar multajn li jam sanigis, tiel ke ĉiuj, kiuj havis malsanojn, premadis sur lin, por tuŝi lin.","ĉar multajn li jam sanigis, tiel ke ĉiuj, kiuj havis malsanojn, premadis sur lin, por tuŝi lin."],[3,11,"Kaj malpuraj spiritoj, tuj kiam ili vidis lin, falis antaŭ li, kaj kriis, dirante: Vi estas la Filo de Dio.","Kaj malpuraj spiritoj, tuj kiam ili vidis lin, falis antaŭ li, kaj kriis, dirante: Vi estas la Filo de Dio."],[3,12,"Kaj li severe admonis ilin, ke ili ne konatigu lin.","Kaj li severe admonis ilin, ke ili ne konatigu lin."],[3,13,"Kaj li supreniris sur la monton, kaj alvokis tiujn, kiujn li mem volis; kaj ili venis al li.","Kaj li supreniris sur la monton, kaj alvokis tiujn, kiujn li mem volis; kaj ili venis al li."],[3,14,"Kaj li elektis dek du, kiujn ankaŭ li nomis apostoloj, por ke ili estu kun li, kaj por ke li dissendu ilin por prediki,","Kaj li elektis dek du, kiujn ankaŭ li nomis apostoloj, por ke ili estu kun li, kaj por ke li dissendu ilin por prediki,"],[3,15,"kaj por havi aŭtoritaton elpeli demonojn:","kaj por havi aŭtoritaton elpeli demonojn:"],[3,16,"kaj Simonon li alnomis Petro;","kaj Simonon li alnomis Petro;"],[3,17,"kaj Jakobon, filon de Zebedeo, kaj Johanon, fraton de Jakobo, kaj tiujn li alnomis Boanerges, tio estas, Filoj de tondro;","kaj Jakobon, filon de Zebedeo, kaj Johanon, fraton de Jakobo, kaj tiujn li alnomis Boanerges, tio estas, Filoj de tondro;"],[3,18,"kaj Andreon kaj Filipon kaj Bartolomeon kaj Mateon kaj Tomason, kaj Jakobon, filon de Alfeo, kaj Tadeon, kaj Simonon, la Fervorulon,","kaj Andreon kaj Filipon kaj Bartolomeon kaj Mateon kaj Tomason, kaj Jakobon, filon de Alfeo, kaj Tadeon, kaj Simonon, la Fervorulon,"],[3,19,"kaj Judason Iskariotan, kiu ankaŭ perfidis lin. Kaj li venis en domon.","kaj Judason Iskariotan, kiu ankaŭ perfidis lin. Kaj li venis en domon."],[3,20,"Kaj denove la homamaso kunvenis tiel, ke ili ne povis eĉ manĝi panon.","Kaj denove la homamaso kunvenis tiel, ke ili ne povis eĉ manĝi panon."],[3,21,"Kaj liaj amikoj, aŭdinte tion, eliris, por kapti lin, ĉar ili diris: Li frenezas.","Kaj liaj amikoj, aŭdinte tion, eliris, por kapti lin, ĉar ili diris: Li frenezas."],[3,22,"Kaj la skribistoj, kiuj alvenis el Jerusalem, diris: Li havas Baal-Zebubon; per la estro de la demonoj li elpelas la demonojn.","Kaj la skribistoj, kiuj alvenis el Jerusalem, diris: Li havas Baal-Zebubon; per la estro de la demonoj li elpelas la demonojn."],[3,23,"Kaj li alvokis ilin, kaj parolis al ili parabole: Kiel povas Satano elpeli Satanon?","Kaj li alvokis ilin, kaj parolis al ili parabole: Kiel povas Satano elpeli Satanon?"],[3,24,"Kaj se regno estas dividita kontraŭ si, tiu regno ne povas stari.","Kaj se regno estas dividita kontraŭ si, tiu regno ne povas stari."],[3,25,"Kaj se domo estas dividita kontraŭ si, tiu domo ne povas stari.","Kaj se domo estas dividita kontraŭ si, tiu domo ne povas stari."],[3,26,"Kaj se Satano ribelis kontraŭ si kaj estas dividita, li ne povas stari, sed havas finon.","Kaj se Satano ribelis kontraŭ si kaj estas dividita, li ne povas stari, sed havas finon."],[3,27,"Sed neniu povas eniri en la domon de la fortulo kaj trarabi liajn posedaĵojn, se unue li ne ligos la fortulon, kaj poste li trarabos lian domon.","Sed neniu povas eniri en la domon de la fortulo kaj trarabi liajn posedaĵojn, se unue li ne ligos la fortulon, kaj poste li trarabos lian domon."],[3,28,"Vere mi diras al vi: Ĉiuj iliaj pekoj estos pardonitaj al la filoj de homoj, kaj iliaj blasfemoj, per kiuj ajn ili blasfemos;","Vere mi diras al vi: Ĉiuj iliaj pekoj estos pardonitaj al la filoj de homoj, kaj iliaj blasfemoj, per kiuj ajn ili blasfemos;"],[3,29,"sed iu, kiu blasfemos kontraŭ la Sankta Spirito, eterne ne havos pardonon, sed estas kulpa pri eterna peko;","sed iu, kiu blasfemos kontraŭ la Sankta Spirito, eterne ne havos pardonon, sed estas kulpa pri eterna peko;"],[3,30,"ĉar oni diris: Li havas malpuran spiriton.","ĉar oni diris: Li havas malpuran spiriton."],[3,31,"Kaj jen alvenis lia patrino kaj liaj fratoj, kaj starante ekstere, ili sendis al li, vokante lin.","Kaj jen alvenis lia patrino kaj liaj fratoj, kaj starante ekstere, ili sendis al li, vokante lin."],[3,32,"Kaj homamaso sidis ĉirkaŭ li; kaj oni diris al li: Jen via patrino kaj viaj fratoj ekstere vin serĉas.","Kaj homamaso sidis ĉirkaŭ li; kaj oni diris al li: Jen via patrino kaj viaj fratoj ekstere vin serĉas."],[3,33,"Kaj li respondis al ili, dirante: Kiuj estas mia patrino kaj miaj fratoj?","Kaj li respondis al ili, dirante: Kiuj estas mia patrino kaj miaj fratoj?"],[3,34,"Kaj ĉirkaŭrigardante tiujn, kiuj ronde ĉirkaŭ li sidis, li diris: Jen mia patrino kaj miaj fratoj!","Kaj ĉirkaŭrigardante tiujn, kiuj ronde ĉirkaŭ li sidis, li diris: Jen mia patrino kaj miaj fratoj!"],[3,35,"Ĉar kiu ajn faros la volon de Dio, tiu estas mia frato kaj mia fratino kaj mia patrino.","Ĉar kiu ajn faros la volon de Dio, tiu estas mia frato kaj mia fratino kaj mia patrino."],[4,1,"Kaj denove li komencis instrui apud la maro. Kaj kolektiĝis al li tre granda homamaso tiel, ke li eniris en ŝipeton, kaj sidis sur la maro; kaj la tuta homamaso estis sur la tero apud la maro.","Kaj denove li komencis instrui apud la maro. Kaj kolektiĝis al li tre granda homamaso tiel, ke li eniris en ŝipeton, kaj sidis sur la maro; kaj la tuta homamaso estis sur la tero apud la maro."],[4,2,"Kaj li multe instruis ilin per paraboloj, kaj diris al ili en sia instruado:","Kaj li multe instruis ilin per paraboloj, kaj diris al ili en sia instruado:"],[4,3,"Aŭskultu: jen semisto eliris, por semi;","Aŭskultu: jen semisto eliris, por semi;"],[4,4,"kaj dum li semis, iuj semoj falis apud la vojo, kaj la birdoj venis kaj formanĝis ilin.","kaj dum li semis, iuj semoj falis apud la vojo, kaj la birdoj venis kaj formanĝis ilin."],[4,5,"Kaj aliaj falis sur ŝtonan lokon, kie ili ne havis multe da tero; kaj tuj ili ekkreskis, ĉar ili ne havis profundecon de tero;","Kaj aliaj falis sur ŝtonan lokon, kie ili ne havis multe da tero; kaj tuj ili ekkreskis, ĉar ili ne havis profundecon de tero;"],[4,6,"kaj kiam la suno leviĝis, ili brulsekiĝis, kaj ĉar ili ne havis radikon, ili forvelkis.","kaj kiam la suno leviĝis, ili brulsekiĝis, kaj ĉar ili ne havis radikon, ili forvelkis."],[4,7,"Kaj aliaj falis inter dornojn, kaj la dornoj kreskis kaj sufokis ilin, kaj ili ne donis frukton.","Kaj aliaj falis inter dornojn, kaj la dornoj kreskis kaj sufokis ilin, kaj ili ne donis frukton."],[4,8,"Kaj aliaj falis en la bonan teron, kaj donis frukton, kreskante kaj multobliĝante, kaj produktis tridekoble kaj sesdekoble kaj centoble.","Kaj aliaj falis en la bonan teron, kaj donis frukton, kreskante kaj multobliĝante, kaj produktis tridekoble kaj sesdekoble kaj centoble."],[4,9,"Kaj li diris: Kiu havas orelojn por aŭdi, tiu aŭdu.","Kaj li diris: Kiu havas orelojn por aŭdi, tiu aŭdu."],[4,10,"Kaj kiam li estis sola, tiuj, kiuj alestis kune kun la dek du, demandis lin pri la paraboloj.","Kaj kiam li estis sola, tiuj, kiuj alestis kune kun la dek du, demandis lin pri la paraboloj."],[4,11,"Kaj li diris al ili: Al vi estas donite scii la misteron de la regno de Dio; sed al tiuj, kiuj estas ekstere, ĉio estas farata per paraboloj;","Kaj li diris al ili: Al vi estas donite scii la misteron de la regno de Dio; sed al tiuj, kiuj estas ekstere, ĉio estas farata per paraboloj;"],[4,12,"por ke, vidante, ili vidu, sed ne rimarku; kaj aŭdante, ili aŭdu, sed ne komprenu; por ke neniam ili konvertiĝu kaj pardoniĝu.","por ke, vidante, ili vidu, sed ne rimarku; kaj aŭdante, ili aŭdu, sed ne komprenu; por ke neniam ili konvertiĝu kaj pardoniĝu."],[4,13,"Kaj li diris al ili: Ĉu vi ne scias ĉi tiun parabolon? kiel do vi povos kompreni ĉiujn parabolojn?","Kaj li diris al ili: Ĉu vi ne scias ĉi tiun parabolon? kiel do vi povos kompreni ĉiujn parabolojn?"],[4,14,"La semisto semas la vorton.","La semisto semas la vorton."],[4,15,"Jen do tiuj, kiuj estas apud la vojo, kie estas semata la vorto; kaj kiam ili aŭdis, tuj venas Satano, kaj forprenas la vorton, en ili semitan.","Jen do tiuj, kiuj estas apud la vojo, kie estas semata la vorto; kaj kiam ili aŭdis, tuj venas Satano, kaj forprenas la vorton, en ili semitan."],[4,16,"Kaj tiel same jen la semitaj ĉe la ŝtonaj lokoj: ili aŭdas la vorton, kaj tuj kun ĝojo akceptas ĝin;","Kaj tiel same jen la semitaj ĉe la ŝtonaj lokoj: ili aŭdas la vorton, kaj tuj kun ĝojo akceptas ĝin;"],[4,17,"kaj ili ne havas en si radikon, sed restas nur portempe; kiam do venas sufero aŭ persekuto pro la vorto, tuj ili falpuŝiĝas.","kaj ili ne havas en si radikon, sed restas nur portempe; kiam do venas sufero aŭ persekuto pro la vorto, tuj ili falpuŝiĝas."],[4,18,"Kaj jen la semitaj ĉe la dornoj: tiuj, kiuj aŭdis la vorton;","Kaj jen la semitaj ĉe la dornoj: tiuj, kiuj aŭdis la vorton;"],[4,19,"sed la zorgoj de la mondo kaj la trompo de riĉo kaj la deziroj al aliaj aferoj, enirante, sufokas la vorton, kaj ĝi fariĝas senfrukta.","sed la zorgoj de la mondo kaj la trompo de riĉo kaj la deziroj al aliaj aferoj, enirante, sufokas la vorton, kaj ĝi fariĝas senfrukta."],[4,20,"Kaj jen la semitaj ĉe la bona tero: tiuj, kiuj aŭdas la vorton kaj akceptas ĝin, kaj donas frukton, jen tridekoble, kaj jen sesdekoble, kaj jen centoble.","Kaj jen la semitaj ĉe la bona tero: tiuj, kiuj aŭdas la vorton kaj akceptas ĝin, kaj donas frukton, jen tridekoble, kaj jen sesdekoble, kaj jen centoble."],[4,21,"Kaj li diris al ili: Ĉu lampo enportiĝas, por esti metita sub grenmezurilon aŭ sub liton, kaj ne por stari sur la lampingo?","Kaj li diris al ili: Ĉu lampo enportiĝas, por esti metita sub grenmezurilon aŭ sub liton, kaj ne por stari sur la lampingo?"],[4,22,"Ĉar nenio estas kaŝita krom por tio, ke ĝi estu malkaŝita; nek io estas sekreta krom por tio, ke ĝi estu aperigita.","Ĉar nenio estas kaŝita krom por tio, ke ĝi estu malkaŝita; nek io estas sekreta krom por tio, ke ĝi estu aperigita."],[4,23,"Se iu havas orelojn por aŭdi, tiu aŭdu.","Se iu havas orelojn por aŭdi, tiu aŭdu."],[4,24,"Kaj li diris al ili: Atentu, kion vi aŭdas; per kia mezuro vi mezuras, laŭ tiu sama oni mezuros al vi, kaj eĉ faros al vi aldonon.","Kaj li diris al ili: Atentu, kion vi aŭdas; per kia mezuro vi mezuras, laŭ tiu sama oni mezuros al vi, kaj eĉ faros al vi aldonon."],[4,25,"Ĉar al tiu, kiu havas, estos donite; sed for de tiu, kiu ne havas, estos prenita eĉ tio, kion li havas.","Ĉar al tiu, kiu havas, estos donite; sed for de tiu, kiu ne havas, estos prenita eĉ tio, kion li havas."],[4,26,"Kaj li diris: Tia estas la regno de Dio, kvazaŭ homo ĵetus semojn sur la teron,","Kaj li diris: Tia estas la regno de Dio, kvazaŭ homo ĵetus semojn sur la teron,"],[4,27,"kaj dormus kaj leviĝus nokte kaj tage, kaj la semoj burĝonus kaj kreskus, li ne scias kiel.","kaj dormus kaj leviĝus nokte kaj tage, kaj la semoj burĝonus kaj kreskus, li ne scias kiel."],[4,28,"Aŭtomate la tero donas frukton, unue folion, poste spikon, poste plenan grenon en spiko.","Aŭtomate la tero donas frukton, unue folion, poste spikon, poste plenan grenon en spiko."],[4,29,"Sed kiam la frukto estas preta, li tuj svingas la rikoltilon, ĉar venis la rikolto.","Sed kiam la frukto estas preta, li tuj svingas la rikoltilon, ĉar venis la rikolto."],[4,30,"Kaj li diris: Al kio ni komparu la regnon de Dio? aŭ per kia parabolo ni montru ĝin?","Kaj li diris: Al kio ni komparu la regnon de Dio? aŭ per kia parabolo ni montru ĝin?"],[4,31,"Al sinapa semeto, kiu, kiam ĝi estas semita sur la teron, estas pli malgranda ol ĉiuj aliaj semoj, kiuj estas sur la tero,","Al sinapa semeto, kiu, kiam ĝi estas semita sur la teron, estas pli malgranda ol ĉiuj aliaj semoj, kiuj estas sur la tero,"],[4,32,"tamen semite, kreskas kaj fariĝas pli granda ol ĉiuj legomoj, kaj elmetas grandajn branĉojn, tiel ke sub ĝia ombro povas ekloĝi la birdoj de la ĉielo.","tamen semite, kreskas kaj fariĝas pli granda ol ĉiuj legomoj, kaj elmetas grandajn branĉojn, tiel ke sub ĝia ombro povas ekloĝi la birdoj de la ĉielo."],[4,33,"Kaj per multaj tiaj paraboloj li parolis al ili la vorton laŭ tio, kiel ili povis aŭskulti;","Kaj per multaj tiaj paraboloj li parolis al ili la vorton laŭ tio, kiel ili povis aŭskulti;"],[4,34,"kaj sen parabolo li ne parolis al ili; sed private li klarigis ĉion al siaj disĉiploj.","kaj sen parabolo li ne parolis al ili; sed private li klarigis ĉion al siaj disĉiploj."],[4,35,"Kaj en tiu tago, kiam vesperiĝis, li diris al ili: Ni transiru al la alia bordo.","Kaj en tiu tago, kiam vesperiĝis, li diris al ili: Ni transiru al la alia bordo."],[4,36,"Kaj forsendinte la homamason, ili kondukis lin kun si, kiel li estis en la ŝipeto. Kaj aliaj ŝipetoj akompanis lin.","Kaj forsendinte la homamason, ili kondukis lin kun si, kiel li estis en la ŝipeto. Kaj aliaj ŝipetoj akompanis lin."],[4,37,"Kaj okazis granda ventego, kaj ondoj batis en la ŝipeton, tiel ke la ŝipeto estis jam pleniĝanta.","Kaj okazis granda ventego, kaj ondoj batis en la ŝipeton, tiel ke la ŝipeto estis jam pleniĝanta."],[4,38,"Kaj li estis dormanta en la posta parto sur la kuseno; kaj ili vekis lin, kaj diris al li: Majstro, ĉu vi ne zorgas pri tio, ke ni pereas?","Kaj li estis dormanta en la posta parto sur la kuseno; kaj ili vekis lin, kaj diris al li: Majstro, ĉu vi ne zorgas pri tio, ke ni pereas?"],[4,39,"Kaj vekite, li admonis la venton, kaj diris al la maro: Silentu, kvietiĝu. Kaj la vento ĉesiĝis, kaj fariĝis granda sereno.","Kaj vekite, li admonis la venton, kaj diris al la maro: Silentu, kvietiĝu. Kaj la vento ĉesiĝis, kaj fariĝis granda sereno."],[4,40,"Kaj li diris al ili: Kial vi estas timemaj? ĉu vi ankoraŭ ne havas fidon?","Kaj li diris al ili: Kial vi estas timemaj? ĉu vi ankoraŭ ne havas fidon?"],[4,41,"Kaj ili timis treege, kaj diris unu al alia: Kiu do estas ĉi tiu? ĉar eĉ la vento kaj la maro obeas al li.","Kaj ili timis treege, kaj diris unu al alia: Kiu do estas ĉi tiu? ĉar eĉ la vento kaj la maro obeas al li."],[5,1,"Kaj ili venis trans la maron en la landon de la Gerasenoj.","Kaj ili venis trans la maron en la landon de la Gerasenoj."],[5,2,"Kaj kiam li elvenis el la ŝipeto, tuj lin renkontis el la tomboj viro, havanta malpuran spiriton,","Kaj kiam li elvenis el la ŝipeto, tuj lin renkontis el la tomboj viro, havanta malpuran spiriton,"],[5,3,"kiu havis loĝejon en la tomboj, kaj jam neniu povis ligi lin eĉ per kateno;","kiu havis loĝejon en la tomboj, kaj jam neniu povis ligi lin eĉ per kateno;"],[5,4,"ĉar li ofte estis ĉirkaŭligita per katenoj kaj ĉenoj, kaj la ĉenoj estis disŝiritaj de li kaj la katenoj frakasitaj; kaj neniu kapablis malsovaĝigi lin.","ĉar li ofte estis ĉirkaŭligita per katenoj kaj ĉenoj, kaj la ĉenoj estis disŝiritaj de li kaj la katenoj frakasitaj; kaj neniu kapablis malsovaĝigi lin."],[5,5,"Kaj ĉiam, nokte kaj tage, inter la tomboj kaj sur la montoj, li kriadis kaj sin tranĉis per ŝtonoj.","Kaj ĉiam, nokte kaj tage, inter la tomboj kaj sur la montoj, li kriadis kaj sin tranĉis per ŝtonoj."],[5,6,"Kaj, vidinte Jesuon el malproksime, li kuris kaj adorkliniĝis al li;","Kaj, vidinte Jesuon el malproksime, li kuris kaj adorkliniĝis al li;"],[5,7,"kaj kriante per laŭta voĉo, li diris: Kio estas inter mi kaj vi, ho Jesuo, Filo de Dio Plejalta? Mi vin ĵurpetas per Dio, ke vi ne turmentu min.","kaj kriante per laŭta voĉo, li diris: Kio estas inter mi kaj vi, ho Jesuo, Filo de Dio Plejalta? Mi vin ĵurpetas per Dio, ke vi ne turmentu min."],[5,8,"Ĉar li diris al li: Eliru, ho malpura spirito, el la viro.","Ĉar li diris al li: Eliru, ho malpura spirito, el la viro."],[5,9,"Kaj li demandis lin: Kia estas via nomo? Kaj li respondis, dirante: Mia nomo estas Legio, ĉar ni estas multaj.","Kaj li demandis lin: Kia estas via nomo? Kaj li respondis, dirante: Mia nomo estas Legio, ĉar ni estas multaj."],[5,10,"Kaj li multe petegis, ke li ne forsendu ilin el la lando.","Kaj li multe petegis, ke li ne forsendu ilin el la lando."],[5,11,"Kaj estis tie sur la monto granda grego da porkoj paŝtiĝantaj.","Kaj estis tie sur la monto granda grego da porkoj paŝtiĝantaj."],[5,12,"Kaj ili petegis lin, dirante: Sendu nin en la porkojn, por ke ni eniru en ilin.","Kaj ili petegis lin, dirante: Sendu nin en la porkojn, por ke ni eniru en ilin."],[5,13,"Kaj li permesis tion al ili. Kaj elirinte, la malpuraj spiritoj eniris en la porkojn; kaj la grego kuris rapide malsupren de la krutaĵo en la maron, ĉirkaŭ du miloj, kaj sufokiĝis en la maro.","Kaj li permesis tion al ili. Kaj elirinte, la malpuraj spiritoj eniris en la porkojn; kaj la grego kuris rapide malsupren de la krutaĵo en la maron, ĉirkaŭ du miloj, kaj sufokiĝis en la maro."],[5,14,"Kaj iliaj paŝtistoj forkuris, kaj rakontis la aferon en la urbo kaj en la kamparo. Kaj oni venis, por vidi, kio okazis.","Kaj iliaj paŝtistoj forkuris, kaj rakontis la aferon en la urbo kaj en la kamparo. Kaj oni venis, por vidi, kio okazis."],[5,15,"Kaj ili venis al Jesuo, kaj vidis la demonhavinton, kiu havis la legion, sidanta, vestita kaj en sana prudento; kaj ili timis.","Kaj ili venis al Jesuo, kaj vidis la demonhavinton, kiu havis la legion, sidanta, vestita kaj en sana prudento; kaj ili timis."],[5,16,"Kaj la vidintoj rakontis al ili, kiamaniere tio okazis al la demonhavinto, kaj pri la porkoj.","Kaj la vidintoj rakontis al ili, kiamaniere tio okazis al la demonhavinto, kaj pri la porkoj."],[5,17,"Kaj ili komencis petegi lin, ke li foriru el iliaj limoj.","Kaj ili komencis petegi lin, ke li foriru el iliaj limoj."],[5,18,"Kaj kiam li eniris en la ŝipeton, la demonhavinto petegis lin, ke li povu esti kun li.","Kaj kiam li eniris en la ŝipeton, la demonhavinto petegis lin, ke li povu esti kun li."],[5,19,"Kaj li ne permesis al li, sed diris al li: Iru al via domo, al la viaj, kaj rakontu al ili ĉion, kion faris la Eternulo por vi, kaj kiel Li kompatis vin.","Kaj li ne permesis al li, sed diris al li: Iru al via domo, al la viaj, kaj rakontu al ili ĉion, kion faris la Eternulo por vi, kaj kiel Li kompatis vin."],[5,20,"Kaj li foriris, kaj komencis famigi en Dekapolis ĉion, kion faris Jesuo por li; kaj ĉiuj miregis.","Kaj li foriris, kaj komencis famigi en Dekapolis ĉion, kion faris Jesuo por li; kaj ĉiuj miregis."],[5,21,"Kaj kiam Jesuo retransiris en la ŝipeto al la alia bordo, granda homamaso kolektiĝis al li; kaj li estis apud la maro.","Kaj kiam Jesuo retransiris en la ŝipeto al la alia bordo, granda homamaso kolektiĝis al li; kaj li estis apud la maro."],[5,22,"Kaj venis unu el la sinagogestroj, nomata Jairo, kaj ekvidinte lin, falis antaŭ liaj piedoj,","Kaj venis unu el la sinagogestroj, nomata Jairo, kaj ekvidinte lin, falis antaŭ liaj piedoj,"],[5,23,"kaj insiste lin petegis, dirante: Mia filineto estas en lasta ekstremo; venu do kaj metu viajn manojn sur ŝin, por ke ŝi saviĝu kaj vivu.","kaj insiste lin petegis, dirante: Mia filineto estas en lasta ekstremo; venu do kaj metu viajn manojn sur ŝin, por ke ŝi saviĝu kaj vivu."],[5,24,"Kaj li iris kun li, kaj granda homamaso sekvis lin kaj premis lin.","Kaj li iris kun li, kaj granda homamaso sekvis lin kaj premis lin."],[5,25,"Kaj virino, kiu jam dek du jarojn havis sangofluon,","Kaj virino, kiu jam dek du jarojn havis sangofluon,"],[5,26,"kaj multe suferis pro multaj kuracistoj, kaj elspezis sian tutan havon, kaj estis neniel helpita, sed kontraŭe eĉ pli malsaniĝis,","kaj multe suferis pro multaj kuracistoj, kaj elspezis sian tutan havon, kaj estis neniel helpita, sed kontraŭe eĉ pli malsaniĝis,"],[5,27,"aŭdinte pri Jesuo, venis en la homamaso malantaŭ lin, kaj tuŝis lian mantelon.","aŭdinte pri Jesuo, venis en la homamaso malantaŭ lin, kaj tuŝis lian mantelon."],[5,28,"Ĉar ŝi diris: Se mi nur tuŝos lian mantelon, mi estos sanigita.","Ĉar ŝi diris: Se mi nur tuŝos lian mantelon, mi estos sanigita."],[5,29,"Kaj tuj la fonto de ŝia sango sekiĝis, kaj ŝi korpe sentis, ke ŝi resaniĝis el sia malsano.","Kaj tuj la fonto de ŝia sango sekiĝis, kaj ŝi korpe sentis, ke ŝi resaniĝis el sia malsano."],[5,30,"Kaj Jesuo, tuj sentante en si, ke la potenco eliris, turnis sin en la homamaso, kaj diris: Kiu tuŝis mian veston?","Kaj Jesuo, tuj sentante en si, ke la potenco eliris, turnis sin en la homamaso, kaj diris: Kiu tuŝis mian veston?"],[5,31,"Kaj liaj disĉiploj diris al li: Vi vidas la homamason, premantan vin, kaj ĉu vi diras: Kiu min tuŝis?","Kaj liaj disĉiploj diris al li: Vi vidas la homamason, premantan vin, kaj ĉu vi diras: Kiu min tuŝis?"],[5,32,"Kaj li ĉirkaŭrigardis, por vidi tiun, kiu tion faris.","Kaj li ĉirkaŭrigardis, por vidi tiun, kiu tion faris."],[5,33,"Sed la virino, timigita kaj tremanta, sciante, kio fariĝis al ŝi, venis kaj falis antaŭ li, kaj diris al li la tutan veron.","Sed la virino, timigita kaj tremanta, sciante, kio fariĝis al ŝi, venis kaj falis antaŭ li, kaj diris al li la tutan veron."],[5,34,"Kaj li diris al ŝi: Filino, via fido vin savis; iru en paco, kaj estu sana el via malsano.","Kaj li diris al ŝi: Filino, via fido vin savis; iru en paco, kaj estu sana el via malsano."],[5,35,"Dum li ankoraŭ parolis, oni venis el la domo de la sinagogestro, dirante: Via filino mortis; kial vi ankoraŭ ĝenas la instruiston?","Dum li ankoraŭ parolis, oni venis el la domo de la sinagogestro, dirante: Via filino mortis; kial vi ankoraŭ ĝenas la instruiston?"],[5,36,"Sed Jesuo, ne atentante la parolon diritan, diris al la sinagogestro: Ne timu, nur kredu.","Sed Jesuo, ne atentante la parolon diritan, diris al la sinagogestro: Ne timu, nur kredu."],[5,37,"Kaj li ne permesis al iu sekvi kun li, krom Petro kaj Jakobo, kaj Johano, frato de Jakobo.","Kaj li ne permesis al iu sekvi kun li, krom Petro kaj Jakobo, kaj Johano, frato de Jakobo."],[5,38,"Kaj ili venis al la domo de la sinagogestro, kaj li vidis tumulton, kaj homojn plorantajn kaj funebre ĝemantajn.","Kaj ili venis al la domo de la sinagogestro, kaj li vidis tumulton, kaj homojn plorantajn kaj funebre ĝemantajn."],[5,39,"Kaj enirinte, li diris al ili: Kial vi tumultas kaj ploras? la infanino ne mortis, sed dormas.","Kaj enirinte, li diris al ili: Kial vi tumultas kaj ploras? la infanino ne mortis, sed dormas."],[5,40,"Kaj ili mokridis lin. Tamen, foriginte ĉiujn, li kondukis la patron de la infanino kaj la patrinon, kaj tiujn, kiuj estis kun li, kaj eniris tien, kie estis la infanino.","Kaj ili mokridis lin. Tamen, foriginte ĉiujn, li kondukis la patron de la infanino kaj la patrinon, kaj tiujn, kiuj estis kun li, kaj eniris tien, kie estis la infanino."],[5,41,"Kaj preninte la manon de la infanino, li diris al ŝi: Talita kumi; tio estas: Knabineto, mi diras al vi: Leviĝu.","Kaj preninte la manon de la infanino, li diris al ŝi: Talita kumi; tio estas: Knabineto, mi diras al vi: Leviĝu."],[5,42,"Kaj tuj leviĝis la knabineto kaj piediris; ĉar ŝi estis dekdujara. Kaj ili miris kun granda mirego.","Kaj tuj leviĝis la knabineto kaj piediris; ĉar ŝi estis dekdujara. Kaj ili miris kun granda mirego."],[5,43,"Kaj li severe admonis ilin, ke neniu sciiĝu pri tio; kaj li ordonis doni al ŝi manĝi.","Kaj li severe admonis ilin, ke neniu sciiĝu pri tio; kaj li ordonis doni al ŝi manĝi."],[6,1,"Kaj li eliris de tie, kaj venis en sian patrujon; kaj liaj disĉiploj lin sekvis.","Kaj li eliris de tie, kaj venis en sian patrujon; kaj liaj disĉiploj lin sekvis."],[6,2,"Kaj kiam venis la sabato, li komencis instrui en la sinagogo; kaj multaj, lin aŭdante, miris, dirante: De kie tiu viro havas tion? kaj: Kia estas la saĝeco donita al li? kaj kiaj estas tiaj potencaĵoj farataj per liaj manoj?","Kaj kiam venis la sabato, li komencis instrui en la sinagogo; kaj multaj, lin aŭdante, miris, dirante: De kie tiu viro havas tion? kaj: Kia estas la saĝeco donita al li? kaj kiaj estas tiaj potencaĵoj farataj per liaj manoj?"],[6,3,"Ĉu ĉi tiu ne estas la ĉarpentisto, filo de Maria, kaj frato de Jakobo kaj Joses kaj Judas kaj Simon? kaj ĉu liaj fratinoj ne estas ĉi tie ĉe ni? Kaj ili ofendiĝis pro li.","Ĉu ĉi tiu ne estas la ĉarpentisto, filo de Maria, kaj frato de Jakobo kaj Joses kaj Judas kaj Simon? kaj ĉu liaj fratinoj ne estas ĉi tie ĉe ni? Kaj ili ofendiĝis pro li."],[6,4,"Kaj Jesuo diris al ili: Profeto ne estas sen honoro, krom en sia patrujo kaj inter siaj parencoj kaj en sia domo.","Kaj Jesuo diris al ili: Profeto ne estas sen honoro, krom en sia patrujo kaj inter siaj parencoj kaj en sia domo."],[6,5,"Kaj li povis tie fari nenian potencaĵon, krom tio, ke li metis la manojn sur kelkajn senfortulojn kaj ilin resanigis.","Kaj li povis tie fari nenian potencaĵon, krom tio, ke li metis la manojn sur kelkajn senfortulojn kaj ilin resanigis."],[6,6,"Kaj li miris pro ilia nekredemo. Kaj li rondevizitis la vilaĝojn, instruante.","Kaj li miris pro ilia nekredemo. Kaj li rondevizitis la vilaĝojn, instruante."],[6,7,"Kaj li alvokis al si la dek du, kaj komencis forsendi ilin duope; kaj li donis al ili aŭtoritaton super malpuraj spiritoj;","Kaj li alvokis al si la dek du, kaj komencis forsendi ilin duope; kaj li donis al ili aŭtoritaton super malpuraj spiritoj;"],[6,8,"kaj li ordonis, ke ili portu nenion por la vojo krom nur bastono — nek panon, nek saketon, nek monon en sia zono;","kaj li ordonis, ke ili portu nenion por la vojo krom nur bastono — nek panon, nek saketon, nek monon en sia zono;"],[6,9,"sed ili iru piedvestitaj per sandaloj, kaj ne surmetu du tunikojn.","sed ili iru piedvestitaj per sandaloj, kaj ne surmetu du tunikojn."],[6,10,"Kaj li diris al ili: Kie ajn vi eniros en domon, tie loĝu, ĝis vi foriros el tiu loko.","Kaj li diris al ili: Kie ajn vi eniros en domon, tie loĝu, ĝis vi foriros el tiu loko."],[6,11,"Kaj se ie ajn oni vin ne akceptos, nek vin aŭskultos, tiam el tie forirante, deskuu la polvon, kiu estas sub viaj piedoj, por atesto al ili.","Kaj se ie ajn oni vin ne akceptos, nek vin aŭskultos, tiam el tie forirante, deskuu la polvon, kiu estas sub viaj piedoj, por atesto al ili."],[6,12,"Kaj foririnte, ili predikis, ke oni pentu.","Kaj foririnte, ili predikis, ke oni pentu."],[6,13,"Kaj ili elpeladis multajn demonojn, kaj ŝmiradis per oleo multajn malsanulojn kaj ilin sanigadis.","Kaj ili elpeladis multajn demonojn, kaj ŝmiradis per oleo multajn malsanulojn kaj ilin sanigadis."],[6,14,"Kaj la reĝo Herodo aŭdis pri tio, ĉar lia nomo jam konatiĝis; kaj li diris: Johano, la Baptisto, leviĝis el la mortintoj, kaj tial tiuj potencaĵoj energias en li.","Kaj la reĝo Herodo aŭdis pri tio, ĉar lia nomo jam konatiĝis; kaj li diris: Johano, la Baptisto, leviĝis el la mortintoj, kaj tial tiuj potencaĵoj energias en li."],[6,15,"Sed aliaj diris: Tiu estas Elija. Kaj aliaj diris: Tiu estas profeto, kvazaŭ unu el la profetoj.","Sed aliaj diris: Tiu estas Elija. Kaj aliaj diris: Tiu estas profeto, kvazaŭ unu el la profetoj."],[6,16,"Sed, tion aŭdinte, Herodo diris: Johano, kiun mi senkapigis, leviĝis.","Sed, tion aŭdinte, Herodo diris: Johano, kiun mi senkapigis, leviĝis."],[6,17,"Ĉar Herodo mem jam sendis, kaj arestis Johanon, kaj ligis lin en malliberejo pro Herodias, kiu estis edzino de lia frato Filipo, ĉar li estis edziĝinta kun ŝi.","Ĉar Herodo mem jam sendis, kaj arestis Johanon, kaj ligis lin en malliberejo pro Herodias, kiu estis edzino de lia frato Filipo, ĉar li estis edziĝinta kun ŝi."],[6,18,"Ĉar Johano diris al Herodo: Ne decas, ke vi havu la edzinon de via frato.","Ĉar Johano diris al Herodo: Ne decas, ke vi havu la edzinon de via frato."],[6,19,"Kaj Herodias klopodis kontraŭ li, kaj deziris mortigi lin, kaj ne povis;","Kaj Herodias klopodis kontraŭ li, kaj deziris mortigi lin, kaj ne povis;"],[6,20,"ĉar Herodo timis Johanon, sciante, ke li estas viro justa kaj sankta, kaj nepre gardis lin. Kaj aŭskultante lin, li embarasiĝis, kaj aŭskultis lin volonte.","ĉar Herodo timis Johanon, sciante, ke li estas viro justa kaj sankta, kaj nepre gardis lin. Kaj aŭskultante lin, li embarasiĝis, kaj aŭskultis lin volonte."],[6,21,"Kaj kiam venis oportuna tago, kiam Herodo pro sia naskotago faris vespermanĝon al siaj nobeloj kaj milestroj kaj ĉefoj de Galileo,","Kaj kiam venis oportuna tago, kiam Herodo pro sia naskotago faris vespermanĝon al siaj nobeloj kaj milestroj kaj ĉefoj de Galileo,"],[6,22,"eniris la filino de Herodias mem kaj dancis, kaj ŝi plaĉis al Herodo kaj al liaj kunmanĝantoj; kaj la reĝo diris al la knabino: Petu de mi, kion ajn vi volas, kaj mi tion donos al vi.","eniris la filino de Herodias mem kaj dancis, kaj ŝi plaĉis al Herodo kaj al liaj kunmanĝantoj; kaj la reĝo diris al la knabino: Petu de mi, kion ajn vi volas, kaj mi tion donos al vi."],[6,23,"Kaj li ĵuris al ŝi: Kion ajn vi petos de mi, mi tion donos al vi, ĝis duono de mia regno.","Kaj li ĵuris al ŝi: Kion ajn vi petos de mi, mi tion donos al vi, ĝis duono de mia regno."],[6,24,"Kaj elirinte, ŝi diris al sia patrino: Kion mi petu? Kaj tiu diris: La kapon de Johano, la Baptisto.","Kaj elirinte, ŝi diris al sia patrino: Kion mi petu? Kaj tiu diris: La kapon de Johano, la Baptisto."],[6,25,"Kaj ŝi tuj eniris rapide al la reĝo, kaj petis, dirante: Mi deziras, ke vi tuj donu al mi sur plado la kapon de Johano, la Baptisto.","Kaj ŝi tuj eniris rapide al la reĝo, kaj petis, dirante: Mi deziras, ke vi tuj donu al mi sur plado la kapon de Johano, la Baptisto."],[6,26,"Kaj la reĝo fariĝis tre malĝoja; tamen pro siaj ĵuroj kaj pro la kunmanĝantoj li ne volis rifuzi al ŝi.","Kaj la reĝo fariĝis tre malĝoja; tamen pro siaj ĵuroj kaj pro la kunmanĝantoj li ne volis rifuzi al ŝi."],[6,27,"Kaj tuj la reĝo elsendis soldaton el sia gardistaro, kaj ordonis alporti lian kapon; kaj elirinte, tiu senkapigis lin en la malliberejo,","Kaj tuj la reĝo elsendis soldaton el sia gardistaro, kaj ordonis alporti lian kapon; kaj elirinte, tiu senkapigis lin en la malliberejo,"],[6,28,"kaj alportis lian kapon sur plado, kaj donis ĝin al la knabino; kaj la knabino donis ĝin al sia patrino.","kaj alportis lian kapon sur plado, kaj donis ĝin al la knabino; kaj la knabino donis ĝin al sia patrino."],[6,29,"Kaj kiam liaj disĉiploj aŭdis, ili venis kaj forportis lian korpon, kaj metis ĝin en tombon.","Kaj kiam liaj disĉiploj aŭdis, ili venis kaj forportis lian korpon, kaj metis ĝin en tombon."],[6,30,"Kaj la apostoloj kolektiĝis al Jesuo, kaj rakontis al li ĉion, kion ili faris kaj instruis.","Kaj la apostoloj kolektiĝis al Jesuo, kaj rakontis al li ĉion, kion ili faris kaj instruis."],[6,31,"Kaj li diris al ili: Venu mem aparte en dezertan lokon, kaj iom ripozu. Ĉar estis multaj venantaj kaj irantaj, kaj ili ne havis oportunon eĉ por manĝi.","Kaj li diris al ili: Venu mem aparte en dezertan lokon, kaj iom ripozu. Ĉar estis multaj venantaj kaj irantaj, kaj ili ne havis oportunon eĉ por manĝi."],[6,32,"Kaj ili foriris en la ŝipeto al dezerta loko aparte.","Kaj ili foriris en la ŝipeto al dezerta loko aparte."],[6,33,"Kaj oni vidis ilin forirantajn, kaj multaj rekonis ilin, kaj piede oni kuris tien el ĉiuj urboj kaj antaŭvenis ilin.","Kaj oni vidis ilin forirantajn, kaj multaj rekonis ilin, kaj piede oni kuris tien el ĉiuj urboj kaj antaŭvenis ilin."],[6,34,"Kaj li elvenis, kaj vidis grandan homamason, kaj li kortuŝiĝis pri ili, ĉar ili estis kiel ŝafoj ne havantaj paŝtiston; kaj li komencis instrui al ili multon.","Kaj li elvenis, kaj vidis grandan homamason, kaj li kortuŝiĝis pri ili, ĉar ili estis kiel ŝafoj ne havantaj paŝtiston; kaj li komencis instrui al ili multon."],[6,35,"Kaj kiam la horo jam estis malfrua, liaj disĉiploj venis al li, kaj diris: La loko estas dezerta, kaj la horo estas jam malfrua;","Kaj kiam la horo jam estis malfrua, liaj disĉiploj venis al li, kaj diris: La loko estas dezerta, kaj la horo estas jam malfrua;"],[6,36,"forsendu ilin, por ke ili iru en la ĉirkaŭajn kampojn kaj vilaĝojn kaj aĉetu por si manĝaĵon.","forsendu ilin, por ke ili iru en la ĉirkaŭajn kampojn kaj vilaĝojn kaj aĉetu por si manĝaĵon."],[6,37,"Sed li responde diris al ili: Vi donu al ili manĝi. Kaj ili diris al li: Ĉu ni iru kaj aĉetu panojn por ducent denaroj, kaj donu al ili manĝi?","Sed li responde diris al ili: Vi donu al ili manĝi. Kaj ili diris al li: Ĉu ni iru kaj aĉetu panojn por ducent denaroj, kaj donu al ili manĝi?"],[6,38,"Kaj li diris al ili: Kiom da panoj vi havas? iru, por vidi. Kaj sciiĝinte, ili diris: Kvin, kaj du fiŝojn.","Kaj li diris al ili: Kiom da panoj vi havas? iru, por vidi. Kaj sciiĝinte, ili diris: Kvin, kaj du fiŝojn."],[6,39,"Kaj li ordonis al ili, ke ĉiuj sidiĝu laŭgrupe sur la verda herbo.","Kaj li ordonis al ili, ke ĉiuj sidiĝu laŭgrupe sur la verda herbo."],[6,40,"Kaj ili sidiĝis en aroj, centope kaj kvindekope.","Kaj ili sidiĝis en aroj, centope kaj kvindekope."],[6,41,"Kaj li prenis la kvin panojn kaj la du fiŝojn, kaj suprenrigardinte al la ĉielo, li benis kaj dispecigis la panojn, kaj donis al la disĉiploj, por meti antaŭ ilin; kaj li dividis la du fiŝojn inter ĉiuj.","Kaj li prenis la kvin panojn kaj la du fiŝojn, kaj suprenrigardinte al la ĉielo, li benis kaj dispecigis la panojn, kaj donis al la disĉiploj, por meti antaŭ ilin; kaj li dividis la du fiŝojn inter ĉiuj."],[6,42,"Kaj ĉiuj manĝis kaj satiĝis.","Kaj ĉiuj manĝis kaj satiĝis."],[6,43,"Kaj oni kolektis da fragmentoj dek du korbojn, kaj ankaŭ el la fiŝoj.","Kaj oni kolektis da fragmentoj dek du korbojn, kaj ankaŭ el la fiŝoj."],[6,44,"Kaj tiuj, kiuj manĝis la panojn, estis kvin mil viroj.","Kaj tiuj, kiuj manĝis la panojn, estis kvin mil viroj."],[6,45,"Kaj tuj li devigis siajn disĉiplojn eniri en la ŝipeton kaj iri antaŭ li al la alia bordo, al Betsaida, dum li forsendos la homamason.","Kaj tuj li devigis siajn disĉiplojn eniri en la ŝipeton kaj iri antaŭ li al la alia bordo, al Betsaida, dum li forsendos la homamason."],[6,46,"Kaj adiaŭinte ilin, li foriris sur la monton, por preĝi.","Kaj adiaŭinte ilin, li foriris sur la monton, por preĝi."],[6,47,"Kaj kiam vesperiĝis, la ŝipeto estis meze de la maro, kaj li sola sur la tero.","Kaj kiam vesperiĝis, la ŝipeto estis meze de la maro, kaj li sola sur la tero."],[6,48,"Kaj vidante ilin laborantaj en malfacila remado, ĉar la vento estis kontraŭa al ili, ĉirkaŭ la kvara gardoparto de la nokto li venis al ili, irante sur la maro, kaj li volis preterpasi ilin;","Kaj vidante ilin laborantaj en malfacila remado, ĉar la vento estis kontraŭa al ili, ĉirkaŭ la kvara gardoparto de la nokto li venis al ili, irante sur la maro, kaj li volis preterpasi ilin;"],[6,49,"sed ili, vidante lin iranta sur la maro, supozis, ke ĝi estas fantomo, kaj ili ekkriis;","sed ili, vidante lin iranta sur la maro, supozis, ke ĝi estas fantomo, kaj ili ekkriis;"],[6,50,"ĉar ĉiuj vidis lin kaj maltrankviliĝis. Sed li tuj parolis kun ili, kaj diris al ili: Kuraĝu; ĝi estas mi; ne timu.","ĉar ĉiuj vidis lin kaj maltrankviliĝis. Sed li tuj parolis kun ili, kaj diris al ili: Kuraĝu; ĝi estas mi; ne timu."],[6,51,"Kaj li supreniris al ili en la ŝipeton, kaj la vento ĉesiĝis; kaj ili sentis grandan miregon;","Kaj li supreniris al ili en la ŝipeton, kaj la vento ĉesiĝis; kaj ili sentis grandan miregon;"],[6,52,"ĉar ili ne komprenis pri la panoj, ĉar ilia koro estis sensenta.","ĉar ili ne komprenis pri la panoj, ĉar ilia koro estis sensenta."],[6,53,"Kaj transirinte, ili alvenis teren ĉe Genesaret, kaj alligis la ŝipeton.","Kaj transirinte, ili alvenis teren ĉe Genesaret, kaj alligis la ŝipeton."],[6,54,"Kaj kiam ili estis elŝipiĝintaj, tuj oni rekonis lin,","Kaj kiam ili estis elŝipiĝintaj, tuj oni rekonis lin,"],[6,55,"kaj kuris tra tiu tuta regiono, kaj komencis ĉirkaŭporti la malsanulojn sur iliaj litoj tien, kie ili aŭdis, ke li estas.","kaj kuris tra tiu tuta regiono, kaj komencis ĉirkaŭporti la malsanulojn sur iliaj litoj tien, kie ili aŭdis, ke li estas."],[6,56,"Kaj kien ajn li eniris, en vilaĝojn aŭ en urbojn aŭ sur la kamparon, ili demetis la malsanulojn sur la placoj, kaj petegis lin, ke ili tuŝu nur la randon de lia vesto; kaj ĉiuj, kiuj tuŝis, resaniĝis.","Kaj kien ajn li eniris, en vilaĝojn aŭ en urbojn aŭ sur la kamparon, ili demetis la malsanulojn sur la placoj, kaj petegis lin, ke ili tuŝu nur la randon de lia vesto; kaj ĉiuj, kiuj tuŝis, resaniĝis."],[7,1,"Kaj kolektiĝis al li la Fariseoj kaj iuj el la skribistoj, kiuj venis el Jerusalem,","Kaj kolektiĝis al li la Fariseoj kaj iuj el la skribistoj, kiuj venis el Jerusalem,"],[7,2,"kaj jam vidis, ke kelkaj el liaj disĉiploj manĝas panon kun manoj profanaj, tio estas nelavitaj.","kaj jam vidis, ke kelkaj el liaj disĉiploj manĝas panon kun manoj profanaj, tio estas nelavitaj."],[7,3,"Kaj la Fariseoj kaj ĉiuj Judoj, se ili ne lavis zorge la manojn, ne manĝas, tenante la tradicion de la antaŭuloj;","Kaj la Fariseoj kaj ĉiuj Judoj, se ili ne lavis zorge la manojn, ne manĝas, tenante la tradicion de la antaŭuloj;"],[7,4,"kaj veninte el komercejo, ili ne manĝas, ne sin lavinte; kaj estas multaj aliaj aferoj, kiujn ili ricevis por observi, trempon de pokaloj kaj mezurpotoj kaj kupraj vazoj.","kaj veninte el komercejo, ili ne manĝas, ne sin lavinte; kaj estas multaj aliaj aferoj, kiujn ili ricevis por observi, trempon de pokaloj kaj mezurpotoj kaj kupraj vazoj."],[7,5,"Kaj lin demandis la Fariseoj kaj la skribistoj: Kial ne faras viaj disĉiploj laŭ la tradicio de la antaŭuloj, sed manĝas panon kun manoj profanaj?","Kaj lin demandis la Fariseoj kaj la skribistoj: Kial ne faras viaj disĉiploj laŭ la tradicio de la antaŭuloj, sed manĝas panon kun manoj profanaj?"],[7,6,"Kaj li diris al ili: Bone profetis Jesaja pri vi hipokrituloj, kiel estas skribite: Ĉi tiu popolo honoras Min per siaj lipoj, Sed ilia koro estas malproksime de Mi.","Kaj li diris al ili: Bone profetis Jesaja pri vi hipokrituloj, kiel estas skribite: Ĉi tiu popolo honoras Min per siaj lipoj, Sed ilia koro estas malproksime de Mi."],[7,7,"Sed vane ili Min adoras, Instruante kiel doktrinojn ordonojn de homoj.","Sed vane ili Min adoras, Instruante kiel doktrinojn ordonojn de homoj."],[7,8,"Ĉar, forlasinte la ordonon de Dio, vi tenas la tradicion de homoj.","Ĉar, forlasinte la ordonon de Dio, vi tenas la tradicion de homoj."],[7,9,"Kaj li diris al ili: Efektive vi forrifuzas la ordonon de Dio, por observi vian tradicion.","Kaj li diris al ili: Efektive vi forrifuzas la ordonon de Dio, por observi vian tradicion."],[7,10,"Ĉar Moseo diris: Respektu vian patron kaj vian patrinon; kaj: Kiu malbenas sian patron aŭ sian patrinon, tiu nepre mortu.","Ĉar Moseo diris: Respektu vian patron kaj vian patrinon; kaj: Kiu malbenas sian patron aŭ sian patrinon, tiu nepre mortu."],[7,11,"Sed vi diras: Se iu diros al sia patro aŭ sia patrino: Korban, tio estas Oferdono, estu tio, per kio vi povus profiti de mi,","Sed vi diras: Se iu diros al sia patro aŭ sia patrino: Korban, tio estas Oferdono, estu tio, per kio vi povus profiti de mi,"],[7,12,"vi jam ne permesas al li fari ion por sia patro aŭ sia patrino;","vi jam ne permesas al li fari ion por sia patro aŭ sia patrino;"],[7,13,"vantigante la vorton de Dio per via tradicio, kiun vi transdonis; kaj multajn tiajn aferojn vi faras.","vantigante la vorton de Dio per via tradicio, kiun vi transdonis; kaj multajn tiajn aferojn vi faras."],[7,14,"Kaj denove alvokinte la homamason, li diris al ili: Ĉiuj min aŭskultu kaj komprenu:","Kaj denove alvokinte la homamason, li diris al ili: Ĉiuj min aŭskultu kaj komprenu:"],[7,15,"ekzistas nenio, kio, enirante en homon de ekstere, povas lin profani; sed kio eliras el homo, tio profanas la homon.","ekzistas nenio, kio, enirante en homon de ekstere, povas lin profani; sed kio eliras el homo, tio profanas la homon."],[7,16,"Kiu havas orelojn por aŭdi, tiu aŭdu.","Kiu havas orelojn por aŭdi, tiu aŭdu."],[7,17,"Kaj kiam li eniris en domon for de la homamaso, liaj disĉiploj demandis lin pri la parabolo.","Kaj kiam li eniris en domon for de la homamaso, liaj disĉiploj demandis lin pri la parabolo."],[7,18,"Kaj li diris al ili: Ĉu vi ankaŭ estas tiel sen kompreno? Ĉu vi ne konscias, ke ĉio, eniranta de ekstere en homon, ne povas profani lin;","Kaj li diris al ili: Ĉu vi ankaŭ estas tiel sen kompreno? Ĉu vi ne konscias, ke ĉio, eniranta de ekstere en homon, ne povas profani lin;"],[7,19,"ĉar ĝi eniras ne en lian koron, sed en la ventron, kaj eliras en apartan lokon? Tion li diris, indigante ĉiajn manĝaĵojn.","ĉar ĝi eniras ne en lian koron, sed en la ventron, kaj eliras en apartan lokon? Tion li diris, indigante ĉiajn manĝaĵojn."],[7,20,"Kaj li diris: Kio elvenas el homo, tio profanas la homon.","Kaj li diris: Kio elvenas el homo, tio profanas la homon."],[7,21,"Ĉar de interne, el la koro de homoj, eliras malvirtaj pensoj, malĉastaĵoj,","Ĉar de interne, el la koro de homoj, eliras malvirtaj pensoj, malĉastaĵoj,"],[7,22,"ŝteloj, mortigoj, adultoj, avideco, malindaĵoj, ruzeco, voluptoj, malica okulo, blasfemo, aroganteco, malsaĝeco;","ŝteloj, mortigoj, adultoj, avideco, malindaĵoj, ruzeco, voluptoj, malica okulo, blasfemo, aroganteco, malsaĝeco;"],[7,23,"ĉiuj tiuj malbonoj elvenas de interne kaj profanas la homon.","ĉiuj tiuj malbonoj elvenas de interne kaj profanas la homon."],[7,24,"Kaj irinte de tie, li venis en la limojn de Tiro kaj Cidon. Kaj enirinte en domon, li volis, ke neniu sciu; sed li ne povis esti kaŝita.","Kaj irinte de tie, li venis en la limojn de Tiro kaj Cidon. Kaj enirinte en domon, li volis, ke neniu sciu; sed li ne povis esti kaŝita."],[7,25,"Sed aŭdinte pri li, iu virino, kies filineto havis malpuran spiriton, venis kaj falis antaŭ liaj piedoj.","Sed aŭdinte pri li, iu virino, kies filineto havis malpuran spiriton, venis kaj falis antaŭ liaj piedoj."],[7,26,"Kaj la virino estis Grekino, rase Sirofenika. Kaj ŝi petis lin, ke li elpelu la demonon el ŝia filino.","Kaj la virino estis Grekino, rase Sirofenika. Kaj ŝi petis lin, ke li elpelu la demonon el ŝia filino."],[7,27,"Kaj li diris al ŝi: Lasu unue satigi la infanojn, ĉar ne decas preni la panon de la infanoj kaj ĵeti ĝin al la hundetoj.","Kaj li diris al ŝi: Lasu unue satigi la infanojn, ĉar ne decas preni la panon de la infanoj kaj ĵeti ĝin al la hundetoj."],[7,28,"Sed ŝi respondis kaj diris al li: Jes, Sinjoro; ĉar eĉ la hundetoj sub la tablo manĝas el la panpecetoj de la infanoj.","Sed ŝi respondis kaj diris al li: Jes, Sinjoro; ĉar eĉ la hundetoj sub la tablo manĝas el la panpecetoj de la infanoj."],[7,29,"Kaj li diris al ŝi: Pro ĉi tiu vorto iru vian vojon; la demono eliris el via filino.","Kaj li diris al ŝi: Pro ĉi tiu vorto iru vian vojon; la demono eliris el via filino."],[7,30,"Kaj kiam ŝi iris en sian domon, ŝi trovis la infaninon kuŝigita sur la lito, kaj la demonon foririnta.","Kaj kiam ŝi iris en sian domon, ŝi trovis la infaninon kuŝigita sur la lito, kaj la demonon foririnta."],[7,31,"Kaj denove foririnte el la limoj de Tiro, li venis tra Cidon al la Galilea Maro, tra la mezo de la limoj de Dekapolis.","Kaj denove foririnte el la limoj de Tiro, li venis tra Cidon al la Galilea Maro, tra la mezo de la limoj de Dekapolis."],[7,32,"Kaj oni kondukis al li viron surdan kaj apenaŭ parolkapablan, kaj petis lin, ke li metu sian manon sur lin.","Kaj oni kondukis al li viron surdan kaj apenaŭ parolkapablan, kaj petis lin, ke li metu sian manon sur lin."],[7,33,"Kaj kondukinte lin el la homamaso en apartan lokon, li metis siajn fingrojn en liajn orelojn, kaj kraĉinte, li tuŝis lian langon;","Kaj kondukinte lin el la homamaso en apartan lokon, li metis siajn fingrojn en liajn orelojn, kaj kraĉinte, li tuŝis lian langon;"],[7,34,"kaj suprenrigardinte al la ĉielo, li ĝemis, kaj diris al li: Efata, tio estas: Malfermiĝu.","kaj suprenrigardinte al la ĉielo, li ĝemis, kaj diris al li: Efata, tio estas: Malfermiĝu."],[7,35,"Kaj liaj oreloj malfermiĝis, kaj la ligilo de lia lango malstreĉiĝis, kaj li parolis klare.","Kaj liaj oreloj malfermiĝis, kaj la ligilo de lia lango malstreĉiĝis, kaj li parolis klare."],[7,36,"Kaj li admonis ilin, ke oni diru tion al neniu; sed ju pli li malpermesis, des pli multe ili ĉie sciigis ĝin.","Kaj li admonis ilin, ke oni diru tion al neniu; sed ju pli li malpermesis, des pli multe ili ĉie sciigis ĝin."],[7,37,"Kaj supermezure ili miregis, dirante: Li faris ĉion bone; li igas la surdulojn aŭdi, kaj la mutulojn paroli.","Kaj supermezure ili miregis, dirante: Li faris ĉion bone; li igas la surdulojn aŭdi, kaj la mutulojn paroli."],[8,1,"En tiuj tagoj, kiam denove estis granda homamaso, kaj ili nenion havis manĝi, li alvokis al si siajn disĉiplojn, kaj diris al ili:","En tiuj tagoj, kiam denove estis granda homamaso, kaj ili nenion havis manĝi, li alvokis al si siajn disĉiplojn, kaj diris al ili:"],[8,2,"Mi kortuŝiĝas pro la homamaso, ĉar jam tri tagojn ili restas ĉe mi kaj nenion havas manĝi;","Mi kortuŝiĝas pro la homamaso, ĉar jam tri tagojn ili restas ĉe mi kaj nenion havas manĝi;"],[8,3,"kaj se mi forsendos ilin fastantaj al iliaj domoj, ili laciĝos sur la vojo; kaj iuj el ili venis de malproksime.","kaj se mi forsendos ilin fastantaj al iliaj domoj, ili laciĝos sur la vojo; kaj iuj el ili venis de malproksime."],[8,4,"Kaj liaj disĉiploj respondis al li: De kie oni povos satigi ĉi tiujn homojn per panoj ĉi tie en dezerto?","Kaj liaj disĉiploj respondis al li: De kie oni povos satigi ĉi tiujn homojn per panoj ĉi tie en dezerto?"],[8,5,"Kaj li demandis ilin: Kiom da panoj vi havas? Kaj ili diris: Sep.","Kaj li demandis ilin: Kiom da panoj vi havas? Kaj ili diris: Sep."],[8,6,"Kaj li ordonis al la homamaso sidiĝi sur la tero; kaj li prenis la sep panojn, kaj doninte dankon, li dispecigis ilin, kaj donis al la disĉiploj por disdoni; kaj ili disdonis al la homamaso.","Kaj li ordonis al la homamaso sidiĝi sur la tero; kaj li prenis la sep panojn, kaj doninte dankon, li dispecigis ilin, kaj donis al la disĉiploj por disdoni; kaj ili disdonis al la homamaso."],[8,7,"Kaj ili havis kelkajn malgrandajn fiŝojn; kaj beninte ilin, li ordonis disdoni ilin ankaŭ.","Kaj ili havis kelkajn malgrandajn fiŝojn; kaj beninte ilin, li ordonis disdoni ilin ankaŭ."],[8,8,"Kaj ili manĝis kaj satiĝis; kaj oni kolektis da postrestintaj fragmentoj sep korbegojn.","Kaj ili manĝis kaj satiĝis; kaj oni kolektis da postrestintaj fragmentoj sep korbegojn."],[8,9,"Kaj ili estis proksimume kvar mil, kaj li forsendis ilin.","Kaj ili estis proksimume kvar mil, kaj li forsendis ilin."],[8,10,"Kaj tuj enirinte en la ŝipeton kun siaj disĉiploj, li iris al la regiono Dalmanuta.","Kaj tuj enirinte en la ŝipeton kun siaj disĉiploj, li iris al la regiono Dalmanuta."],[8,11,"Kaj alvenis la Fariseoj, kaj komencis diskuti kun li, serĉante ĉe li signon el la ĉielo, por provi lin.","Kaj alvenis la Fariseoj, kaj komencis diskuti kun li, serĉante ĉe li signon el la ĉielo, por provi lin."],[8,12,"Kaj forte ĝeminte en sia spirito, li diris: Kial ĉi tiu generacio serĉas signon? vere, mi diras al vi: Nenia signo estos donita al ĉi tiu generacio.","Kaj forte ĝeminte en sia spirito, li diris: Kial ĉi tiu generacio serĉas signon? vere, mi diras al vi: Nenia signo estos donita al ĉi tiu generacio."],[8,13,"Kaj forlasinte ilin, li denove enŝipiĝis kaj transiris al la alia bordo.","Kaj forlasinte ilin, li denove enŝipiĝis kaj transiris al la alia bordo."],[8,14,"Kaj ili forgesis preni panojn; kaj nur unu panon ili havis kun si en la ŝipeto.","Kaj ili forgesis preni panojn; kaj nur unu panon ili havis kun si en la ŝipeto."],[8,15,"Kaj li admonis ilin, dirante: Zorgu, gardu vin kontraŭ la fermentaĵo de la Fariseoj kaj la fermentaĵo de Herodo.","Kaj li admonis ilin, dirante: Zorgu, gardu vin kontraŭ la fermentaĵo de la Fariseoj kaj la fermentaĵo de Herodo."],[8,16,"Kaj ili diskutis unu kun la alia, dirante: Ĉar ni ne havas panojn.","Kaj ili diskutis unu kun la alia, dirante: Ĉar ni ne havas panojn."],[8,17,"Kaj Jesuo, eksciante tion, diris al ili: Kial vi diskutas pro tio, ke vi ne havas panon? ĉu vi ankoraŭ ne konscias nek komprenas? ĉu via koro estas obstinigita?","Kaj Jesuo, eksciante tion, diris al ili: Kial vi diskutas pro tio, ke vi ne havas panon? ĉu vi ankoraŭ ne konscias nek komprenas? ĉu via koro estas obstinigita?"],[8,18,"Okulojn havante, ĉu vi ne vidas? kaj orelojn havante, ĉu vi ne aŭdas? kaj ĉu vi ne memoras?","Okulojn havante, ĉu vi ne vidas? kaj orelojn havante, ĉu vi ne aŭdas? kaj ĉu vi ne memoras?"],[8,19,"Kiam mi dispecigis la kvin panojn por la kvin mil, kiom da korboj da fragmentoj vi kolektis? Ili respondis al li: Dek du.","Kiam mi dispecigis la kvin panojn por la kvin mil, kiom da korboj da fragmentoj vi kolektis? Ili respondis al li: Dek du."],[8,20,"Kaj kiam la sep por la kvar mil, kiom da korbegoj da fragmentoj vi kolektis? Kaj ili respondis al li: Sep.","Kaj kiam la sep por la kvar mil, kiom da korbegoj da fragmentoj vi kolektis? Kaj ili respondis al li: Sep."],[8,21,"Kaj li diris al ili: Ĉu vi ankoraŭ ne komprenas?","Kaj li diris al ili: Ĉu vi ankoraŭ ne komprenas?"],[8,22,"Kaj ili alvenis al Betsaida. Kaj oni alkondukis al li blindulon, kaj petegis, ke li tuŝu lin.","Kaj ili alvenis al Betsaida. Kaj oni alkondukis al li blindulon, kaj petegis, ke li tuŝu lin."],[8,23,"Kaj preninte la manon de la blindulo, li elkondukis lin ekster la vilaĝon; kaj kraĉinte sur liajn okulojn, kaj surmetinte la manojn sur lin, li demandis lin: Ĉu vi vidas ion?","Kaj preninte la manon de la blindulo, li elkondukis lin ekster la vilaĝon; kaj kraĉinte sur liajn okulojn, kaj surmetinte la manojn sur lin, li demandis lin: Ĉu vi vidas ion?"],[8,24,"Kaj li ekrigardis, kaj diris: Mi vidas homojn, ĉar mi vidas kvazaŭ arbojn irantajn.","Kaj li ekrigardis, kaj diris: Mi vidas homojn, ĉar mi vidas kvazaŭ arbojn irantajn."],[8,25,"Tiam denove li metis la manojn sur liajn okulojn; kaj li fikse rigardis, kaj resaniĝis, kaj vidis ĉion klare.","Tiam denove li metis la manojn sur liajn okulojn; kaj li fikse rigardis, kaj resaniĝis, kaj vidis ĉion klare."],[8,26,"Kaj li forsendis lin al lia domo, dirante: Nepre ne eniru en la vilaĝon.","Kaj li forsendis lin al lia domo, dirante: Nepre ne eniru en la vilaĝon."],[8,27,"Kaj eliris Jesuo kaj liaj disĉiploj en la vilaĝojn de Cezarea Filipi; kaj sur la vojo li demandis siajn disĉiplojn, dirante al ili: Kiu, diras la homoj, ke mi estas?","Kaj eliris Jesuo kaj liaj disĉiploj en la vilaĝojn de Cezarea Filipi; kaj sur la vojo li demandis siajn disĉiplojn, dirante al ili: Kiu, diras la homoj, ke mi estas?"],[8,28,"Kaj ili respondis al li: Johano, la Baptisto; laŭ aliaj: Elija; kaj laŭ aliaj: Unu el la profetoj.","Kaj ili respondis al li: Johano, la Baptisto; laŭ aliaj: Elija; kaj laŭ aliaj: Unu el la profetoj."],[8,29,"Kaj li demandis ilin: Sed vi — kiu vi diras, ke mi estas? Petro responde diris al li: Vi estas la Kristo.","Kaj li demandis ilin: Sed vi — kiu vi diras, ke mi estas? Petro responde diris al li: Vi estas la Kristo."],[8,30,"Kaj li admonis ilin, ke ili diru al neniu pri li.","Kaj li admonis ilin, ke ili diru al neniu pri li."],[8,31,"Kaj li komencis instrui al ili, ke la Filo de homo devas multe suferi, kaj esti rifuzita de la pliaĝuloj kaj la ĉefpastroj kaj la skribistoj, kaj esti mortigita, kaj post tri tagoj releviĝi.","Kaj li komencis instrui al ili, ke la Filo de homo devas multe suferi, kaj esti rifuzita de la pliaĝuloj kaj la ĉefpastroj kaj la skribistoj, kaj esti mortigita, kaj post tri tagoj releviĝi."],[8,32,"Kaj li parolis tiun diron malkaŝe. Kaj Petro prenis lin, kaj komencis admoni lin.","Kaj li parolis tiun diron malkaŝe. Kaj Petro prenis lin, kaj komencis admoni lin."],[8,33,"Sed turninte sin kaj rigardante la disĉiplojn, li admonis Petron, dirante: Iru malantaŭ min, Satano, ĉar vi havas pensojn ne laŭ Dio, sed laŭ homoj.","Sed turninte sin kaj rigardante la disĉiplojn, li admonis Petron, dirante: Iru malantaŭ min, Satano, ĉar vi havas pensojn ne laŭ Dio, sed laŭ homoj."],[8,34,"Kaj alvokinte al si la homamason kun siaj disĉiploj, li diris al ili: Se iu volas veni post mi, li abnegaciu sin, kaj levu sian krucon, kaj sekvu min.","Kaj alvokinte al si la homamason kun siaj disĉiploj, li diris al ili: Se iu volas veni post mi, li abnegaciu sin, kaj levu sian krucon, kaj sekvu min."],[8,35,"Ĉar kiu volos savi sian animon, tiu ĝin perdos; kaj kiu perdos sian animon pro mi kaj pro la evangelio, tiu ĝin savos.","Ĉar kiu volos savi sian animon, tiu ĝin perdos; kaj kiu perdos sian animon pro mi kaj pro la evangelio, tiu ĝin savos."],[8,36,"Ĉar kiel profitus homo, se li gajnus la tutan mondon kaj perdus sian animon?","Ĉar kiel profitus homo, se li gajnus la tutan mondon kaj perdus sian animon?"],[8,37,"Ĉar kion homo donu interŝanĝe por sia animo?","Ĉar kion homo donu interŝanĝe por sia animo?"],[8,38,"Ĉar kiu hontos pri mi kaj miaj paroloj antaŭ ĉi tiu adultema kaj peka generacio, pri tiu ankaŭ hontos la Filo de homo, kiam li venos en la gloro de sia Patro kun la sanktaj anĝeloj.","Ĉar kiu hontos pri mi kaj miaj paroloj antaŭ ĉi tiu adultema kaj peka generacio, pri tiu ankaŭ hontos la Filo de homo, kiam li venos en la gloro de sia Patro kun la sanktaj anĝeloj."],[9,1,"Kaj li diris al ili: Vere mi diras al vi: Inter la ĉi tie starantaj estas iuj, kiuj neniel gustumos morton, antaŭ ol ili vidos la regnon de Dio venintan en potenco.","Kaj li diris al ili: Vere mi diras al vi: Inter la ĉi tie starantaj estas iuj, kiuj neniel gustumos morton, antaŭ ol ili vidos la regnon de Dio venintan en potenco."],[9,2,"Kaj post ses tagoj Jesuo prenis kun si Petron kaj Jakobon kaj Johanon, kaj kondukis ilin solajn sur altan monton aparte; kaj li estis aliformita antaŭ ili;","Kaj post ses tagoj Jesuo prenis kun si Petron kaj Jakobon kaj Johanon, kaj kondukis ilin solajn sur altan monton aparte; kaj li estis aliformita antaŭ ili;"],[9,3,"kaj liaj vestoj fariĝis brilantaj, treege blankaj, kiel fulisto sur la tero ne povas blankigi.","kaj liaj vestoj fariĝis brilantaj, treege blankaj, kiel fulisto sur la tero ne povas blankigi."],[9,4,"Kaj aperis al ili Elija kun Moseo, kaj ili interparoladis kun Jesuo.","Kaj aperis al ili Elija kun Moseo, kaj ili interparoladis kun Jesuo."],[9,5,"Kaj Petro responde diris al Jesuo: Rabeno, estas bone por ni esti ĉi tie; kaj ni faru tri laŭbojn: unu por vi, kaj unu por Moseo, kaj unu por Elija.","Kaj Petro responde diris al Jesuo: Rabeno, estas bone por ni esti ĉi tie; kaj ni faru tri laŭbojn: unu por vi, kaj unu por Moseo, kaj unu por Elija."],[9,6,"Ĉar li ne sciis, kion respondi, ĉar ili tre timiĝis.","Ĉar li ne sciis, kion respondi, ĉar ili tre timiĝis."],[9,7,"Kaj nubo superombris ilin; kaj elvenis voĉo el la nubo: Ĉi tiu estas Mia Filo, la amata; aŭskultu lin.","Kaj nubo superombris ilin; kaj elvenis voĉo el la nubo: Ĉi tiu estas Mia Filo, la amata; aŭskultu lin."],[9,8,"Kaj subite, ĉirkaŭrigardinte, ili jam vidis neniun krom Jesuo sola.","Kaj subite, ĉirkaŭrigardinte, ili jam vidis neniun krom Jesuo sola."],[9,9,"Kaj dum ili malsupreniris de la monto, li admonis ilin, ke al neniu ili rakontu tion, kion ili vidis, ĝis la Filo de homo releviĝos el la mortintoj.","Kaj dum ili malsupreniris de la monto, li admonis ilin, ke al neniu ili rakontu tion, kion ili vidis, ĝis la Filo de homo releviĝos el la mortintoj."],[9,10,"Kaj ili konservis la diron, demandante inter si, kion signifas la releviĝo el la mortintoj.","Kaj ili konservis la diron, demandante inter si, kion signifas la releviĝo el la mortintoj."],[9,11,"Kaj ili demandis lin, dirante: Kial diras la skribistoj, ke Elija devas veni antaŭe?","Kaj ili demandis lin, dirante: Kial diras la skribistoj, ke Elija devas veni antaŭe?"],[9,12,"Kaj li diris al ili: Vere Elija venas antaŭe, kaj restarigas ĉion; kaj kiel estas skribite pri la Filo de homo, ke li devas multe suferi kaj esti malestimata?","Kaj li diris al ili: Vere Elija venas antaŭe, kaj restarigas ĉion; kaj kiel estas skribite pri la Filo de homo, ke li devas multe suferi kaj esti malestimata?"],[9,13,"Sed mi diras al vi, ke Elija jam venis, kaj oni faris al li ĉion, kion ili volis, kiel estas skribite pri li.","Sed mi diras al vi, ke Elija jam venis, kaj oni faris al li ĉion, kion ili volis, kiel estas skribite pri li."],[9,14,"Kaj veninte al la disĉiploj, ili vidis grandan homamason ĉirkaŭ ili, kaj skribistojn diskutantajn kun ili.","Kaj veninte al la disĉiploj, ili vidis grandan homamason ĉirkaŭ ili, kaj skribistojn diskutantajn kun ili."],[9,15,"Kaj tuj la homamaso, vidante lin, forte miris, kaj alkuris, kaj salutis lin.","Kaj tuj la homamaso, vidante lin, forte miris, kaj alkuris, kaj salutis lin."],[9,16,"Kaj li demandis ilin: Pri kio vi diskutas kun ili?","Kaj li demandis ilin: Pri kio vi diskutas kun ili?"],[9,17,"Kaj unu el la amaso respondis al li: Majstro, mi venigis al vi mian filon, kiu havas mutan spiriton;","Kaj unu el la amaso respondis al li: Majstro, mi venigis al vi mian filon, kiu havas mutan spiriton;"],[9,18,"kaj kie ajn ĝi kaptas lin, ĝi ŝiras lin, kaj li ŝaŭmas kaj grincigas la dentojn kaj kadukiĝas; kaj mi parolis al viaj disĉiploj, ke ili elpelu ĝin; kaj ili ne povis.","kaj kie ajn ĝi kaptas lin, ĝi ŝiras lin, kaj li ŝaŭmas kaj grincigas la dentojn kaj kadukiĝas; kaj mi parolis al viaj disĉiploj, ke ili elpelu ĝin; kaj ili ne povis."],[9,19,"Kaj li respondis al ili, dirante: Ho senfida generacio, ĝis kiam mi estos kun vi? ĝis kiam mi toleros vin? venigu lin al mi.","Kaj li respondis al ili, dirante: Ho senfida generacio, ĝis kiam mi estos kun vi? ĝis kiam mi toleros vin? venigu lin al mi."],[9,20,"Kaj ili venigis lin al li; kaj vidinte lin, tuj la spirito konvulsiigis lin, kaj li falis teren kaj ruliĝis ŝaŭmanta.","Kaj ili venigis lin al li; kaj vidinte lin, tuj la spirito konvulsiigis lin, kaj li falis teren kaj ruliĝis ŝaŭmanta."],[9,21,"Kaj li demandis la patron: De kiom da tempo okazadas ĉi tio al li? Kaj li diris: De infaneco.","Kaj li demandis la patron: De kiom da tempo okazadas ĉi tio al li? Kaj li diris: De infaneco."],[9,22,"Kaj ofte ĝi ĵetis lin en fajron kaj en akvon, por pereigi lin; sed se vi povas fari ion, kompatu al ni kaj helpu nin.","Kaj ofte ĝi ĵetis lin en fajron kaj en akvon, por pereigi lin; sed se vi povas fari ion, kompatu al ni kaj helpu nin."],[9,23,"Kaj Jesuo diris al li: Kiel, se vi povas! Ĉio estas ebla por kredanto.","Kaj Jesuo diris al li: Kiel, se vi povas! Ĉio estas ebla por kredanto."],[9,24,"Tuj ekkriante, la patro de la infano diris: Mi kredas; helpu mian nekredemon.","Tuj ekkriante, la patro de la infano diris: Mi kredas; helpu mian nekredemon."],[9,25,"Kaj kiam Jesuo vidis, ke homamaso alkuras, li severe admonis la malpuran spiriton, dirante al ĝi: Vi muta kaj surda spirito, mi ordonas al vi: Eliru el li, kaj ne plu eniru en lin.","Kaj kiam Jesuo vidis, ke homamaso alkuras, li severe admonis la malpuran spiriton, dirante al ĝi: Vi muta kaj surda spirito, mi ordonas al vi: Eliru el li, kaj ne plu eniru en lin."],[9,26,"Kaj ekkriinte, kaj multe konvulsiiginte lin, ĝi eliris; kaj li fariĝis kvazaŭ mortinto, tiel ke la plimulto diris: Li mortis.","Kaj ekkriinte, kaj multe konvulsiiginte lin, ĝi eliris; kaj li fariĝis kvazaŭ mortinto, tiel ke la plimulto diris: Li mortis."],[9,27,"Sed Jesuo, preninte lin je la mano, levis lin; kaj li stariĝis.","Sed Jesuo, preninte lin je la mano, levis lin; kaj li stariĝis."],[9,28,"Kaj kiam li eniris en la domon, liaj disĉiploj aparte demandis lin: Kial ni ne povis elpeli ĝin?","Kaj kiam li eniris en la domon, liaj disĉiploj aparte demandis lin: Kial ni ne povis elpeli ĝin?"],[9,29,"Kaj li diris al ili: Ĉi tiu speco neniel povas eliri, krom per preĝado.","Kaj li diris al ili: Ĉi tiu speco neniel povas eliri, krom per preĝado."],[9,30,"Kaj foririnte, ili trapasis tra Galileo; kaj li deziris, ke neniu tion eksciu.","Kaj foririnte, ili trapasis tra Galileo; kaj li deziris, ke neniu tion eksciu."],[9,31,"Ĉar li instruadis siajn disĉiplojn, kaj diris al ili: La Filo de homo estas transdonita en la manojn de homoj, kaj ili mortigos lin; kaj, mortigite, li leviĝos post tri tagoj.","Ĉar li instruadis siajn disĉiplojn, kaj diris al ili: La Filo de homo estas transdonita en la manojn de homoj, kaj ili mortigos lin; kaj, mortigite, li leviĝos post tri tagoj."],[9,32,"Sed ili ne komprenis la diron, kaj timis demandi lin.","Sed ili ne komprenis la diron, kaj timis demandi lin."],[9,33,"Kaj ili venis al Kapernaum, kaj kiam li estis en la domo, li demandis ilin: Pri kio vi diskutis sur la vojo?","Kaj ili venis al Kapernaum, kaj kiam li estis en la domo, li demandis ilin: Pri kio vi diskutis sur la vojo?"],[9,34,"Sed ili silentis; ĉar ili diskutis inter si sur la vojo pri tio, kiu estas la plej granda.","Sed ili silentis; ĉar ili diskutis inter si sur la vojo pri tio, kiu estas la plej granda."],[9,35,"Kaj sidiĝinte, li alvokis la dek du, kaj diris al ili: Se iu volas esti unua, li estos lasta el ĉiuj, kaj servanto de ĉiuj.","Kaj sidiĝinte, li alvokis la dek du, kaj diris al ili: Se iu volas esti unua, li estos lasta el ĉiuj, kaj servanto de ĉiuj."],[9,36,"Kaj preninte infanon, li starigis ĝin meze de ili; kaj ĉirkaŭbrakinte ĝin, li diris al ili:","Kaj preninte infanon, li starigis ĝin meze de ili; kaj ĉirkaŭbrakinte ĝin, li diris al ili:"],[9,37,"Kiu akceptos unu el tiaj infanoj en mia nomo, tiu akceptas min; kaj kiu akceptas min, tiu akceptas ne min, sed Tiun, kiu sendis min.","Kiu akceptos unu el tiaj infanoj en mia nomo, tiu akceptas min; kaj kiu akceptas min, tiu akceptas ne min, sed Tiun, kiu sendis min."],[9,38,"Johano diris al li: Majstro, ni vidis iun elpelantan demonojn en via nomo; kaj ni malpermesis lin, ĉar li ne sekvas nin.","Johano diris al li: Majstro, ni vidis iun elpelantan demonojn en via nomo; kaj ni malpermesis lin, ĉar li ne sekvas nin."],[9,39,"Sed Jesuo diris: Ne malpermesu lin; ĉar neniu, kiu faros miraklon en mia nomo, povos facile paroli malbone pri mi.","Sed Jesuo diris: Ne malpermesu lin; ĉar neniu, kiu faros miraklon en mia nomo, povos facile paroli malbone pri mi."],[9,40,"Ĉar tiu, kiu ne estas kontraŭ ni, estas por ni.","Ĉar tiu, kiu ne estas kontraŭ ni, estas por ni."],[9,41,"Ĉar kiu donos al vi trinki tason da akvo, pro tio, ke vi apartenas al Kristo, vere mi diras al vi, tiu neniel perdos sian rekompencon.","Ĉar kiu donos al vi trinki tason da akvo, pro tio, ke vi apartenas al Kristo, vere mi diras al vi, tiu neniel perdos sian rekompencon."],[9,42,"Kaj kiu igos fali unu el ĉi tiuj malgranduloj, kiuj kredas al mi, estus pli bone por tiu, se granda muelŝtono estus pendigita ĉirkaŭ lia kolo, kaj se li estus ĵetita en la maron.","Kaj kiu igos fali unu el ĉi tiuj malgranduloj, kiuj kredas al mi, estus pli bone por tiu, se granda muelŝtono estus pendigita ĉirkaŭ lia kolo, kaj se li estus ĵetita en la maron."],[9,43,"Kaj se via mano faligas vin, detranĉu ĝin: estas bone por vi eniri en vivon kripla prefere ol, havante du manojn, eniri en Gehenan, en la neestingeblan fajron,","Kaj se via mano faligas vin, detranĉu ĝin: estas bone por vi eniri en vivon kripla prefere ol, havante du manojn, eniri en Gehenan, en la neestingeblan fajron,"],[9,44,"kie ilia vermo ne pereas kaj la fajro ne estingiĝas.","kie ilia vermo ne pereas kaj la fajro ne estingiĝas."],[9,45,"Kaj se via piedo faligas vin, detranĉu ĝin: estas bone por vi eniri en vivon lama prefere ol, havante du piedojn, esti ĵetita en Gehenan,","Kaj se via piedo faligas vin, detranĉu ĝin: estas bone por vi eniri en vivon lama prefere ol, havante du piedojn, esti ĵetita en Gehenan,"],[9,46,"kie ilia vermo ne pereas kaj la fajro ne estingiĝas.","kie ilia vermo ne pereas kaj la fajro ne estingiĝas."],[9,47,"Kaj se via okulo faligas vin, elŝiru ĝin: estas bone por vi eniri en la regnon de Dio kun unu okulo prefere ol, havante du okulojn, esti ĵetita en Gehenan,","Kaj se via okulo faligas vin, elŝiru ĝin: estas bone por vi eniri en la regnon de Dio kun unu okulo prefere ol, havante du okulojn, esti ĵetita en Gehenan,"],[9,48,"kie ilia vermo ne pereas kaj la fajro ne estingiĝas.","kie ilia vermo ne pereas kaj la fajro ne estingiĝas."],[9,49,"Ĉar ĉiu estos salita per fajro.","Ĉar ĉiu estos salita per fajro."],[9,50,"Salo estas bona; sed se la salo fariĝis nesala, kiel vi rebonigos ĝin? Havu salon en vi, kaj paciĝu unu kun alia.","Salo estas bona; sed se la salo fariĝis nesala, kiel vi rebonigos ĝin? Havu salon en vi, kaj paciĝu unu kun alia."],[10,1,"Kaj li foriris de tie, kaj venis en la limojn de Judujo kaj trans Jordanon; kaj homamasoj kunvenis denove al li, kaj laŭ sia kutimo li instruis ilin denove.","Kaj li foriris de tie, kaj venis en la limojn de Judujo kaj trans Jordanon; kaj homamasoj kunvenis denove al li, kaj laŭ sia kutimo li instruis ilin denove."],[10,2,"Kaj Fariseoj venis, kaj demandis lin, por provi lin: Ĉu estas permesate al viro forsendi sian edzinon?","Kaj Fariseoj venis, kaj demandis lin, por provi lin: Ĉu estas permesate al viro forsendi sian edzinon?"],[10,3,"Kaj li responde diris al ili: Kion Moseo ordonis al vi?","Kaj li responde diris al ili: Kion Moseo ordonis al vi?"],[10,4,"Kaj ili diris: Moseo permesis skribi eksedzigan leteron, kaj forsendi ŝin.","Kaj ili diris: Moseo permesis skribi eksedzigan leteron, kaj forsendi ŝin."],[10,5,"Sed Jesuo diris al ili: Pro la malmoleco de via koro li skribis por vi ĉi tiun ordonon.","Sed Jesuo diris al ili: Pro la malmoleco de via koro li skribis por vi ĉi tiun ordonon."],[10,6,"Sed de la komenco de la kreo: Li faris ilin vira kaj virina.","Sed de la komenco de la kreo: Li faris ilin vira kaj virina."],[10,7,"Tial viro forlasos sian patron kaj sian patrinon, kaj aliĝos al sia edzino,","Tial viro forlasos sian patron kaj sian patrinon, kaj aliĝos al sia edzino,"],[10,8,"kaj ili estos unu karno; sekve ili jam estas ne du, sed unu karno.","kaj ili estos unu karno; sekve ili jam estas ne du, sed unu karno."],[10,9,"Kion do Dio kunigis, tion homo ne disigu.","Kion do Dio kunigis, tion homo ne disigu."],[10,10,"Kaj en la domo la disĉiploj denove demandis lin pri la afero.","Kaj en la domo la disĉiploj denove demandis lin pri la afero."],[10,11,"Kaj li diris al ili: Kiu forsendos sian edzinon kaj edziĝos kun alia, tiu adultas kontraŭ ŝi;","Kaj li diris al ili: Kiu forsendos sian edzinon kaj edziĝos kun alia, tiu adultas kontraŭ ŝi;"],[10,12,"kaj se ŝi mem forsendos sian edzon kaj edziniĝos kun alia, ŝi adultas.","kaj se ŝi mem forsendos sian edzon kaj edziniĝos kun alia, ŝi adultas."],[10,13,"Kaj oni venigis al li infanojn, por ke li tuŝu ilin; kaj la disĉiploj admonis ilin.","Kaj oni venigis al li infanojn, por ke li tuŝu ilin; kaj la disĉiploj admonis ilin."],[10,14,"Sed Jesuo, vidinte tion, indignis, kaj diris al ili: Lasu la infanojn veni al mi; ne malhelpu ilin, ĉar el tiaj estas la regno de Dio.","Sed Jesuo, vidinte tion, indignis, kaj diris al ili: Lasu la infanojn veni al mi; ne malhelpu ilin, ĉar el tiaj estas la regno de Dio."],[10,15,"Vere mi diras al vi: Kiu ne akceptos la regnon de Dio kiel infano, tiu neniel eniros en ĝin.","Vere mi diras al vi: Kiu ne akceptos la regnon de Dio kiel infano, tiu neniel eniros en ĝin."],[10,16,"Kaj li prenis ilin en siaj brakoj, kaj benis ilin, metinte la manojn sur ilin.","Kaj li prenis ilin en siaj brakoj, kaj benis ilin, metinte la manojn sur ilin."],[10,17,"Kaj dum li foriris sur la vojo, unu homo kuris al li kaj genuis antaŭ li, kaj demandis lin: Bona Majstro, kion mi faru, por ke mi heredu eternan vivon?","Kaj dum li foriris sur la vojo, unu homo kuris al li kaj genuis antaŭ li, kaj demandis lin: Bona Majstro, kion mi faru, por ke mi heredu eternan vivon?"],[10,18,"Kaj Jesuo diris al li: Kial vi nomas min bona? neniu estas bona krom Unu, nome Dio.","Kaj Jesuo diris al li: Kial vi nomas min bona? neniu estas bona krom Unu, nome Dio."],[10,19,"Vi scias la ordonojn: Ne mortigu; Ne adultu; Ne ŝtelu; Ne parolu malveran ateston; Ne rabu; Respektu vian patron kaj vian patrinon.","Vi scias la ordonojn: Ne mortigu; Ne adultu; Ne ŝtelu; Ne parolu malveran ateston; Ne rabu; Respektu vian patron kaj vian patrinon."],[10,20,"Kaj li responde diris al li: Majstro, ĉion tion mi observis detempe de mia juneco.","Kaj li responde diris al li: Majstro, ĉion tion mi observis detempe de mia juneco."],[10,21,"Kaj Jesuo, rigardante lin, amis lin, kaj diris al li: Unu mankon vi havas; iru, kaj vendu ĉion, kion vi havas, kaj donu al malriĉuloj, kaj vi havos trezoron en la ĉielo; kaj venu, sekvu min.","Kaj Jesuo, rigardante lin, amis lin, kaj diris al li: Unu mankon vi havas; iru, kaj vendu ĉion, kion vi havas, kaj donu al malriĉuloj, kaj vi havos trezoron en la ĉielo; kaj venu, sekvu min."],[10,22,"Sed li malgajiĝis ĉe tiu vorto, kaj foriris malĝoja; ĉar li havis multajn posedaĵojn.","Sed li malgajiĝis ĉe tiu vorto, kaj foriris malĝoja; ĉar li havis multajn posedaĵojn."],[10,23,"Kaj Jesuo ĉirkaŭrigardis, kaj diris al siaj disĉiploj: Kiel malfacile tiuj, kiuj havas riĉon, eniros en la regnon de Dio!","Kaj Jesuo ĉirkaŭrigardis, kaj diris al siaj disĉiploj: Kiel malfacile tiuj, kiuj havas riĉon, eniros en la regnon de Dio!"],[10,24,"Kaj la disĉiploj miris pro liaj vortoj. Sed Jesuo, respondante denove, diris al ili: Infanoj, kiel malfacile estas por tiuj, kiuj fidas al la riĉo, eniri en la regnon de Dio!","Kaj la disĉiploj miris pro liaj vortoj. Sed Jesuo, respondante denove, diris al ili: Infanoj, kiel malfacile estas por tiuj, kiuj fidas al la riĉo, eniri en la regnon de Dio!"],[10,25,"Estas pli facile por kamelo iri tra trueton de kudrilo, ol por riĉulo eniri en la regnon de Dio.","Estas pli facile por kamelo iri tra trueton de kudrilo, ol por riĉulo eniri en la regnon de Dio."],[10,26,"Kaj ili forte miregis, dirante al li: Kiu do povas esti savita?","Kaj ili forte miregis, dirante al li: Kiu do povas esti savita?"],[10,27,"Rigardante ilin, Jesuo diris: Ĉe homoj tio estas neebla, sed ne ĉe Dio; ĉar ĉio estas ebla ĉe Dio.","Rigardante ilin, Jesuo diris: Ĉe homoj tio estas neebla, sed ne ĉe Dio; ĉar ĉio estas ebla ĉe Dio."],[10,28,"Petro ekparolis al li: Jen ni ĉion forlasis kaj vin sekvis.","Petro ekparolis al li: Jen ni ĉion forlasis kaj vin sekvis."],[10,29,"Jesuo diris: Vere mi diras al vi: Ekzistas neniu, kiu forlasis domon aŭ fratojn aŭ fratinojn aŭ patrinon aŭ patron aŭ infanojn aŭ kampojn pro mi kaj pro la evangelio,","Jesuo diris: Vere mi diras al vi: Ekzistas neniu, kiu forlasis domon aŭ fratojn aŭ fratinojn aŭ patrinon aŭ patron aŭ infanojn aŭ kampojn pro mi kaj pro la evangelio,"],[10,30,"kaj kiu ne ricevos centoble en ĉi tiu tempo, domojn kaj fratojn kaj fratinojn kaj patrinojn kaj infanojn kaj kampojn, kun persekutado; kaj en la venonta mondo eternan vivon.","kaj kiu ne ricevos centoble en ĉi tiu tempo, domojn kaj fratojn kaj fratinojn kaj patrinojn kaj infanojn kaj kampojn, kun persekutado; kaj en la venonta mondo eternan vivon."],[10,31,"Sed multaj unuaj estos lastaj, kaj lastaj estos unuaj.","Sed multaj unuaj estos lastaj, kaj lastaj estos unuaj."],[10,32,"Kaj ili estis sur la vojo suprenirantaj al Jerusalem, kaj Jesuo iris antaŭ ili; kaj ili miregis, kaj la sekvantoj timis. Kaj li prenis al si denove la dek du, kaj ekparolis pri tio, kio okazos al li, dirante:","Kaj ili estis sur la vojo suprenirantaj al Jerusalem, kaj Jesuo iris antaŭ ili; kaj ili miregis, kaj la sekvantoj timis. Kaj li prenis al si denove la dek du, kaj ekparolis pri tio, kio okazos al li, dirante:"],[10,33,"Jen ni supreniras al Jerusalem; kaj la Filo de homo estos transdonita al la ĉefpastroj kaj la skribistoj; kaj ili kondamnos lin al morto kaj transdonos lin al la nacianoj;","Jen ni supreniras al Jerusalem; kaj la Filo de homo estos transdonita al la ĉefpastroj kaj la skribistoj; kaj ili kondamnos lin al morto kaj transdonos lin al la nacianoj;"],[10,34,"kaj ili lin mokos kaj sur lin kraĉos kaj lin skurĝos kaj lin mortigos; kaj post tri tagoj li releviĝos.","kaj ili lin mokos kaj sur lin kraĉos kaj lin skurĝos kaj lin mortigos; kaj post tri tagoj li releviĝos."],[10,35,"Kaj alproksimiĝis al li Jakobo kaj Johano, filoj de Zebedeo, dirante al li: Majstro, ni deziras, ke, kion ajn ni petos de vi, vi tion faru por ni.","Kaj alproksimiĝis al li Jakobo kaj Johano, filoj de Zebedeo, dirante al li: Majstro, ni deziras, ke, kion ajn ni petos de vi, vi tion faru por ni."],[10,36,"Kaj li diris al ili: Kion vi volas, ke mi faru por vi?","Kaj li diris al ili: Kion vi volas, ke mi faru por vi?"],[10,37,"Kaj ili diris al li: Permesu, ke ni povu sidi, unu dekstre de vi kaj la dua maldekstre, en via gloro.","Kaj ili diris al li: Permesu, ke ni povu sidi, unu dekstre de vi kaj la dua maldekstre, en via gloro."],[10,38,"Sed Jesuo diris al ili: Vi ne scias, kion vi petas. Ĉu vi povas trinki la kalikon, kiun mi trinkas? aŭ esti baptitaj per la bapto, per kiu mi estas baptata?","Sed Jesuo diris al ili: Vi ne scias, kion vi petas. Ĉu vi povas trinki la kalikon, kiun mi trinkas? aŭ esti baptitaj per la bapto, per kiu mi estas baptata?"],[10,39,"Kaj ili diris al li: Ni povas. Kaj Jesuo diris al ili: La kalikon, kiun mi trinkas, vi trinkos, kaj per la bapto, per kiu mi estas baptata, vi estos baptitaj;","Kaj ili diris al li: Ni povas. Kaj Jesuo diris al ili: La kalikon, kiun mi trinkas, vi trinkos, kaj per la bapto, per kiu mi estas baptata, vi estos baptitaj;"],[10,40,"sed sidi dekstre de mi aŭ maldekstre, tion doni ne apartenas al mi; sed ĝi estas por tiuj, por kiuj ĝi estas preparita.","sed sidi dekstre de mi aŭ maldekstre, tion doni ne apartenas al mi; sed ĝi estas por tiuj, por kiuj ĝi estas preparita."],[10,41,"Kaj aŭdinte, la dek ekindignis kontraŭ Jakobo kaj Johano.","Kaj aŭdinte, la dek ekindignis kontraŭ Jakobo kaj Johano."],[10,42,"Kaj Jesuo, alvokinte ilin al si, diris al ili: Vi scias, ke tiuj, kiuj pretendas regi la nacianojn, kondutas kiel sinjoroj super ili, kaj iliaj granduloj ekzercas aŭtoritaton super ili.","Kaj Jesuo, alvokinte ilin al si, diris al ili: Vi scias, ke tiuj, kiuj pretendas regi la nacianojn, kondutas kiel sinjoroj super ili, kaj iliaj granduloj ekzercas aŭtoritaton super ili."],[10,43,"Sed ne tiel estos inter vi; sed kiu volas esti granda inter vi, tiu estu via servanto;","Sed ne tiel estos inter vi; sed kiu volas esti granda inter vi, tiu estu via servanto;"],[10,44,"kaj kiu volas esti la unua inter vi, tiu estu sklavo de ĉiuj.","kaj kiu volas esti la unua inter vi, tiu estu sklavo de ĉiuj."],[10,45,"Ĉar la Filo de homo venis, ne por esti servata, sed por servi, kaj por doni sian vivon kiel elaĉeton por multaj.","Ĉar la Filo de homo venis, ne por esti servata, sed por servi, kaj por doni sian vivon kiel elaĉeton por multaj."],[10,46,"Kaj ili venis al Jeriĥo; kaj kiam li foriris el Jeriĥo kun siaj disĉiploj kaj granda homamaso, la filo de Timeo, Bartimeo, blinda almozulo, sidis apud la vojo.","Kaj ili venis al Jeriĥo; kaj kiam li foriris el Jeriĥo kun siaj disĉiploj kaj granda homamaso, la filo de Timeo, Bartimeo, blinda almozulo, sidis apud la vojo."],[10,47,"Kaj aŭdinte, ke ĉeestas Jesuo, la Nazaretano, li ekkriis, kaj diris: Jesuo, filo de David, kompatu min.","Kaj aŭdinte, ke ĉeestas Jesuo, la Nazaretano, li ekkriis, kaj diris: Jesuo, filo de David, kompatu min."],[10,48,"Kaj multaj admonis lin, ke li silentu; sed li des pli forte kriis: Ho Filo de David, kompatu min!","Kaj multaj admonis lin, ke li silentu; sed li des pli forte kriis: Ho Filo de David, kompatu min!"],[10,49,"Kaj Jesuo haltis, kaj diris: Alvoku lin. Kaj oni alvokis la blindulon, dirante al li: Kuraĝu; leviĝu, li vin alvokas.","Kaj Jesuo haltis, kaj diris: Alvoku lin. Kaj oni alvokis la blindulon, dirante al li: Kuraĝu; leviĝu, li vin alvokas."],[10,50,"Kaj li forĵetis sian veston, kaj eksaltis kaj venis al Jesuo.","Kaj li forĵetis sian veston, kaj eksaltis kaj venis al Jesuo."],[10,51,"Kaj Jesuo responde al li diris: Kion vi volas, ke mi faru al vi? Kaj la blindulo diris al li: Rabeno mia, ke mi ricevu vidpovon.","Kaj Jesuo responde al li diris: Kion vi volas, ke mi faru al vi? Kaj la blindulo diris al li: Rabeno mia, ke mi ricevu vidpovon."],[10,52,"Kaj Jesuo diris al li: Iru; via fido vin savis. Kaj tuj li ricevis vidpovon, kaj sekvis lin sur la vojo.","Kaj Jesuo diris al li: Iru; via fido vin savis. Kaj tuj li ricevis vidpovon, kaj sekvis lin sur la vojo."],[11,1,"Kaj kiam ili alproksimiĝis al Jerusalem, al Betfage kaj Betania, apud la monto Olivarba, li sendis du el siaj disĉiploj,","Kaj kiam ili alproksimiĝis al Jerusalem, al Betfage kaj Betania, apud la monto Olivarba, li sendis du el siaj disĉiploj,"],[11,2,"kaj diris al ili: Iru en la vilaĝon, kiu estas kontraŭ vi, kaj enirinte ĝin, vi tuj trovos azenidon alligitan, sur kiu ankoraŭ neniu iam sidis; malligu kaj alkonduku ĝin.","kaj diris al ili: Iru en la vilaĝon, kiu estas kontraŭ vi, kaj enirinte ĝin, vi tuj trovos azenidon alligitan, sur kiu ankoraŭ neniu iam sidis; malligu kaj alkonduku ĝin."],[11,3,"Kaj se iu diros al vi: Kial vi faras tion? respondu: La Sinjoro bezonas ĝin; kaj tuj li sendos ĝin ĉi tien.","Kaj se iu diros al vi: Kial vi faras tion? respondu: La Sinjoro bezonas ĝin; kaj tuj li sendos ĝin ĉi tien."],[11,4,"Kaj ili iris, kaj trovis azenidon alligitan apud pordo ekstere sur la strato; kaj ili malligis ĝin.","Kaj ili iris, kaj trovis azenidon alligitan apud pordo ekstere sur la strato; kaj ili malligis ĝin."],[11,5,"Kaj iuj apudstarantoj diris al ili: Kion vi faras, malligante la azenidon?","Kaj iuj apudstarantoj diris al ili: Kion vi faras, malligante la azenidon?"],[11,6,"Sed ili respondis al ili, kiel Jesuo diris; kaj ili lasis ilin.","Sed ili respondis al ili, kiel Jesuo diris; kaj ili lasis ilin."],[11,7,"Kaj ili alkondukis la azenidon al Jesuo, kaj metis sur ĝin siajn vestojn; kaj li sidis sur ĝi.","Kaj ili alkondukis la azenidon al Jesuo, kaj metis sur ĝin siajn vestojn; kaj li sidis sur ĝi."],[11,8,"Kaj multaj sternis siajn vestojn sur la vojo, kaj aliaj sternis foliarojn, tranĉinte ilin el la kampoj.","Kaj multaj sternis siajn vestojn sur la vojo, kaj aliaj sternis foliarojn, tranĉinte ilin el la kampoj."],[11,9,"Kaj kriis la antaŭirantoj kaj la sekvantoj: Hosana! Estu benata tiu, kiu venas en la nomo de la Eternulo;","Kaj kriis la antaŭirantoj kaj la sekvantoj: Hosana! Estu benata tiu, kiu venas en la nomo de la Eternulo;"],[11,10,"Estu benata la venanta regno de nia patro David; Hosana en la supera alto!","Estu benata la venanta regno de nia patro David; Hosana en la supera alto!"],[11,11,"Kaj li eniris en Jerusalemon, en la templon; kaj kiam li ĉirkaŭrigardis ĉion, kaj la horo jam vesperiĝis, li foriris al Betania kun la dek du.","Kaj li eniris en Jerusalemon, en la templon; kaj kiam li ĉirkaŭrigardis ĉion, kaj la horo jam vesperiĝis, li foriris al Betania kun la dek du."],[11,12,"Kaj la morgaŭan tagon, post ilia eliro el Betania, li malsatis.","Kaj la morgaŭan tagon, post ilia eliro el Betania, li malsatis."],[11,13,"Kaj vidinte el malproksime figarbon havantan foliojn, li aliris, por trovi, se eble, ion sur ĝi; kaj veninte al ĝi, li trovis nenion krom folioj, ĉar la tempo de figoj ankoraŭ ne venis.","Kaj vidinte el malproksime figarbon havantan foliojn, li aliris, por trovi, se eble, ion sur ĝi; kaj veninte al ĝi, li trovis nenion krom folioj, ĉar la tempo de figoj ankoraŭ ne venis."],[11,14,"Kaj responde li diris al ĝi: Neniu por ĉiam manĝu frukton el vi. Kaj aŭdis la disĉiploj.","Kaj responde li diris al ĝi: Neniu por ĉiam manĝu frukton el vi. Kaj aŭdis la disĉiploj."],[11,15,"Kaj ili venis en Jerusalemon; kaj enirinte en la templon, li komencis elpeli la vendantojn kaj la aĉetantojn en la templo, kaj renversis la tablojn de la monŝanĝistoj kaj la seĝojn de la vendantoj de kolomboj;","Kaj ili venis en Jerusalemon; kaj enirinte en la templon, li komencis elpeli la vendantojn kaj la aĉetantojn en la templo, kaj renversis la tablojn de la monŝanĝistoj kaj la seĝojn de la vendantoj de kolomboj;"],[11,16,"kaj ne permesis, ke oni portu ian vazon tra la templo.","kaj ne permesis, ke oni portu ian vazon tra la templo."],[11,17,"Kaj li instruis, kaj diris al ili: Ĉu ne estas skribite: Mia domo estos nomata domo de preĝo por ĉiuj popoloj? Sed vi faris ĝin kaverno de rabistoj.","Kaj li instruis, kaj diris al ili: Ĉu ne estas skribite: Mia domo estos nomata domo de preĝo por ĉiuj popoloj? Sed vi faris ĝin kaverno de rabistoj."],[11,18,"Kaj la ĉefpastroj kaj la skribistoj aŭdis tion, kaj serĉis, kiamaniere pereigi lin; ĉar ili timis lin, ĉar la tuta homamaso miregis pro lia instruado.","Kaj la ĉefpastroj kaj la skribistoj aŭdis tion, kaj serĉis, kiamaniere pereigi lin; ĉar ili timis lin, ĉar la tuta homamaso miregis pro lia instruado."],[11,19,"Kaj kiam vesperiĝis, li eliris el la urbo.","Kaj kiam vesperiĝis, li eliris el la urbo."],[11,20,"Kaj matene, preterpasante, ili vidis la figarbon forvelkinta de la radikoj.","Kaj matene, preterpasante, ili vidis la figarbon forvelkinta de la radikoj."],[11,21,"Kaj rememorinte, Petro diris al li: Rabeno, jen forvelkis la figarbo, kiun vi malbenis.","Kaj rememorinte, Petro diris al li: Rabeno, jen forvelkis la figarbo, kiun vi malbenis."],[11,22,"Kaj responde Jesuo diris al ili: Havu fidon al Dio.","Kaj responde Jesuo diris al ili: Havu fidon al Dio."],[11,23,"Vere mi diras al vi: Se iu diros al ĉi tiu monto: Estu formovita kaj ĵetita en la maron, kaj ne dubos en sia koro, sed kredos, ke okazos tio, kion li diras, tiu ĝin havos.","Vere mi diras al vi: Se iu diros al ĉi tiu monto: Estu formovita kaj ĵetita en la maron, kaj ne dubos en sia koro, sed kredos, ke okazos tio, kion li diras, tiu ĝin havos."],[11,24,"Pro tio mi diras al vi: Kion ajn vi petos, preĝante, kredu, ke vi tion jam ricevis, kaj vi ĝin havos.","Pro tio mi diras al vi: Kion ajn vi petos, preĝante, kredu, ke vi tion jam ricevis, kaj vi ĝin havos."],[11,25,"Kaj kiam vi staras preĝante, pardonu, se vi havas ion kontraŭ iu; por ke ankaŭ via Patro, kiu estas en la ĉielo, pardonu al vi viajn erarojn.","Kaj kiam vi staras preĝante, pardonu, se vi havas ion kontraŭ iu; por ke ankaŭ via Patro, kiu estas en la ĉielo, pardonu al vi viajn erarojn."],[11,26,"Sed se vi ne pardonos, ankaŭ via Patro, kiu estas en la ĉielo, ne pardonos viajn erarojn.","Sed se vi ne pardonos, ankaŭ via Patro, kiu estas en la ĉielo, ne pardonos viajn erarojn."],[11,27,"Kaj ili denove venis al Jerusalem; kaj dum li ĉirkaŭiris en la templo, la ĉefpastroj kaj la skribistoj kaj la pliaĝuloj venis al li,","Kaj ili denove venis al Jerusalem; kaj dum li ĉirkaŭiris en la templo, la ĉefpastroj kaj la skribistoj kaj la pliaĝuloj venis al li,"],[11,28,"kaj diris al li: Laŭ kia aŭtoritato vi faras ĉi tion? aŭ kiu donis al vi tian aŭtoritaton, ke vi faru ĉi tion?","kaj diris al li: Laŭ kia aŭtoritato vi faras ĉi tion? aŭ kiu donis al vi tian aŭtoritaton, ke vi faru ĉi tion?"],[11,29,"Sed Jesuo diris al ili: Mi faros al vi unu demandon, kaj respondu al mi, kaj mi diros al vi, laŭ kia aŭtoritato mi faras ĉi tion.","Sed Jesuo diris al ili: Mi faros al vi unu demandon, kaj respondu al mi, kaj mi diros al vi, laŭ kia aŭtoritato mi faras ĉi tion."],[11,30,"La baptado de Johano, ĉu ĝi estis el la ĉielo, aŭ el homoj? respondu al mi.","La baptado de Johano, ĉu ĝi estis el la ĉielo, aŭ el homoj? respondu al mi."],[11,31,"Kaj ili diskutis inter si, dirante: Se ni diros: El la ĉielo, li diros: Kial do vi ne kredis al li?","Kaj ili diskutis inter si, dirante: Se ni diros: El la ĉielo, li diros: Kial do vi ne kredis al li?"],[11,32,"Sed se ni diros: El homoj — ili timis la popolon, ĉar ĉiuj opiniis, ke Johano efektive estis profeto.","Sed se ni diros: El homoj — ili timis la popolon, ĉar ĉiuj opiniis, ke Johano efektive estis profeto."],[11,33,"Kaj responde ili diris al Jesuo: Ni ne scias. Kaj Jesuo diris al ili: Kaj mi ne diras al vi, laŭ kia aŭtoritato mi faras ĉi tion.","Kaj responde ili diris al Jesuo: Ni ne scias. Kaj Jesuo diris al ili: Kaj mi ne diras al vi, laŭ kia aŭtoritato mi faras ĉi tion."],[12,1,"Kaj li komencis paroli al ili per paraboloj. Vinberĝardenon plantis unu viro, kaj ĉirkaŭmetis plektobarilon, kaj fosis vinpremejon, kaj konstruis turon, kaj luigis ĝin al kultivistoj, kaj forvojaĝis.","Kaj li komencis paroli al ili per paraboloj. Vinberĝardenon plantis unu viro, kaj ĉirkaŭmetis plektobarilon, kaj fosis vinpremejon, kaj konstruis turon, kaj luigis ĝin al kultivistoj, kaj forvojaĝis."],[12,2,"Kaj li sendis sklavon en la ĝusta tempo al la kultivistoj, por ricevi de la kultivistoj el la fruktoj de la vinberejo.","Kaj li sendis sklavon en la ĝusta tempo al la kultivistoj, por ricevi de la kultivistoj el la fruktoj de la vinberejo."],[12,3,"Kaj ili kaptis lin kaj skurĝis lin, kaj forsendis lin senhava.","Kaj ili kaptis lin kaj skurĝis lin, kaj forsendis lin senhava."],[12,4,"Kaj poste li sendis al ili duan sklavon; kaj ili lin kapvundis kaj malhonoris.","Kaj poste li sendis al ili duan sklavon; kaj ili lin kapvundis kaj malhonoris."],[12,5,"Kaj li sendis alian, kaj ili mortigis lin; kaj multajn aliajn; skurĝante unujn, kaj mortigante aliajn.","Kaj li sendis alian, kaj ili mortigis lin; kaj multajn aliajn; skurĝante unujn, kaj mortigante aliajn."],[12,6,"Li havis ankoraŭ unu amatan filon: li sendis lin ankaŭ la lastan al ili, dirante: Ili respektos mian filon.","Li havis ankoraŭ unu amatan filon: li sendis lin ankaŭ la lastan al ili, dirante: Ili respektos mian filon."],[12,7,"Sed tiuj kultivistoj diris inter si: Ĉi tiu estas la heredonto; venu, ni mortigu lin, kaj la heredaĵo estos nia.","Sed tiuj kultivistoj diris inter si: Ĉi tiu estas la heredonto; venu, ni mortigu lin, kaj la heredaĵo estos nia."],[12,8,"Kaj ili kaptis kaj mortigis lin, kaj elĵetis lin ekster la vinberejon.","Kaj ili kaptis kaj mortigis lin, kaj elĵetis lin ekster la vinberejon."],[12,9,"Kion do faros la sinjoro de la vinberejo? li venos kaj pereigos la kultivistojn, kaj donos la vinberejon al aliaj.","Kion do faros la sinjoro de la vinberejo? li venos kaj pereigos la kultivistojn, kaj donos la vinberejon al aliaj."],[12,10,"Ĉu vi ne legis tiun skribon: Ŝtono, kiun malŝatis la konstruantoj, Fariĝis ŝtono bazangula;","Ĉu vi ne legis tiun skribon: Ŝtono, kiun malŝatis la konstruantoj, Fariĝis ŝtono bazangula;"],[12,11,"De la Eternulo ĉi tio fariĝis, Kaj ĝi estas miraklo en niaj okuloj?","De la Eternulo ĉi tio fariĝis, Kaj ĝi estas miraklo en niaj okuloj?"],[12,12,"Kaj ili celis kapti lin, sed ili timis la homamason; ĉar ili eksciis, ke li parolis la parabolon kontraŭ ili; kaj forlasinte lin, ili foriris.","Kaj ili celis kapti lin, sed ili timis la homamason; ĉar ili eksciis, ke li parolis la parabolon kontraŭ ili; kaj forlasinte lin, ili foriris."],[12,13,"Kaj ili sendis al li iujn el la Fariseoj kaj el la Herodanoj, por impliki lin per interparolado.","Kaj ili sendis al li iujn el la Fariseoj kaj el la Herodanoj, por impliki lin per interparolado."],[12,14,"Kaj veninte, ili diris al li: Majstro, ni scias, ke vi estas verama kaj ne zorgas pri iu ajn; ĉar vi ne favoras la personon de homoj, sed instruas laŭ vero la vojon de Dio. Ĉu konvenas doni tributon al Cezaro, aŭ ne?","Kaj veninte, ili diris al li: Majstro, ni scias, ke vi estas verama kaj ne zorgas pri iu ajn; ĉar vi ne favoras la personon de homoj, sed instruas laŭ vero la vojon de Dio. Ĉu konvenas doni tributon al Cezaro, aŭ ne?"],[12,15,"Ĉu ni donu, aŭ ne donu? Sed li, sciante ilian hipokritecon, diris al ili: Kial vi provas min? alportu al mi denaron, ke mi ĝin vidu.","Ĉu ni donu, aŭ ne donu? Sed li, sciante ilian hipokritecon, diris al ili: Kial vi provas min? alportu al mi denaron, ke mi ĝin vidu."],[12,16,"Kaj ili ĝin alportis. Kaj li diris al ili: Kies estas ĉi tiu bildo kaj la surskribaĵo? Kaj ili diris al li: De Cezaro.","Kaj ili ĝin alportis. Kaj li diris al ili: Kies estas ĉi tiu bildo kaj la surskribaĵo? Kaj ili diris al li: De Cezaro."],[12,17,"Kaj Jesuo respondis al ili: Redonu al Cezaro la propraĵon de Cezaro, kaj al Dio la propraĵon de Dio. Kaj ili miregis pro li.","Kaj Jesuo respondis al ili: Redonu al Cezaro la propraĵon de Cezaro, kaj al Dio la propraĵon de Dio. Kaj ili miregis pro li."],[12,18,"Kaj venis al li Sadukeoj, kiuj diras, ke ne estas releviĝo; kaj ili demandis lin, dirante:","Kaj venis al li Sadukeoj, kiuj diras, ke ne estas releviĝo; kaj ili demandis lin, dirante:"],[12,19,"Majstro, Moseo skribis por ni: Se ies frato mortos kaj postlasos edzinon kaj ne lasos infanon, la frato de la mortinto prenu lian edzinon kaj naskigu idaron al sia frato.","Majstro, Moseo skribis por ni: Se ies frato mortos kaj postlasos edzinon kaj ne lasos infanon, la frato de la mortinto prenu lian edzinon kaj naskigu idaron al sia frato."],[12,20,"Estis sep fratoj; kaj la unua prenis edzinon, kaj mortinte, ne lasis idaron;","Estis sep fratoj; kaj la unua prenis edzinon, kaj mortinte, ne lasis idaron;"],[12,21,"kaj la dua prenis ŝin, kaj mortis, ne lasinte idaron; kaj la tria same;","kaj la dua prenis ŝin, kaj mortis, ne lasinte idaron; kaj la tria same;"],[12,22,"kaj la sep ne lasis idaron. Laste post ĉiuj la virino ankaŭ mortis.","kaj la sep ne lasis idaron. Laste post ĉiuj la virino ankaŭ mortis."],[12,23,"En la releviĝo, por kiu el ili ŝi estos edzino? ĉar ĉiuj sep havis ŝin kiel edzinon.","En la releviĝo, por kiu el ili ŝi estos edzino? ĉar ĉiuj sep havis ŝin kiel edzinon."],[12,24,"Kaj Jesuo diris al ili: Ĉu vi ne eraras pro tio, ke vi ne scias la Skribojn, nek la potencon de Dio?","Kaj Jesuo diris al ili: Ĉu vi ne eraras pro tio, ke vi ne scias la Skribojn, nek la potencon de Dio?"],[12,25,"Ĉar kiam oni leviĝos el la mortintoj, oni nek edziĝas nek edziniĝas, sed estas kiel anĝeloj en la ĉielo.","Ĉar kiam oni leviĝos el la mortintoj, oni nek edziĝas nek edziniĝas, sed estas kiel anĝeloj en la ĉielo."],[12,26,"Sed pri la mortintoj, ke ili releviĝas, ĉu vi ne legis en la libro de Moseo ĉe la arbetaĵo, kiel Dio parolis al li, dirante: Mi estas la Dio de Abraham kaj la Dio de Isaak kaj la Dio de Jakob?","Sed pri la mortintoj, ke ili releviĝas, ĉu vi ne legis en la libro de Moseo ĉe la arbetaĵo, kiel Dio parolis al li, dirante: Mi estas la Dio de Abraham kaj la Dio de Isaak kaj la Dio de Jakob?"],[12,27,"Li estas Dio ne de la mortintoj, sed de la vivantoj: vi multe eraras.","Li estas Dio ne de la mortintoj, sed de la vivantoj: vi multe eraras."],[12,28,"Kaj unu el la skribistoj alvenis kaj aŭskultis la diskutadon, kaj rimarkis, ke li lerte respondas al ili; kaj tiu demandis lin: Kiu ordono estas la unua el ĉiuj?","Kaj unu el la skribistoj alvenis kaj aŭskultis la diskutadon, kaj rimarkis, ke li lerte respondas al ili; kaj tiu demandis lin: Kiu ordono estas la unua el ĉiuj?"],[12,29,"Kaj Jesuo respondis: La unua estas: Aŭskultu, ho Izrael! la Eternulo, nia Dio, la Eternulo estas unu;","Kaj Jesuo respondis: La unua estas: Aŭskultu, ho Izrael! la Eternulo, nia Dio, la Eternulo estas unu;"],[12,30,"kaj amu la Eternulon, vian Dion, per via tuta koro kaj per via tuta animo kaj per via tuta menso kaj per via tuta forto.","kaj amu la Eternulon, vian Dion, per via tuta koro kaj per via tuta animo kaj per via tuta menso kaj per via tuta forto."],[12,31,"Kaj jen estas la dua: Amu vian proksimulon kiel vin mem. Pli granda ol ĉi tiuj ne estas alia ordono.","Kaj jen estas la dua: Amu vian proksimulon kiel vin mem. Pli granda ol ĉi tiuj ne estas alia ordono."],[12,32,"Kaj respondis al li la skribisto: Bone, Majstro, laŭ vero vi respondis, ke Li estas unu, kaj ne ekzistas alia krom Li;","Kaj respondis al li la skribisto: Bone, Majstro, laŭ vero vi respondis, ke Li estas unu, kaj ne ekzistas alia krom Li;"],[12,33,"kaj ami Lin per la tuta koro kaj per la tuta intelekto kaj per la tuta forto, kaj ami sian proksimulon kiel sin mem — tio multe pli valoras, ol ĉiuj bruloferoj kaj pekoferoj.","kaj ami Lin per la tuta koro kaj per la tuta intelekto kaj per la tuta forto, kaj ami sian proksimulon kiel sin mem — tio multe pli valoras, ol ĉiuj bruloferoj kaj pekoferoj."],[12,34,"Kaj Jesuo, vidante, ke li respondis prudente, diris al li: Vi ne estas malproksime de la regno de Dio. Kaj neniu plu kuraĝis fari al li demandon.","Kaj Jesuo, vidante, ke li respondis prudente, diris al li: Vi ne estas malproksime de la regno de Dio. Kaj neniu plu kuraĝis fari al li demandon."],[12,35,"Kaj responde Jesuo diris, instruante en la templo: Kial diras la skribistoj, ke la Kristo estas Filo de David?","Kaj responde Jesuo diris, instruante en la templo: Kial diras la skribistoj, ke la Kristo estas Filo de David?"],[12,36,"David mem diris per la Sankta Spirito: La Eternulo diris al mia Sinjoro: Sidu dekstre de Mi, Ĝis Mi faros viajn malamikojn benketo por viaj piedoj.","David mem diris per la Sankta Spirito: La Eternulo diris al mia Sinjoro: Sidu dekstre de Mi, Ĝis Mi faros viajn malamikojn benketo por viaj piedoj."],[12,37,"David mem nomas lin Sinjoro; kaj kiel do li estas lia filo? Kaj la granda homamaso aŭskultis lin plezure.","David mem nomas lin Sinjoro; kaj kiel do li estas lia filo? Kaj la granda homamaso aŭskultis lin plezure."],[12,38,"Kaj en sia instruado li diris: Gardu vin kontraŭ la skribistoj, kiuj amas promenadi en roboj kaj salutojn sur la placoj,","Kaj en sia instruado li diris: Gardu vin kontraŭ la skribistoj, kiuj amas promenadi en roboj kaj salutojn sur la placoj,"],[12,39,"kaj ĉefseĝojn en la sinagogoj, kaj ĉeflokojn ĉe festenoj;","kaj ĉefseĝojn en la sinagogoj, kaj ĉeflokojn ĉe festenoj;"],[12,40,"kaj kiuj formanĝas la domojn de vidvinoj, kaj por preteksto ili longe preĝas; ili ricevos pli severan kondamnon.","kaj kiuj formanĝas la domojn de vidvinoj, kaj por preteksto ili longe preĝas; ili ricevos pli severan kondamnon."],[12,41,"Kaj sidante kontraŭ la monkesto, li rimarkis, kiel la homoj enĵetas monerojn en la monkeston; kaj multaj riĉuloj enĵetis multon.","Kaj sidante kontraŭ la monkesto, li rimarkis, kiel la homoj enĵetas monerojn en la monkeston; kaj multaj riĉuloj enĵetis multon."],[12,42,"Kaj venis unu malriĉa vidvino, kaj enĵetis du leptojn, kiuj faras kodranton.","Kaj venis unu malriĉa vidvino, kaj enĵetis du leptojn, kiuj faras kodranton."],[12,43,"Kaj alvokinte al si siajn disĉiplojn, li diris al ili: Vere mi diras al vi, ke tiu malriĉa vidvino enĵetis pli ol ĉiuj ĵetantoj en la monkeston;","Kaj alvokinte al si siajn disĉiplojn, li diris al ili: Vere mi diras al vi, ke tiu malriĉa vidvino enĵetis pli ol ĉiuj ĵetantoj en la monkeston;"],[12,44,"ĉar ili ĉiuj enĵetis el sia abundo, sed ŝi el sia senhaveco ĵetis ĉion, kion ŝi havis, sian tutan vivrimedon.","ĉar ili ĉiuj enĵetis el sia abundo, sed ŝi el sia senhaveco ĵetis ĉion, kion ŝi havis, sian tutan vivrimedon."],[13,1,"Kaj dum li eliris el la templo, unu el liaj disĉiploj diris al li: Majstro, jen kiaj ŝtonoj kaj kiaj konstruaĵoj!","Kaj dum li eliris el la templo, unu el liaj disĉiploj diris al li: Majstro, jen kiaj ŝtonoj kaj kiaj konstruaĵoj!"],[13,2,"Kaj Jesuo diris al li: Ĉu vi vidas ĉi tiujn grandajn konstruaĵojn? ne estos lasita ĉi tie ŝtono sur ŝtono, kiu ne estos deĵetita.","Kaj Jesuo diris al li: Ĉu vi vidas ĉi tiujn grandajn konstruaĵojn? ne estos lasita ĉi tie ŝtono sur ŝtono, kiu ne estos deĵetita."],[13,3,"Kaj dum li sidis sur la monto Olivarba rekte kontraŭ la templo, Petro kaj Jakobo kaj Johano kaj Andreo demandis lin aparte:","Kaj dum li sidis sur la monto Olivarba rekte kontraŭ la templo, Petro kaj Jakobo kaj Johano kaj Andreo demandis lin aparte:"],[13,4,"Diru al ni, kiam tio estos? kaj kio estas la signo, kiam ĉio tio devos plenumiĝi?","Diru al ni, kiam tio estos? kaj kio estas la signo, kiam ĉio tio devos plenumiĝi?"],[13,5,"Kaj Jesuo ekparolis, kaj diris al ili: Gardu vin, ke neniu vin forlogu.","Kaj Jesuo ekparolis, kaj diris al ili: Gardu vin, ke neniu vin forlogu."],[13,6,"Multaj venos en mia nomo, dirante: Mi estas; kaj ili forlogos multajn.","Multaj venos en mia nomo, dirante: Mi estas; kaj ili forlogos multajn."],[13,7,"Kaj kiam vi aŭdos pri militoj kaj famoj de militoj, ne maltrankviliĝu; tio devas okazi; sed ankoraŭ ne estas la fino.","Kaj kiam vi aŭdos pri militoj kaj famoj de militoj, ne maltrankviliĝu; tio devas okazi; sed ankoraŭ ne estas la fino."],[13,8,"Ĉar leviĝos nacio kontraŭ nacio, kaj regno kontraŭ regno; estos tertremoj en diversaj lokoj, kaj estos malsatoj; tio estas komenco de suferoj.","Ĉar leviĝos nacio kontraŭ nacio, kaj regno kontraŭ regno; estos tertremoj en diversaj lokoj, kaj estos malsatoj; tio estas komenco de suferoj."],[13,9,"Sed gardu vin; ĉar oni transdonos vin al sinedrioj, kaj en sinagogoj vi estos skurĝitaj; kaj vi staros antaŭ provincestroj kaj reĝoj pro mi, por atesto al ili.","Sed gardu vin; ĉar oni transdonos vin al sinedrioj, kaj en sinagogoj vi estos skurĝitaj; kaj vi staros antaŭ provincestroj kaj reĝoj pro mi, por atesto al ili."],[13,10,"Kaj la evangelio devas antaŭe esti predikita al ĉiuj nacioj.","Kaj la evangelio devas antaŭe esti predikita al ĉiuj nacioj."],[13,11,"Kaj kiam oni forkondukos kaj transdonos vin, ne antaŭzorgu, kion vi parolos; sed kio ajn estos donita al vi en tiu horo, tion parolu; ĉar la parolanto estas ne vi, sed la Sankta Spirito.","Kaj kiam oni forkondukos kaj transdonos vin, ne antaŭzorgu, kion vi parolos; sed kio ajn estos donita al vi en tiu horo, tion parolu; ĉar la parolanto estas ne vi, sed la Sankta Spirito."],[13,12,"Kaj frato transdonos fraton al morto, kaj patro filon; kaj leviĝos gefiloj kontraŭ gepatroj kaj mortigos ilin.","Kaj frato transdonos fraton al morto, kaj patro filon; kaj leviĝos gefiloj kontraŭ gepatroj kaj mortigos ilin."],[13,13,"Kaj vi estos malamataj de ĉiuj pro mia nomo; sed kiu persistos ĝis la fino, tiu estos savita.","Kaj vi estos malamataj de ĉiuj pro mia nomo; sed kiu persistos ĝis la fino, tiu estos savita."],[13,14,"Sed kiam vi vidos la abomenindaĵon de dezerteco starantan tie, kie ne decas (la leganto komprenu), tiam kiuj estas en Judujo, tiuj forkuru al la montoj;","Sed kiam vi vidos la abomenindaĵon de dezerteco starantan tie, kie ne decas (la leganto komprenu), tiam kiuj estas en Judujo, tiuj forkuru al la montoj;"],[13,15,"kaj kiu estas sur la tegmento, tiu ne malsupreniru, nek eniru, por preni ion el sia domo;","kaj kiu estas sur la tegmento, tiu ne malsupreniru, nek eniru, por preni ion el sia domo;"],[13,16,"kaj kiu estas sur la kampo, tiu ne revenu, por preni sian mantelon.","kaj kiu estas sur la kampo, tiu ne revenu, por preni sian mantelon."],[13,17,"Sed ve al la gravedulinoj kaj al la suĉigantinoj en tiuj tagoj!","Sed ve al la gravedulinoj kaj al la suĉigantinoj en tiuj tagoj!"],[13,18,"Kaj preĝu, ke tio ne okazu en vintro.","Kaj preĝu, ke tio ne okazu en vintro."],[13,19,"Ĉar tiuj tagoj estos tagoj de aflikto tia, kia ne estis de la komenco de la kreo, kiun Dio kreis, ĝis nun, kaj neniam estos.","Ĉar tiuj tagoj estos tagoj de aflikto tia, kia ne estis de la komenco de la kreo, kiun Dio kreis, ĝis nun, kaj neniam estos."],[13,20,"Kaj se la Eternulo ne malplilongigus la tagojn, neniu karno estus savita; sed pro la elektitoj, kiujn Li elektis, Li malplilongigis la tagojn.","Kaj se la Eternulo ne malplilongigus la tagojn, neniu karno estus savita; sed pro la elektitoj, kiujn Li elektis, Li malplilongigis la tagojn."],[13,21,"Kaj tiam se iu diros al vi: Jen ĉi tie la Kristo, aŭ, Jen tie; ne kredu;","Kaj tiam se iu diros al vi: Jen ĉi tie la Kristo, aŭ, Jen tie; ne kredu;"],[13,22,"ĉar leviĝos falsaj kristoj kaj falsaj profetoj, kaj faros signojn kaj miraklojn, por erarigi, se eble, la elektitojn.","ĉar leviĝos falsaj kristoj kaj falsaj profetoj, kaj faros signojn kaj miraklojn, por erarigi, se eble, la elektitojn."],[13,23,"Sed gardu vin; jen mi ĉion antaŭdiris al vi.","Sed gardu vin; jen mi ĉion antaŭdiris al vi."],[13,24,"Sed en tiuj tagoj, post tiu aflikto, la suno mallumiĝos kaj la luno ne donos sian lumon,","Sed en tiuj tagoj, post tiu aflikto, la suno mallumiĝos kaj la luno ne donos sian lumon,"],[13,25,"kaj la steloj falados el la ĉielo, kaj la potencoj, kiuj estas en la ĉieloj, ŝanceliĝos.","kaj la steloj falados el la ĉielo, kaj la potencoj, kiuj estas en la ĉieloj, ŝanceliĝos."],[13,26,"Kaj tiam oni vidos la Filon de homo, venantan en nuboj kun granda potenco kaj gloro.","Kaj tiam oni vidos la Filon de homo, venantan en nuboj kun granda potenco kaj gloro."],[13,27,"Kaj tiam li elsendos la anĝelojn kaj kolektos siajn elektitojn el la kvar ventoj, de la limo de la tero ĝis la limo de la ĉielo.","Kaj tiam li elsendos la anĝelojn kaj kolektos siajn elektitojn el la kvar ventoj, de la limo de la tero ĝis la limo de la ĉielo."],[13,28,"De la figarbo lernu ĝian parabolon: kiam ĝia branĉo jam moliĝas kaj aperigas foliojn, vi scias, ke la somero estas proksima;","De la figarbo lernu ĝian parabolon: kiam ĝia branĉo jam moliĝas kaj aperigas foliojn, vi scias, ke la somero estas proksima;"],[13,29,"tiel same vi, kiam vi vidos, ke tio okazas, tiam sciu, ke li estas proksima, ĉe la pordoj.","tiel same vi, kiam vi vidos, ke tio okazas, tiam sciu, ke li estas proksima, ĉe la pordoj."],[13,30,"Vere mi diras al vi: Ĉi tiu generacio ne forpasos, antaŭ ol ĉio tio fariĝos.","Vere mi diras al vi: Ĉi tiu generacio ne forpasos, antaŭ ol ĉio tio fariĝos."],[13,31,"La ĉielo kaj la tero forpasos, sed miaj vortoj ne forpasos.","La ĉielo kaj la tero forpasos, sed miaj vortoj ne forpasos."],[13,32,"Sed pri tiu tago kaj la horo scias neniu, eĉ ne la anĝeloj en la ĉielo, nek la Filo, sed nur la Patro.","Sed pri tiu tago kaj la horo scias neniu, eĉ ne la anĝeloj en la ĉielo, nek la Filo, sed nur la Patro."],[13,33,"Gardu vin, viglu kaj preĝu; ĉar vi ne scias, kiam estos la ĝusta tempo.","Gardu vin, viglu kaj preĝu; ĉar vi ne scias, kiam estos la ĝusta tempo."],[13,34,"Kiel homo forvojaĝinta, kiu lasis sian domon kaj donis aŭtoritaton al siaj sklavoj, al ĉiu lian propran laboron, kaj ordonis al la pordisto, ke li viglu:","Kiel homo forvojaĝinta, kiu lasis sian domon kaj donis aŭtoritaton al siaj sklavoj, al ĉiu lian propran laboron, kaj ordonis al la pordisto, ke li viglu:"],[13,35,"vi do viglu; ĉar vi ne scias, kiam venos la domomastro, ĉu vespere, ĉu noktomeze, ĉu ĉe la kokokrio, ĉu frumatene;","vi do viglu; ĉar vi ne scias, kiam venos la domomastro, ĉu vespere, ĉu noktomeze, ĉu ĉe la kokokrio, ĉu frumatene;"],[13,36,"por ke li ne venu subite kaj ne trovu vin dormantaj.","por ke li ne venu subite kaj ne trovu vin dormantaj."],[13,37,"Kaj kion mi diras al vi, tion mi diras al ĉiuj: Viglu.","Kaj kion mi diras al vi, tion mi diras al ĉiuj: Viglu."],[14,1,"Kaj post du tagoj estis la Pasko kaj la festo de macoj; kaj la ĉefpastroj kaj skribistoj serĉis, kiamaniere ili povu per ruzo lin kapti kaj mortigi;","Kaj post du tagoj estis la Pasko kaj la festo de macoj; kaj la ĉefpastroj kaj skribistoj serĉis, kiamaniere ili povu per ruzo lin kapti kaj mortigi;"],[14,2,"ĉar ili diris: Ne dum la festo, por ke ne estu tumulto de la popolo.","ĉar ili diris: Ne dum la festo, por ke ne estu tumulto de la popolo."],[14,3,"Kaj dum li estis en Betania, en la domo de Simon, la leprulo, kiam li sidis ĉe manĝo, venis virino, havanta alabastran vazon da pura narda ŝmiraĵo, tre multekosta; kaj rompinte la vazon, ŝi surverŝis lian kapon.","Kaj dum li estis en Betania, en la domo de Simon, la leprulo, kiam li sidis ĉe manĝo, venis virino, havanta alabastran vazon da pura narda ŝmiraĵo, tre multekosta; kaj rompinte la vazon, ŝi surverŝis lian kapon."],[14,4,"Kaj iuj indignis inter si, dirante: Por kio fariĝis ĉi tiu malŝparo de la ŝmiraĵo?","Kaj iuj indignis inter si, dirante: Por kio fariĝis ĉi tiu malŝparo de la ŝmiraĵo?"],[14,5,"Ĉar ĉi tiun ŝmiraĵon oni povus vendi por pli ol tricent denaroj, kaj doni al malriĉuloj. Kaj ili murmuris kontraŭ ŝi.","Ĉar ĉi tiun ŝmiraĵon oni povus vendi por pli ol tricent denaroj, kaj doni al malriĉuloj. Kaj ili murmuris kontraŭ ŝi."],[14,6,"Kaj Jesuo diris: Lasu ŝin; kial vi ĝenas ŝin? ŝi faris bonan faron al mi.","Kaj Jesuo diris: Lasu ŝin; kial vi ĝenas ŝin? ŝi faris bonan faron al mi."],[14,7,"Ĉar la malriĉulojn vi ĉiam havas kun vi, kaj kiam ajn vi volas, vi povas bonfari al ili; sed min vi ne ĉiam havas.","Ĉar la malriĉulojn vi ĉiam havas kun vi, kaj kiam ajn vi volas, vi povas bonfari al ili; sed min vi ne ĉiam havas."],[14,8,"Kion ŝi povis, tion ŝi faris; ŝi antaŭfaris la ŝmiron de mia korpo por la entombigo.","Kion ŝi povis, tion ŝi faris; ŝi antaŭfaris la ŝmiron de mia korpo por la entombigo."],[14,9,"Vere mi diras al vi: Kie ajn estos predikata la evangelio en la tuta mondo, tio ankaŭ, kion ŝi faris, estos priparolata, por memoraĵo de ŝi.","Vere mi diras al vi: Kie ajn estos predikata la evangelio en la tuta mondo, tio ankaŭ, kion ŝi faris, estos priparolata, por memoraĵo de ŝi."],[14,10,"Kaj Judas Iskariota, kiu estis unu el la dek du, foriris al la ĉefpastroj, por transdoni lin al ili.","Kaj Judas Iskariota, kiu estis unu el la dek du, foriris al la ĉefpastroj, por transdoni lin al ili."],[14,11,"Kaj aŭdinte, ili ĝojis, kaj promesis doni al li monon. Kaj li serĉis, kiamaniere oportune transdoni lin.","Kaj aŭdinte, ili ĝojis, kaj promesis doni al li monon. Kaj li serĉis, kiamaniere oportune transdoni lin."],[14,12,"Kaj en la unua tago de la macoj, kiam oni buĉis la Paskon, liaj disĉiploj diris al li: Kien vi volas, ke ni iru, kaj pretigu, por ke vi manĝu la Paskon?","Kaj en la unua tago de la macoj, kiam oni buĉis la Paskon, liaj disĉiploj diris al li: Kien vi volas, ke ni iru, kaj pretigu, por ke vi manĝu la Paskon?"],[14,13,"Kaj li sendis du el siaj disĉiploj, kaj diris al ili: Iru en la urbon, kaj vin renkontos viro, portanta kruĉon da akvo;","Kaj li sendis du el siaj disĉiploj, kaj diris al ili: Iru en la urbon, kaj vin renkontos viro, portanta kruĉon da akvo;"],[14,14,"lin sekvu, kaj kien li eniros, tie diru al la domomastro: La Majstro diras: Kie estas mia gastoĉambro, en kiu mi manĝos la Paskon kun miaj disĉiploj?","lin sekvu, kaj kien li eniros, tie diru al la domomastro: La Majstro diras: Kie estas mia gastoĉambro, en kiu mi manĝos la Paskon kun miaj disĉiploj?"],[14,15,"Kaj li mem montros al vi grandan supran ĉambron, prete aranĝitan; kaj tie vi pretigu por ni.","Kaj li mem montros al vi grandan supran ĉambron, prete aranĝitan; kaj tie vi pretigu por ni."],[14,16,"Kaj foriris la disĉiploj kaj iris en la urbon, kaj trovis tiel, kiel li diris al ili; kaj ili pretigis la Paskon.","Kaj foriris la disĉiploj kaj iris en la urbon, kaj trovis tiel, kiel li diris al ili; kaj ili pretigis la Paskon."],[14,17,"Kaj kiam vesperiĝis, li venis kun la dek du.","Kaj kiam vesperiĝis, li venis kun la dek du."],[14,18,"Kaj dum ili sidis kaj manĝis, Jesuo diris: Vere mi diras al vi, ke unu el vi perfidos min, unu, kiu manĝas kun mi.","Kaj dum ili sidis kaj manĝis, Jesuo diris: Vere mi diras al vi, ke unu el vi perfidos min, unu, kiu manĝas kun mi."],[14,19,"Kaj ili komencis malĝoji, kaj diri al li unu post la alia: Ĉu eble mi?","Kaj ili komencis malĝoji, kaj diri al li unu post la alia: Ĉu eble mi?"],[14,20,"Sed li diris al ili: Unu el la dek du, kiu trempas kun mi en la pladon.","Sed li diris al ili: Unu el la dek du, kiu trempas kun mi en la pladon."],[14,21,"La Filo de homo iros, kiel estas skribite pri li; sed ve al tiu viro, de kiu la Filo de homo estos perfidita! Se tiu homo ne estus naskita, estus bone por li.","La Filo de homo iros, kiel estas skribite pri li; sed ve al tiu viro, de kiu la Filo de homo estos perfidita! Se tiu homo ne estus naskita, estus bone por li."],[14,22,"Kaj dum ili manĝis, li prenis panon, kaj, beninte, dispecigis ĝin kaj donis al ili, kaj diris: Prenu; ĉi tio estas mia korpo.","Kaj dum ili manĝis, li prenis panon, kaj, beninte, dispecigis ĝin kaj donis al ili, kaj diris: Prenu; ĉi tio estas mia korpo."],[14,23,"Kaj li prenis kalikon, kaj, doninte dankon, li donis al ili; kaj ĉiuj trinkis el ĝi.","Kaj li prenis kalikon, kaj, doninte dankon, li donis al ili; kaj ĉiuj trinkis el ĝi."],[14,24,"Kaj li diris al ili: Ĉi tio estas mia sango de la interligo, kiu estas elverŝata por multaj.","Kaj li diris al ili: Ĉi tio estas mia sango de la interligo, kiu estas elverŝata por multaj."],[14,25,"Vere mi diras al vi: Mi ne plu trinkos el la frukto de la vinberarbo, ĝis tiu tago, kiam mi trinkos ĝin novan en la regno de Dio.","Vere mi diras al vi: Mi ne plu trinkos el la frukto de la vinberarbo, ĝis tiu tago, kiam mi trinkos ĝin novan en la regno de Dio."],[14,26,"Kaj kantinte himnon, ili foriris al la monto Olivarba.","Kaj kantinte himnon, ili foriris al la monto Olivarba."],[14,27,"Kaj Jesuo diris al ili: Vi ĉiuj ofendiĝos; ĉar estas skribite: Mi frapos la paŝtiston, kaj la ŝafoj diskuros.","Kaj Jesuo diris al ili: Vi ĉiuj ofendiĝos; ĉar estas skribite: Mi frapos la paŝtiston, kaj la ŝafoj diskuros."],[14,28,"Tamen post mia releviĝo, mi iros antaŭ vi en Galileon.","Tamen post mia releviĝo, mi iros antaŭ vi en Galileon."],[14,29,"Sed Petro diris al li: Eĉ se ĉiuj ofendiĝos, tamen ne mi.","Sed Petro diris al li: Eĉ se ĉiuj ofendiĝos, tamen ne mi."],[14,30,"Kaj Jesuo diris al li: Vere mi diras al vi, ke hodiaŭ en ĉi tiu nokto, antaŭ ol dufoje krios koko, vi trifoje malkonfesos min.","Kaj Jesuo diris al li: Vere mi diras al vi, ke hodiaŭ en ĉi tiu nokto, antaŭ ol dufoje krios koko, vi trifoje malkonfesos min."],[14,31,"Sed tre insiste li diris: Eĉ se mi devos morti kun vi, mi neniel vin malkonfesos. Kaj tiel same diris ili ĉiuj.","Sed tre insiste li diris: Eĉ se mi devos morti kun vi, mi neniel vin malkonfesos. Kaj tiel same diris ili ĉiuj."],[14,32,"Kaj ili venis al loko, kies nomo estas Getsemane; kaj li diris al siaj disĉiploj: Sidu ĉi tie, dum mi preĝos.","Kaj ili venis al loko, kies nomo estas Getsemane; kaj li diris al siaj disĉiploj: Sidu ĉi tie, dum mi preĝos."],[14,33,"Kaj li prenis kun si Petron kaj Jakobon kaj Johanon, kaj komencis tre konsterniĝi kaj maltrankviliĝi.","Kaj li prenis kun si Petron kaj Jakobon kaj Johanon, kaj komencis tre konsterniĝi kaj maltrankviliĝi."],[14,34,"Kaj li diris al ili: Tre malĝoja estas mia animo, eĉ ĝis morto; restu ĉi tie, kaj viglu.","Kaj li diris al ili: Tre malĝoja estas mia animo, eĉ ĝis morto; restu ĉi tie, kaj viglu."],[14,35,"Kaj irinte iom antaŭen, li falis sur la teron, kaj preĝis, ke, se povas esti, la horo pasu for de li.","Kaj irinte iom antaŭen, li falis sur la teron, kaj preĝis, ke, se povas esti, la horo pasu for de li."],[14,36,"Kaj li diris: Aba, Patro, ĉio estas ebla ĉe Vi: forportu de mi ĉi tiun kalikon; tamen estu ne tio, kion mi volas, sed kion Vi volas.","Kaj li diris: Aba, Patro, ĉio estas ebla ĉe Vi: forportu de mi ĉi tiun kalikon; tamen estu ne tio, kion mi volas, sed kion Vi volas."],[14,37,"Kaj li venis, kaj trovis ilin dormantaj, kaj diris al Petro: Simon, ĉu vi dormas? ĉu vi ne havis forton vigli eĉ unu horon?","Kaj li venis, kaj trovis ilin dormantaj, kaj diris al Petro: Simon, ĉu vi dormas? ĉu vi ne havis forton vigli eĉ unu horon?"],[14,38,"Viglu kaj preĝu, por ke vi ne eniru en tenton; la spirito ja estas fervora, sed la karno estas malforta.","Viglu kaj preĝu, por ke vi ne eniru en tenton; la spirito ja estas fervora, sed la karno estas malforta."],[14,39,"Kaj denove foririnte, li preĝis, dirante la samajn vortojn.","Kaj denove foririnte, li preĝis, dirante la samajn vortojn."],[14,40,"Kaj denove reveninte, li trovis ilin dormantaj, ĉar iliaj okuloj peziĝis; kaj ili ne sciis, kion respondi al li.","Kaj denove reveninte, li trovis ilin dormantaj, ĉar iliaj okuloj peziĝis; kaj ili ne sciis, kion respondi al li."],[14,41,"Kaj li venis la trian fojon, kaj diris al ili: Dormu nun kaj ripozu; sufiĉas; venis la horo; jen la Filo de homo estas perfidata en la manojn de pekuloj.","Kaj li venis la trian fojon, kaj diris al ili: Dormu nun kaj ripozu; sufiĉas; venis la horo; jen la Filo de homo estas perfidata en la manojn de pekuloj."],[14,42,"Leviĝu, ni iru; jen mia perfidanto alproksimiĝas.","Leviĝu, ni iru; jen mia perfidanto alproksimiĝas."],[14,43,"Kaj tuj, dum li ankoraŭ parolis, venis Judas, unu el la dek du; kaj kun li homamaso kun glavoj kaj bastonoj venis de la ĉefpastroj kaj la skribistoj kaj la pliaĝuloj.","Kaj tuj, dum li ankoraŭ parolis, venis Judas, unu el la dek du; kaj kun li homamaso kun glavoj kaj bastonoj venis de la ĉefpastroj kaj la skribistoj kaj la pliaĝuloj."],[14,44,"Kaj lia perfidanto jam antaŭe aranĝis kun ili signon, dirante: Kiun mi kisos, tiu estas li; kaptu kaj forkonduku lin garde.","Kaj lia perfidanto jam antaŭe aranĝis kun ili signon, dirante: Kiun mi kisos, tiu estas li; kaptu kaj forkonduku lin garde."],[14,45,"Kaj veninte, li tuj iris al li, kaj diris: Rabeno; kaj kisis lin.","Kaj veninte, li tuj iris al li, kaj diris: Rabeno; kaj kisis lin."],[14,46,"Kaj ili metis la manojn sur lin kaj arestis lin.","Kaj ili metis la manojn sur lin kaj arestis lin."],[14,47,"Sed unu el tiuj, kiuj staris apude, eltiris la glavon kaj frapis la sklavon de la ĉefpastro, kaj detranĉis al li la orelon.","Sed unu el tiuj, kiuj staris apude, eltiris la glavon kaj frapis la sklavon de la ĉefpastro, kaj detranĉis al li la orelon."],[14,48,"Kaj Jesuo responde diris al ili: Ĉu vi elvenis, kvazaŭ kontraŭ rabiston, kun glavoj kaj bastonoj, por kapti min?","Kaj Jesuo responde diris al ili: Ĉu vi elvenis, kvazaŭ kontraŭ rabiston, kun glavoj kaj bastonoj, por kapti min?"],[14,49,"Ĉiutage mi estis inter vi en la templo, instruante, kaj vi ne arestis min; tamen, ke plenumiĝu la Skriboj.","Ĉiutage mi estis inter vi en la templo, instruante, kaj vi ne arestis min; tamen, ke plenumiĝu la Skriboj."],[14,50,"Kaj ĉiuj forlasis lin kaj forkuris.","Kaj ĉiuj forlasis lin kaj forkuris."],[14,51,"Kaj sekvis lin unu junulo, vestita per tolaĵo ĉirkaŭ la nuda korpo; kaj oni kaptis lin;","Kaj sekvis lin unu junulo, vestita per tolaĵo ĉirkaŭ la nuda korpo; kaj oni kaptis lin;"],[14,52,"sed lasinte la tolaĵon, li forkuris nuda.","sed lasinte la tolaĵon, li forkuris nuda."],[14,53,"Kaj oni forkondukis Jesuon al la ĉefpastro; kaj kunvenis ĉe li ĉiuj ĉefpastroj kaj pliaĝuloj kaj skribistoj.","Kaj oni forkondukis Jesuon al la ĉefpastro; kaj kunvenis ĉe li ĉiuj ĉefpastroj kaj pliaĝuloj kaj skribistoj."],[14,54,"Kaj Petro malproksime sekvis lin ĝis interne de la korto de la ĉefpastro; kaj sidis kun la subuloj kaj sin varmigis apud la fajro.","Kaj Petro malproksime sekvis lin ĝis interne de la korto de la ĉefpastro; kaj sidis kun la subuloj kaj sin varmigis apud la fajro."],[14,55,"Sed la ĉefpastroj kaj la tuta sinedrio serĉis ateston kontraŭ Jesuo, por lin mortigi, kaj ne trovis.","Sed la ĉefpastroj kaj la tuta sinedrio serĉis ateston kontraŭ Jesuo, por lin mortigi, kaj ne trovis."],[14,56,"Ĉar multaj malvere atestis kontraŭ li, kaj iliaj atestoj ne akordiĝis.","Ĉar multaj malvere atestis kontraŭ li, kaj iliaj atestoj ne akordiĝis."],[14,57,"Kaj elpaŝis iuj, kaj malvere atestis kontraŭ li, dirante:","Kaj elpaŝis iuj, kaj malvere atestis kontraŭ li, dirante:"],[14,58,"Ni aŭdis lin diri: Mi detruos ĉi tiun sanktejon manfaritan, kaj en la daŭro de tri tagoj mi konstruos alian ne manfaritan.","Ni aŭdis lin diri: Mi detruos ĉi tiun sanktejon manfaritan, kaj en la daŭro de tri tagoj mi konstruos alian ne manfaritan."],[14,59,"Kaj eĉ tiel ilia atesto ne akordiĝis.","Kaj eĉ tiel ilia atesto ne akordiĝis."],[14,60,"Kaj la ĉefpastro stariĝis en la mezo, kaj demandis Jesuon, dirante: Ĉu vi respondas nenion? kion atestas ĉi tiuj kontraŭ vi?","Kaj la ĉefpastro stariĝis en la mezo, kaj demandis Jesuon, dirante: Ĉu vi respondas nenion? kion atestas ĉi tiuj kontraŭ vi?"],[14,61,"Sed li silentadis kaj respondis nenion. Denove la ĉefpastro demandis lin, kaj diris al li: Ĉu vi estas la Kristo, la Filo de la Benato?","Sed li silentadis kaj respondis nenion. Denove la ĉefpastro demandis lin, kaj diris al li: Ĉu vi estas la Kristo, la Filo de la Benato?"],[14,62,"Kaj Jesuo diris: Mi estas; kaj vi vidos la Filon de homo, sidantan dekstre de la Potenco kaj venantan kun la nuboj de la ĉielo.","Kaj Jesuo diris: Mi estas; kaj vi vidos la Filon de homo, sidantan dekstre de la Potenco kaj venantan kun la nuboj de la ĉielo."],[14,63,"Kaj la ĉefpastro disŝiris siajn vestojn, kaj diris: Pro kio ni plu bezonas atestantojn?","Kaj la ĉefpastro disŝiris siajn vestojn, kaj diris: Pro kio ni plu bezonas atestantojn?"],[14,64,"Vi aŭdis la blasfemon: kion vi opinias? Kaj ili ĉiuj juĝis lin kondamninda al morto.","Vi aŭdis la blasfemon: kion vi opinias? Kaj ili ĉiuj juĝis lin kondamninda al morto."],[14,65,"Kaj iuj komencis kraĉi sur lin, kaj ĉirkaŭkovri lian vizaĝon, kaj vangofrapi lin, kaj diri al li: Profetu; kaj la subuloj frapis lin per la manplatoj.","Kaj iuj komencis kraĉi sur lin, kaj ĉirkaŭkovri lian vizaĝon, kaj vangofrapi lin, kaj diri al li: Profetu; kaj la subuloj frapis lin per la manplatoj."],[14,66,"Kaj dum Petro estis malsupre sur la korto, venis unu el la servantinoj de la ĉefpastro;","Kaj dum Petro estis malsupre sur la korto, venis unu el la servantinoj de la ĉefpastro;"],[14,67,"kaj vidante Petron sin varmigantan, ŝi rigardis lin, kaj diris: Vi ankaŭ estis kun la Nazaretano, kun tiu Jesuo.","kaj vidante Petron sin varmigantan, ŝi rigardis lin, kaj diris: Vi ankaŭ estis kun la Nazaretano, kun tiu Jesuo."],[14,68,"Sed li malkonfesis, dirante: Mi ne scias, nek komprenas, kion vi diras; kaj li iris en la vestiblon; kaj koko kriis.","Sed li malkonfesis, dirante: Mi ne scias, nek komprenas, kion vi diras; kaj li iris en la vestiblon; kaj koko kriis."],[14,69,"Kaj lin vidinte, la servantino denove komencis diri al la apudstarantoj: Tiu estas el ili.","Kaj lin vidinte, la servantino denove komencis diri al la apudstarantoj: Tiu estas el ili."],[14,70,"Kaj li denove malkonfesis. Kaj post iom da tempo la apudstarantoj denove diris al Petro: Vere vi estas el ili, ĉar vi estas ja Galileano.","Kaj li denove malkonfesis. Kaj post iom da tempo la apudstarantoj denove diris al Petro: Vere vi estas el ili, ĉar vi estas ja Galileano."],[14,71,"Kaj li komencis malbeni kaj ĵuri: Mi ne konas tiun homon, pri kiu vi parolas.","Kaj li komencis malbeni kaj ĵuri: Mi ne konas tiun homon, pri kiu vi parolas."],[14,72,"Kaj tuj la duan fojon koko kriis. Kaj Petro ekrememoris la vorton, kiun Jesuo diris al li: Antaŭ ol dufoje krios koko, vi trifoje malkonfesos min. Kaj pripensinte, li ekploris.","Kaj tuj la duan fojon koko kriis. Kaj Petro ekrememoris la vorton, kiun Jesuo diris al li: Antaŭ ol dufoje krios koko, vi trifoje malkonfesos min. Kaj pripensinte, li ekploris."],[15,1,"Tuj matene la ĉefpastroj, farinte interkonsilon kun la pliaĝuloj kaj skribistoj kaj la tuta sinedrio, ligis Jesuon kaj forkondukis lin kaj transdonis lin al Pilato.","Tuj matene la ĉefpastroj, farinte interkonsilon kun la pliaĝuloj kaj skribistoj kaj la tuta sinedrio, ligis Jesuon kaj forkondukis lin kaj transdonis lin al Pilato."],[15,2,"Kaj Pilato demandis lin: Ĉu vi estas la Reĝo de la Judoj? Kaj responde li diris al li: Vi diras.","Kaj Pilato demandis lin: Ĉu vi estas la Reĝo de la Judoj? Kaj responde li diris al li: Vi diras."],[15,3,"Kaj la ĉefpastroj multe lin akuzis.","Kaj la ĉefpastroj multe lin akuzis."],[15,4,"Kaj Pilato denove lin demandis: Ĉu vi respondas nenion? vidu, pri kiom da aferoj oni vin akuzas.","Kaj Pilato denove lin demandis: Ĉu vi respondas nenion? vidu, pri kiom da aferoj oni vin akuzas."],[15,5,"Sed Jesuo ankoraŭ nenion respondis, tiel ke Pilato miris.","Sed Jesuo ankoraŭ nenion respondis, tiel ke Pilato miris."],[15,6,"Ĉe tiu festo li kutimis liberigi al ili unu malliberulon, iun ajn, kiun ili pripetis.","Ĉe tiu festo li kutimis liberigi al ili unu malliberulon, iun ajn, kiun ili pripetis."],[15,7,"Kaj estis unu, nomata Barabas, katenita kun la ribelintoj, kiuj en la ribelo faris mortigon.","Kaj estis unu, nomata Barabas, katenita kun la ribelintoj, kiuj en la ribelo faris mortigon."],[15,8,"Kaj suprenveninte, la homamaso komencis peti lin pri tio, kion li kutimis fari por ili.","Kaj suprenveninte, la homamaso komencis peti lin pri tio, kion li kutimis fari por ili."],[15,9,"Kaj Pilato respondis al ili, dirante: Ĉu vi volas, ke mi liberigu al vi la Reĝon de la Judoj?","Kaj Pilato respondis al ili, dirante: Ĉu vi volas, ke mi liberigu al vi la Reĝon de la Judoj?"],[15,10,"Ĉar li eksciis, ke pro envio la ĉefpastroj transdonis lin.","Ĉar li eksciis, ke pro envio la ĉefpastroj transdonis lin."],[15,11,"Sed la ĉefpastroj instigis la homamason, ke prefere li liberigu al ili Barabason.","Sed la ĉefpastroj instigis la homamason, ke prefere li liberigu al ili Barabason."],[15,12,"Kaj Pilato, denove respondante, diris al ili: Kion do mi faru al tiu, kiun vi nomas Reĝo de la Judoj?","Kaj Pilato, denove respondante, diris al ili: Kion do mi faru al tiu, kiun vi nomas Reĝo de la Judoj?"],[15,13,"Kaj ili denove ekkriis: Krucumu lin.","Kaj ili denove ekkriis: Krucumu lin."],[15,14,"Kaj Pilato diris al ili: Kial? kian malbonon li faris? Sed ili des pli ekkriis: Krucumu lin.","Kaj Pilato diris al ili: Kial? kian malbonon li faris? Sed ili des pli ekkriis: Krucumu lin."],[15,15,"Kaj Pilato, volante kontentigi la homamason, liberigis al ili Barabason, kaj, skurĝinte Jesuon, transdonis lin, por esti krucumita.","Kaj Pilato, volante kontentigi la homamason, liberigis al ili Barabason, kaj, skurĝinte Jesuon, transdonis lin, por esti krucumita."],[15,16,"Kaj la soldatoj forkondukis lin en la korton, kiu estas la Pretorio, kaj kunvokis la tutan kohorton.","Kaj la soldatoj forkondukis lin en la korton, kiu estas la Pretorio, kaj kunvokis la tutan kohorton."],[15,17,"Kaj ili vestis lin per purpuro, kaj plektinte dornan kronon, surmetis ĝin al li;","Kaj ili vestis lin per purpuro, kaj plektinte dornan kronon, surmetis ĝin al li;"],[15,18,"kaj ili komencis aklami lin: Saluton, Reĝo de la Judoj!","kaj ili komencis aklami lin: Saluton, Reĝo de la Judoj!"],[15,19,"Kaj ili frapis lian kapon per kano, kaj kraĉis sur lin, kaj ekgenuinte, kliniĝis al li.","Kaj ili frapis lian kapon per kano, kaj kraĉis sur lin, kaj ekgenuinte, kliniĝis al li."],[15,20,"Kaj mokinte lin, ili demetis de li la purpuran veston, kaj surmetis liajn proprajn vestojn. Kaj ili elkondukis lin, por krucumi lin.","Kaj mokinte lin, ili demetis de li la purpuran veston, kaj surmetis liajn proprajn vestojn. Kaj ili elkondukis lin, por krucumi lin."],[15,21,"Kaj ili devigis al servado unu preterpasanton, venantan de la kamparo, Simonon, Kirenanon, patron de Aleksandro kaj Rufo, ke li portu lian krucon.","Kaj ili devigis al servado unu preterpasanton, venantan de la kamparo, Simonon, Kirenanon, patron de Aleksandro kaj Rufo, ke li portu lian krucon."],[15,22,"Kaj ili kondukis lin al la loko Golgota, tio estas, Loko de Kranio.","Kaj ili kondukis lin al la loko Golgota, tio estas, Loko de Kranio."],[15,23,"Kaj ili donis al li vinon kun mirho enmiksita, sed li ne akceptis ĝin.","Kaj ili donis al li vinon kun mirho enmiksita, sed li ne akceptis ĝin."],[15,24,"Kaj ili krucumis lin kaj dividis inter si liajn vestojn, ĵetante lotojn sur ili, kion ĉiu el ili ricevu.","Kaj ili krucumis lin kaj dividis inter si liajn vestojn, ĵetante lotojn sur ili, kion ĉiu el ili ricevu."],[15,25,"Kaj estis la tria horo, kaj ili krucumis lin.","Kaj estis la tria horo, kaj ili krucumis lin."],[15,26,"Kaj la surskribo de lia akuzo estis surskribita: LA REĜO DE LA JUDOJ.","Kaj la surskribo de lia akuzo estis surskribita: LA REĜO DE LA JUDOJ."],[15,27,"Kaj kun li ili krucumis du rabistojn, unu dekstre kaj unu maldekstre de li.","Kaj kun li ili krucumis du rabistojn, unu dekstre kaj unu maldekstre de li."],[15,28,"Kaj plenumiĝis la Skribo, kiu diras: Kaj li estis alkalkulita al krimuloj.","Kaj plenumiĝis la Skribo, kiu diras: Kaj li estis alkalkulita al krimuloj."],[15,29,"Kaj la preterpasantoj insultis lin, balancante la kapon, kaj dirante: Ha, ha! vi, kiu detruas la sanktejon kaj konstruas ĝin en la daŭro de tri tagoj,","Kaj la preterpasantoj insultis lin, balancante la kapon, kaj dirante: Ha, ha! vi, kiu detruas la sanktejon kaj konstruas ĝin en la daŭro de tri tagoj,"],[15,30,"savu vin, deirante de la kruco.","savu vin, deirante de la kruco."],[15,31,"Tiel same ankaŭ la ĉefpastroj, mokante inter si kun la skribistoj, diris: Aliajn li savis; sin mem li ne povas savi.","Tiel same ankaŭ la ĉefpastroj, mokante inter si kun la skribistoj, diris: Aliajn li savis; sin mem li ne povas savi."],[15,32,"La Kristo, la Reĝo de Izrael, deiru ja nun de la kruco, por ke ni vidu kaj kredu. Kaj tiuj, kiuj estis krucumitaj kun li, insultis lin.","La Kristo, la Reĝo de Izrael, deiru ja nun de la kruco, por ke ni vidu kaj kredu. Kaj tiuj, kiuj estis krucumitaj kun li, insultis lin."],[15,33,"Kaj kiam venis la sesa horo, fariĝis mallumo sur la tuta lando ĝis la naŭa horo.","Kaj kiam venis la sesa horo, fariĝis mallumo sur la tuta lando ĝis la naŭa horo."],[15,34,"Kaj je la naŭa horo Jesuo kriis per laŭta voĉo: Eloi, Eloi, lama sabaĥtani; tio estas: Mia Dio, mia Dio, kial Vi forlasis min?","Kaj je la naŭa horo Jesuo kriis per laŭta voĉo: Eloi, Eloi, lama sabaĥtani; tio estas: Mia Dio, mia Dio, kial Vi forlasis min?"],[15,35,"Kaj iuj el la apudstarantoj, aŭdinte, diris: Jen li vokas Elijan.","Kaj iuj el la apudstarantoj, aŭdinte, diris: Jen li vokas Elijan."],[15,36,"Kaj unu kuris, kaj plenigis spongon per vinagro, kaj metinte ĝin sur kanon, donis al li trinki, dirante: Lasu; ni vidu, ĉu venos Elija, por depreni lin.","Kaj unu kuris, kaj plenigis spongon per vinagro, kaj metinte ĝin sur kanon, donis al li trinki, dirante: Lasu; ni vidu, ĉu venos Elija, por depreni lin."],[15,37,"Sed Jesuo, eliginte laŭtan krion, ellasis for la spiriton.","Sed Jesuo, eliginte laŭtan krion, ellasis for la spiriton."],[15,38,"Kaj la kurteno de la sanktejo disŝiriĝis en du pecojn de supre ĝis malsupre.","Kaj la kurteno de la sanktejo disŝiriĝis en du pecojn de supre ĝis malsupre."],[15,39,"Kaj kiam la centestro, kiu apudstaris kontraŭ li, vidis, ke li tiamaniere ellasis for la spiriton, li diris: Vere ĉi tiu viro estis Filo de Dio.","Kaj kiam la centestro, kiu apudstaris kontraŭ li, vidis, ke li tiamaniere ellasis for la spiriton, li diris: Vere ĉi tiu viro estis Filo de Dio."],[15,40,"Estis ankaŭ virinoj, rigardantaj de malproksime, inter kiuj estis Maria Magdalena, kaj Maria, la patrino de Jakobo la malgranda kaj de Joses, kaj Salome;","Estis ankaŭ virinoj, rigardantaj de malproksime, inter kiuj estis Maria Magdalena, kaj Maria, la patrino de Jakobo la malgranda kaj de Joses, kaj Salome;"],[15,41,"kiuj sekvis lin, kiam li estis en Galileo, kaj servadis al li; kaj multaj aliaj virinoj, kiuj suprenvenis kun li en Jerusalemon.","kiuj sekvis lin, kiam li estis en Galileo, kaj servadis al li; kaj multaj aliaj virinoj, kiuj suprenvenis kun li en Jerusalemon."],[15,42,"Kaj kiam jam vesperiĝis, pro tio, ke estas la Preparado, tio estas, la tago antaŭ sabato,","Kaj kiam jam vesperiĝis, pro tio, ke estas la Preparado, tio estas, la tago antaŭ sabato,"],[15,43,"venis Jozef el Arimateo, honorinda konsilanto, kiu mem atendadis la regnon de Dio; kaj li kuraĝe eniris al Pilato, kaj petis la korpon de Jesuo.","venis Jozef el Arimateo, honorinda konsilanto, kiu mem atendadis la regnon de Dio; kaj li kuraĝe eniris al Pilato, kaj petis la korpon de Jesuo."],[15,44,"Kaj Pilato miris, ĉu li jam mortis; kaj alvokinte la centestron, li demandis lin, ĉu li de longe estas mortinta.","Kaj Pilato miris, ĉu li jam mortis; kaj alvokinte la centestron, li demandis lin, ĉu li de longe estas mortinta."],[15,45,"Kaj sciiĝinte de la centestro, li donis al Jozef la korpon.","Kaj sciiĝinte de la centestro, li donis al Jozef la korpon."],[15,46,"Kaj li aĉetis tolaĵon, kaj deprenis lin kaj envolvis lin en la tolaĵo, kaj metis lin en tombon, kiu estis elhakita el ŝtonego; kaj li alrulis ŝtonon al la enirejo de la tombo.","Kaj li aĉetis tolaĵon, kaj deprenis lin kaj envolvis lin en la tolaĵo, kaj metis lin en tombon, kiu estis elhakita el ŝtonego; kaj li alrulis ŝtonon al la enirejo de la tombo."],[15,47,"Kaj Maria Magdalena, kaj Maria, la patrino de Joses, vidis, kien oni metis lin.","Kaj Maria Magdalena, kaj Maria, la patrino de Joses, vidis, kien oni metis lin."],[16,1,"Kaj kiam la sabato jam pasis, Maria Magdalena, kaj Maria, la patrino de Jakobo, kaj Salome aĉetis aromaĵojn, por ke ili iru kaj ŝmiru lin.","Kaj kiam la sabato jam pasis, Maria Magdalena, kaj Maria, la patrino de Jakobo, kaj Salome aĉetis aromaĵojn, por ke ili iru kaj ŝmiru lin."],[16,2,"Kaj tre frue en la unua tago de la semajno ili venis al la tombo, kiam la suno ĵus leviĝis.","Kaj tre frue en la unua tago de la semajno ili venis al la tombo, kiam la suno ĵus leviĝis."],[16,3,"Kaj ili diris inter si: Kiu derulos por ni la ŝtonon de la enirejo de la tombo?","Kaj ili diris inter si: Kiu derulos por ni la ŝtonon de la enirejo de la tombo?"],[16,4,"kaj suprenrigardante, ili vidis, ke la ŝtono estas derulita; ĉar ĝi estis tre granda.","kaj suprenrigardante, ili vidis, ke la ŝtono estas derulita; ĉar ĝi estis tre granda."],[16,5,"Kaj enirinte en la tombon, ili vidis junulon sidantan ĉe la dekstra flanko, vestitan per blanka robo; kaj ili miregis.","Kaj enirinte en la tombon, ili vidis junulon sidantan ĉe la dekstra flanko, vestitan per blanka robo; kaj ili miregis."],[16,6,"Sed li diris al ili: Ne miregu; vi serĉas Jesuon, la Nazaretanon, la krucumitan: li leviĝis; li ne estas ĉi tie; jen la loko, kien oni metis lin!","Sed li diris al ili: Ne miregu; vi serĉas Jesuon, la Nazaretanon, la krucumitan: li leviĝis; li ne estas ĉi tie; jen la loko, kien oni metis lin!"],[16,7,"Sed iru, diru al liaj disĉiploj kaj al Petro: Li iras antaŭ vi en Galileon; tie vi vidos lin, kiel li diris al vi.","Sed iru, diru al liaj disĉiploj kaj al Petro: Li iras antaŭ vi en Galileon; tie vi vidos lin, kiel li diris al vi."],[16,8,"Kaj elirinte, ili forkuris de la tombo, ĉar tremado kaj konfuziĝo posedis ilin; kaj ili diris nenion al iu, ĉar ili timis.","Kaj elirinte, ili forkuris de la tombo, ĉar tremado kaj konfuziĝo posedis ilin; kaj ili diris nenion al iu, ĉar ili timis."],[16,9,"Sed leviĝinte frue en la unua tago de la semajno, li aperis unue al Maria Magdalena, el kiu li elpelis sep demonojn.","Sed leviĝinte frue en la unua tago de la semajno, li aperis unue al Maria Magdalena, el kiu li elpelis sep demonojn."],[16,10,"Ŝi iris, kaj sciigis ĝin al la homoj, kiuj estis kun li, dum ili malĝojis kaj ploris.","Ŝi iris, kaj sciigis ĝin al la homoj, kiuj estis kun li, dum ili malĝojis kaj ploris."],[16,11,"Kaj aŭdinte, ke li vivas kaj estas vidita de ŝi, ili ne kredis.","Kaj aŭdinte, ke li vivas kaj estas vidita de ŝi, ili ne kredis."],[16,12,"Kaj post tio li aperis sub alia formo al du el ili, dum ili piediris en la kamparon.","Kaj post tio li aperis sub alia formo al du el ili, dum ili piediris en la kamparon."],[16,13,"Kaj foririnte, ili sciigis al la aliaj, kaj ankaŭ ili ne kredis.","Kaj foririnte, ili sciigis al la aliaj, kaj ankaŭ ili ne kredis."],[16,14,"Poste li aperis al la dek unu, dum ili sidis ĉe manĝo, kaj riproĉis ilian nekredemon kaj korobstinon, ĉar ili ne kredis tiujn, kiuj vidis lin leviĝintan.","Poste li aperis al la dek unu, dum ili sidis ĉe manĝo, kaj riproĉis ilian nekredemon kaj korobstinon, ĉar ili ne kredis tiujn, kiuj vidis lin leviĝintan."],[16,15,"Kaj li diris al ili: Iru en la tutan mondon, kaj prediku la evangelion al ĉiu kreitaĵo.","Kaj li diris al ili: Iru en la tutan mondon, kaj prediku la evangelion al ĉiu kreitaĵo."],[16,16,"Kiu kredos kaj estos baptita, tiu estos savita; sed kiu ne kredos, tiu estos kondamnita.","Kiu kredos kaj estos baptita, tiu estos savita; sed kiu ne kredos, tiu estos kondamnita."],[16,17,"Kaj jenaj signoj sekvos la kredantojn: en mia nomo ili elpelos demonojn; ili parolos per lingvoj;","Kaj jenaj signoj sekvos la kredantojn: en mia nomo ili elpelos demonojn; ili parolos per lingvoj;"],[16,18,"ili prenos en manojn serpentojn, kaj se ili trinkos ion mortigan, ĝi neniel difektos ilin; sur malsanulojn ili metos la manojn, kaj ili saniĝos.","ili prenos en manojn serpentojn, kaj se ili trinkos ion mortigan, ĝi neniel difektos ilin; sur malsanulojn ili metos la manojn, kaj ili saniĝos."],[16,19,"Tiam la Sinjoro Jesuo, post kiam li parolis al ili, estis ricevita supren en la ĉielon, kaj sidiĝis dekstre de Dio.","Tiam la Sinjoro Jesuo, post kiam li parolis al ili, estis ricevita supren en la ĉielon, kaj sidiĝis dekstre de Dio."],[16,20,"Kaj elirinte, ili predikis ĉie, kaj la Sinjoro laboris kun ili kaj fortikigis la vorton per la signoj, kiuj sekvis. Amen.","Kaj elirinte, ili predikis ĉie, kaj la Sinjoro laboris kun ili kaj fortikigis la vorton per la signoj, kiuj sekvis. Amen."]]}};